def get_maturity_level_name(level):
    """Get human-readable name for maturity level"""
    names = {
        MaturityLevel.PASSIVE: "Passive - Reconnaissance only",
        MaturityLevel.LOW_SLOW: "Low & Slow - Idempotent payloads only",
        MaturityLevel.AGGRESSIVE: "Aggressive - Time-based SQLi, POST mutations",
        MaturityLevel.NUCLEAR: "Nuclear - Stacked queries, OOB, race conditions"
    }
    return names.get(level, "Unknown")

