# REQUEST DEDUPLICATION ENGINE
# ============================================================================

class RequestDeduplicator:
    """
    Advanced request deduplication to avoid redundant tests.
    Implements intelligent hashing and signature-based duplicate detection.
    """
    
    def __init__(self, config=None):
        self.config = config or {}
        self.enabled = self.config.get('request_deduplication_enabled', True)
        self.disabled_endpoints = self.config.get('disabled_endpoints', [])  # Endpoints to skip deduplication
        # Separate signature caches for crawl and active security tests
        self.crawl_signatures = OrderedDict()  # Crawl traffic signatures (aggressive deduplication)
        self.active_test_signatures = OrderedDict()  # Active test signatures (include mutations)
        self.response_signatures = OrderedDict()  # Store response signatures with LRU eviction
        self.dedup_stats = {
            'total_requests': 0,
            'crawl_duplicates_found': 0,
            'active_test_duplicates_found': 0,
            'unique_requests': 0,
            'cache_hits': 0
        }
        self.signature_cache = OrderedDict()
        self.max_cache_size = self.config.get('dedup_cache_size', 10000)
        self.body_truncation_size = self.config.get('body_truncation_size', 1000)  # Configurable truncation size
        
        if self.enabled:
            logging.info("Request deduplication engine initialized with separate policies for crawl and active tests")
    
    def generate_request_signature(self, method, url, headers=None, body=None, request_type='crawl', cookies=None):
        """
        Generate unique signature for HTTP request.
        
        Args:
            method: HTTP method
            url: Request URL
            headers: Request headers
            body: Request body
            request_type: 'crawl' for crawl traffic, 'active' for security tests
            cookies: Request cookies (optional, for security fix S21)
        
        For crawl requests: uses aggressive normalization (removes dynamic params/headers)
        For active test requests: includes mutated parameters and test context in signature
        
        Security fix (Issue S21): Include cookies in signature to prevent cross-session data leaks
        """
        if request_type == 'crawl':
            # Crawl traffic: aggressive normalization to deduplicate similar requests
            normalized_url = self._normalize_url(url)
            normalized_headers = self._normalize_headers(headers)
            normalized_body = self._normalize_body(body)
            # Include cookies in signature for crawl requests to prevent cross-session leaks
            normalized_cookies = self._normalize_cookies(cookies)
            signature_data = ":".join([method, normalized_url, normalized_headers, normalized_body, normalized_cookies])
        else:
            # Active security tests: include full parameters to distinguish mutations
            # Use URL with all parameters (no normalization for security-critical fields)
            normalized_url = url  # Keep full URL including mutated parameters
            normalized_headers = self._normalize_headers(headers)  # Still normalize headers
            # For body, include the full content to distinguish test mutations
            normalized_body = self._normalize_body_for_active_test(body)
            # Include cookies in signature for active tests to prevent cross-session leaks
            normalized_cookies = self._normalize_cookies(cookies)
            signature_data = ":".join([method, normalized_url, normalized_headers, normalized_body, normalized_cookies])
        
        signature = hashlib.sha256(signature_data.encode()).hexdigest()
        return signature
    
    def generate_response_signature(self, status, headers, body):
        """Generate unique signature for HTTP response"""
        # Normalize response (ignore dynamic headers like Date, Server)
        normalized_headers = self._normalize_response_headers(headers)
        
        # Create signature using join for better performance
        signature_data = ":".join([str(status), normalized_headers, body[:self.body_truncation_size]])  # Configurable truncation
        signature = hashlib.sha256(signature_data.encode()).hexdigest()
        
        return signature
    
    def _normalize_url(self, url):
        """Normalize URL for deduplication"""
        parsed = urlparse(url)
        
        # Remove query parameters that might be dynamic
        query_params = parse_qs(parsed.query)
        
        for param in DYNAMIC_QUERY_PARAMS:
            if param in query_params:
                del query_params[param]
        
        # Rebuild URL without dynamic parameters
        normalized = urlunparse((
            parsed.scheme,
            parsed.netloc.lower(),  # Normalize domain to lowercase
            parsed.path,
            parsed.params,
            urlencode(query_params, doseq=True),
            ''
        ))
        
        return normalized
    
    def _normalize_headers(self, headers):
        """Normalize HTTP headers for deduplication"""
        if not headers:
            return ""
        
        # Exclude dynamic headers
        exclude_headers = {
            'date', 'server', 'set-cookie', 'expires', 'etag', 'last-modified',
            'x-request-id', 'x-correlation-id', 'x-trace-id', 'request-id'
        }
        
        normalized = []
        for key, value in sorted(headers.items()):
            if key.lower() not in exclude_headers:
                normalized.append(f"{key.lower()}:{value}")
        
        return "|".join(normalized)
    
    def _normalize_response_headers(self, headers):
        """Normalize response headers for deduplication"""
        if not headers:
            return ""
        
        exclude_headers = {
            'date', 'server', 'set-cookie', 'expires', 'etag', 'last-modified',
            'x-request-id', 'x-correlation-id', 'x-trace-id', 'age', 'cache-control'
        }
        
        normalized = []
        for key, value in sorted(headers.items()):
            if key.lower() not in exclude_headers:
                normalized.append(f"{key.lower()}:{value}")
        
        return "|".join(normalized)
    
    def _normalize_body(self, body):
        """Normalize request body for deduplication (crawl traffic - aggressive normalization)"""
        if not body:
            return ""
        
        body_str = str(body)
        
        # Remove dynamic fields from JSON
        try:
            if body_str.startswith('{'):
                body_json = safe_json_loads(body_str, max_depth=100)
                for field in DYNAMIC_BODY_FIELDS:
                    if field in body_json:
                        body_json[field] = "REDACTED"
                return json.dumps(body_json, sort_keys=True)
        except (json.JSONDecodeError, ValueError, TypeError):
            pass
        
        return body_str[:self.body_truncation_size]  # Configurable truncation for non-JSON
    
    def _normalize_body_for_active_test(self, body):
        """
        Normalize request body for active security tests.
        Unlike crawl normalization, this preserves parameter values to distinguish test mutations.
        Only removes truly dynamic fields like timestamps/nonces.
        """
        if not body:
            return ""
        
        body_str = str(body)
        
        # For active tests, only remove truly dynamic fields (timestamps, nonces)
        # Keep all other parameters to distinguish security test mutations
        try:
            if body_str.startswith('{'):
                body_json = safe_json_loads(body_str, max_depth=100)
                # Only remove specific dynamic fields that are never security-relevant
                minimal_dynamic_fields = {'timestamp', 'nonce', '_csrf_token', 'csrf_token'}
                for field in minimal_dynamic_fields:
                    if field in body_json:
                        body_json[field] = "REDACTED"
                return json.dumps(body_json, sort_keys=True)
        except (json.JSONDecodeError, ValueError, TypeError):
            pass
        
        return body_str  # Return full body for active tests (no truncation)
    
    def _normalize_cookies(self, cookies):
        """
        Normalize cookies for deduplication (security fix S21).
        Includes cookies in signature to prevent cross-session data leaks.
        """
        if not cookies:
            return ""
        
        # Convert cookies to sorted key-value pairs
        normalized = []
        for key, value in sorted(cookies.items()):
            normalized.append(f"{key.lower()}:{value}")
        
        return "|".join(normalized)
    
    def _is_endpoint_disabled(self, url):
        """Check if URL matches any disabled endpoints"""
        if not self.disabled_endpoints:
            return False
        
        parsed = urlparse(url)
        path = parsed.path
        
        for disabled_endpoint in self.disabled_endpoints:
            if path.startswith(disabled_endpoint) or path == disabled_endpoint:
                return True
        
        return False
    
    def is_duplicate_request(self, method, url, headers=None, body=None, request_type='crawl', cookies=None):
        """
        Check if request is a duplicate.
        
        Args:
            method: HTTP method
            url: Request URL
            headers: Request headers
            body: Request body
            request_type: 'crawl' for crawl traffic, 'active' for security tests
            cookies: Request cookies (optional, for security fix S21)
        
        Uses separate signature caches for crawl vs active tests to prevent
        security mutations from being collapsed with baseline requests.
        
        Security fix (Issue S21): Include cookies in signature to prevent cross-session data leaks
        """
        if not self.enabled:
            return False
        
        # Skip deduplication for disabled endpoints
        if self._is_endpoint_disabled(url):
            logging.info(f"Deduplication disabled for endpoint: {url}")
            return False
        
        signature = self.generate_request_signature(method, url, headers, body, request_type, cookies)
        
        # Select appropriate signature cache based on request type
        if request_type == 'crawl':
            signature_cache = self.crawl_signatures
            duplicate_field = 'crawl_duplicates_found'
        else:
            signature_cache = self.active_test_signatures
            duplicate_field = 'active_test_duplicates_found'
        
        if signature in signature_cache:
            self.dedup_stats[duplicate_field] += 1
            self.dedup_stats['cache_hits'] += 1
            logging.info(f"Duplicate {request_type} request detected: {method} {url}")
            return True
        
        # Store new signature with LRU eviction
        if len(signature_cache) >= self.max_cache_size:
            signature_cache.popitem(last=False)
        
        signature_cache[signature] = {
            'method': method,
            'url': url,
            'timestamp': time.time()
        }
        
        # Also manage signature cache size
        if len(self.signature_cache) >= self.max_cache_size:
            self.signature_cache.popitem(last=False)
        
        self.signature_cache[signature] = True
        self.dedup_stats['total_requests'] += 1
        self.dedup_stats['unique_requests'] += 1
        
        return False
    
    def is_duplicate_response(self, status, headers, body):
        """Check if response is a duplicate (useful for detecting similar vulnerabilities)"""
        if not self.enabled:
            return False
        
        signature = self.generate_response_signature(status, headers, body)
        
        if signature in self.response_signatures:
            return True
        
        # Store new signature with LRU eviction
        if len(self.response_signatures) >= self.max_cache_size:
            self.response_signatures.popitem(last=False)
        
        self.response_signatures[signature] = {
            'status': status,
            'timestamp': time.time()
        }
        
        return False
    
    def get_statistics(self):
        """Get deduplication statistics"""
        total_duplicates = (self.dedup_stats['crawl_duplicates_found'] + 
                            self.dedup_stats['active_test_duplicates_found'])
        return {
            **self.dedup_stats,
            'deduplication_rate': (
                total_duplicates / max(self.dedup_stats['total_requests'], 1) * 100
            ),
            'cache_size': len(self.signature_cache),
            'crawl_signatures_count': len(self.crawl_signatures),
            'active_test_signatures_count': len(self.active_test_signatures),
            'response_signatures_count': len(self.response_signatures)
        }
    
    def clear_cache(self):
        """Clear deduplication cache"""
        self.crawl_signatures.clear()
        self.active_test_signatures.clear()
        self.response_signatures.clear()
        self.signature_cache.clear()
        self.dedup_stats = {
            'total_requests': 0,
            'crawl_duplicates_found': 0,
            'active_test_duplicates_found': 0,
            'unique_requests': 0,
            'cache_hits': 0
        }
        logging.info("Request deduplication cache cleared")


