# HTTP/2 AND HTTP/3 CLIENT SUPPORT
# ============================================================================

class HTTP2Client:
    """
    HTTP/2 client with advanced support for modern web protocols.
    Provides multi-stream multiplexing, header compression, and priority handling.
    Phase 1.4: Enhanced with aggressive multiplexing and connection pooling.
    Phase 1.5: Added httpx support for actual HTTP/2 negotiation via ALPN.
    
    Note: aiohttp does not support HTTP/2. This client uses httpx for HTTP/2 and
    aiohttp for HTTP/1.1 (which is faster than httpx for HTTP/1.1).
    """

    def __init__(self, config=None):
        self.config = config or {}
        self.enabled = self.config.get('http2_enabled', True)
        self.max_concurrent_streams = self.config.get('http2_max_streams', 200)  # Increased from 100
        self.session = None
        self.use_httpx = False  # Flag to indicate if using httpx for HTTP/2
        self.stream_priorities = {}
        self.stream_counter = 0
        self.connection_pool = {}  # Maintain persistent connections per host
        self.active_streams = {}  # Track active streams per host for load balancing
        self.stream_semaphore = {}  # Per-host semaphores for stream limiting

        # Determine if we can use actual HTTP/2
        if self.enabled:
            if HTTPX_AVAILABLE:
                self.use_httpx = True
                logging.info(f"HTTP/2 client initialized with httpx for actual HTTP/2 negotiation via ALPN ({self.max_concurrent_streams} max concurrent streams)")
            else:
                logging.warning(f"HTTP/2 client enabled but httpx is not available. Will use HTTP/1.1 only (aiohttp). Install httpx[http2] for actual HTTP/2 support.")
                self.enabled = False  # Disable HTTP/2 since it's not actually available
    
    async def _get_session(self, host):
        """Get or create HTTP/2 session for a specific host with enhanced connection pooling"""
        if host not in self.connection_pool or (hasattr(self.connection_pool[host], 'is_closed') and self.connection_pool[host].is_closed):
            # Always close stale session before overwrite to prevent resource leak
            if host in self.connection_pool:
                stale = self.connection_pool.pop(host)
                try:
                    if hasattr(stale, 'aclose'):
                        await stale.aclose()
                    else:
                        await stale.close()
                    logging.info(f"Closed stale HTTP/2 session for {host}")
                except Exception as e:
                    logging.error(f"Stale HTTP2 session close failed for {host}: {e}")

            # Create HTTP/2 enabled session with aggressive connection pooling (Phase 1.4)
            if self.use_httpx:
                # Use httpx for actual HTTP/2 support
                try:
                    limits = httpx.Limits(
                        max_keepalive_connections=self.max_concurrent_streams,
                        max_connections=self.max_concurrent_streams * 2,
                        keepalive_expiry=30
                    )
                    timeout = TIMEOUT_PROFILES['default'].to_httpx_timeout()
                    session = httpx.AsyncClient(
                        http2=True,
                        verify=True,
                        limits=limits,
                        timeout=timeout
                    )
                    logging.info(f"Created httpx HTTP/2 session for {host}")
                except Exception as e:
                    logging.error(f"Failed to create httpx HTTP/2 session for {host}: {e}", exc_info=True)
                    raise
            else:
                # Use aiohttp for HTTP/1.1 (faster than httpx for HTTP/1.1)
                connector = aiohttp.TCPConnector(
                    limit=self.max_concurrent_streams * 2,  # Double limit for better performance
                    limit_per_host=self.max_concurrent_streams,
                    force_close=False,
                    enable_cleanup_closed=True,
                    ttl_dns_cache=300,  # Cache DNS for 5 minutes
                    use_dns_cache=True,
                    keepalive_timeout=30  # Keep connections alive longer
                )

                # Configure session for HTTP/1.1 with optimized timeout
                timeout = TIMEOUT_PROFILES['default'].to_client_timeout()

                try:
                    session = aiohttp.ClientSession(
                        connector=connector,
                        timeout=timeout
                    )
                    logging.info(f"Created aiohttp HTTP/1.1 session for {host}")
                except (aiohttp.ClientError, ValueError) as e:
                    logging.error(f"Failed to create aiohttp ClientSession for {host}: {e}", exc_info=True)
                    raise

            self.connection_pool[host] = session
            self.active_streams[host] = 0
            self.stream_semaphore[host] = asyncio.Semaphore(self.max_concurrent_streams)

        return self.connection_pool[host]
    
    async def make_request(self, method, url, headers=None, body=None, priority=None, timeout=None):
        """Make HTTP/2 request with stream priority support - returns NormalizedResponse"""
        if not self.enabled:
            return None

        start_time = time.time()

        try:
            parsed = urlparse(url)
            host = parsed.netloc

            # Get HTTP/2 session for this host
            session = await self._get_session(host)

            # Set stream priority if specified
            stream_id = None
            if priority:
                self.stream_counter += 1
                stream_id = self.stream_counter
                self.stream_priorities[stream_id] = priority

            if self.use_httpx:
                # Use httpx for actual HTTP/2 support
                try:
                    # Handle dict body (JSON) properly
                    if isinstance(body, dict):
                        response = await session.request(
                            method, url,
                            headers=headers,
                            json=body,
                            timeout=timeout if timeout else TIMEOUT_PROFILES['default'].to_httpx_timeout()
                        )
                    else:
                        response = await session.request(
                            method, url,
                            headers=headers,
                            content=body,
                            timeout=timeout if timeout else TIMEOUT_PROFILES['default'].to_httpx_timeout()
                        )

                    elapsed = time.time() - start_time

                    # Check if HTTP/2 was actually used
                    actual_version = response.http_version
                    version_str = "HTTP/2" if actual_version == "HTTP/2" else actual_version

                    # Log protocol negotiation result
                    if self.config.get('http2_enabled', True) and actual_version != "HTTP/2":
                        logging.info(f"HTTP/2 requested but server negotiated {actual_version} for {url}")

                    # Convert to NormalizedResponse
                    result = to_normalized_response(response, url, elapsed)
                    # Add HTTP/2 specific metadata to headers
                    result.headers['x-http-version'] = version_str
                    result.headers['x-actual-protocol'] = actual_version
                    if stream_id:
                        result.headers['x-stream-id'] = str(stream_id)
                    return result
                except httpx.HTTPError as e:
                    logging.error(f"HTTP/2 request failed for {url}: {e}", exc_info=True)
                    return None
            else:
                # Use aiohttp for HTTP/1.1 (faster than httpx for HTTP/1.1)
                # Use provided timeout or default
                request_timeout = timeout if timeout is not None else TIMEOUT_PROFILES['default'].to_client_timeout()

                async with session.request(
                    method, url,
                    headers=headers,
                    data=body,
                    timeout=request_timeout
                ) as response:
                    elapsed = time.time() - start_time

                    # Check if HTTP/1.1 was used (aiohttp does not support HTTP/2)
                    actual_version = response.version
                    version_str = f"HTTP/{actual_version.major}.{actual_version.minor}"

                    # Convert to NormalizedResponse
                    result = to_normalized_response(response, url, elapsed)
                    # Add HTTP version metadata to headers
                    result.headers['x-http-version'] = version_str
                    result.headers['x-actual-protocol'] = version_str
                    if stream_id:
                        result.headers['x-stream-id'] = str(stream_id)
                    return result

        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            logging.error(f"HTTP/2 request failed for {url}: {e}", exc_info=True)
            return None
        except asyncio.CancelledError:
            logging.info(f"HTTP/2 request cancelled for {url}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error in HTTP/2 request for {url}: {e}", exc_info=True)
            return None
    
    async def make_multiplexed_requests(self, requests):
        """Make multiple HTTP/2 requests concurrently using enhanced stream multiplexing (Phase 1.4) - returns list of NormalizedResponse"""
        if not self.enabled:
            return []
        
        # Group requests by host for connection reuse
        requests_by_host = {}
        for req in requests:
            parsed = urlparse(req['url'])
            host = parsed.netloc
            if host not in requests_by_host:
                requests_by_host[host] = []
            requests_by_host[host].append(req)
        
        # Process each host's requests with connection reuse and stream limiting
        all_results = []
        for host, host_requests in requests_by_host.items():
            try:
                session = await self._get_session(host)
                semaphore = self.stream_semaphore.setdefault(host, asyncio.Semaphore(self.max_concurrent_streams))
                
                if self.use_httpx:
                    # Use httpx for actual HTTP/2 support
                    async def make_request_with_semaphore(req):
                        async with semaphore:
                            start_time = time.time()
                            body = req.get('body')
                            # Handle dict body (JSON) properly
                            if isinstance(body, dict):
                                response = await session.request(
                                    req.get('method', 'GET'),
                                    req['url'],
                                    headers=req.get('headers'),
                                    json=body,
                                    timeout=TIMEOUT_PROFILES['default'].to_httpx_timeout()
                                )
                            else:
                                response = await session.request(
                                    req.get('method', 'GET'),
                                    req['url'],
                                    headers=req.get('headers'),
                                    content=body,
                                    timeout=TIMEOUT_PROFILES['default'].to_httpx_timeout()
                                )
                            elapsed = time.time() - start_time
                            result = to_normalized_response(response, req['url'], elapsed)
                            result.headers['x-http-version'] = 'HTTP/2' if response.http_version == "HTTP/2" else response.http_version
                            return result
                else:
                    # Fallback to aiohttp (HTTP/1.1 only)
                    async def make_request_with_semaphore(req):
                        async with semaphore:
                            start_time = time.time()
                            response = await session.request(
                                req.get('method', 'GET'),
                                req['url'],
                                headers=req.get('headers'),
                                data=req.get('body'),
                                timeout=TIMEOUT_PROFILES['default'].to_client_timeout()
                            )
                            elapsed = time.time() - start_time
                            result = to_normalized_response(response, req['url'], elapsed)
                            result.headers['x-http-version'] = 'HTTP/2' if str(response.version) == "2.0" else str(response.version)
                            response.close()
                            return result
                
                tasks = [make_request_with_semaphore(req) for req in host_requests]
                
                # Execute all requests concurrently with controlled stream usage
                responses = await asyncio.gather(*tasks, return_exceptions=True)
                
                # Process responses
                for i, response in enumerate(responses):
                    if isinstance(response, Exception):
                        # Return error as dict for backward compatibility
                        all_results.append({ 'error': str(response), 'url': host_requests[i]['url'] })
                    else:
                        all_results.append(response)
            except (aiohttp.ClientError, asyncio.TimeoutError, asyncio.CancelledError, httpx.HTTPError) as e:
                logging.error(f"HTTP/2 multiplexed requests failed for {host}: {e}")
                for req in host_requests:
                    all_results.append({ 'error': str(e), 'url': req['url'] })
        
        return all_results
    
    async def close(self):
        """Close all HTTP/2 sessions and cleanup resources (Phase 1.4)"""
        for host, session in self.connection_pool.items():
            try:
                is_closed = session.is_closed if hasattr(session, 'is_closed') else session.closed
                if not is_closed:
                    if hasattr(session, 'aclose'):
                        await session.aclose()
                    else:
                        await session.close()
            except (aiohttp.ClientError, asyncio.CancelledError, Exception) as e:
                logging.error(f"Error closing HTTP/2 session for {host}: {e}")
        self.connection_pool.clear()
        self.active_streams.clear()
        self.stream_semaphore.clear()
        logging.info("HTTP/2 client sessions closed")


class HTTP3Client:
    """
    HTTP/3 client with QUIC protocol support.
    Provides UDP-based transport with improved performance and security.
    Uses aioquic for actual QUIC implementation.
    """
    
    def __init__(self, config=None):
        self.config = config or {}
        self.enabled = self.config.get('http3_enabled', False)
        self.session = None
        self.quic_available = False
        self.aioquic_available = False
        self.verify_ssl = self.config.get('verify_ssl', True)  # Default to secure SSL verification
        
        if self.enabled:
            try:
                # Try to import aioquic for actual QUIC implementation
                from aioquic.asyncio import QuicConnectionProtocol
                from aioquic.quic.configuration import QuicConfiguration
                from aioquic.h3.connection import H3Connection
                from aioquic.h3.events import H3Event, HeadersReceived, DataReceived, EndStreamReceived
                import aioquic.h3.connection as h3_connection
                
                self.QuicConnectionProtocol = QuicConnectionProtocol
                self.QuicConfiguration = QuicConfiguration
                self.H3Connection = H3Connection
                self.H3Event = H3Event
                self.HeadersReceived = HeadersReceived
                self.DataReceived = DataReceived
                self.EndStreamReceived = EndStreamReceived
                self.aioquic_available = True
                self.quic_available = True
                
                # Create QUIC configuration
                self.quic_config = QuicConfiguration(
                    is_client=True,
                    alpn_protocols=["h3-29", "h3-28", "h3-27"],
                    max_data=2**24,
                    max_stream_data=2**23,
                )
                
                # Configure SSL verification based on settings
                if not self.verify_ssl or DISABLE_SSL_VERIFICATION:
                    self.quic_config.verify_mode = ssl.CERT_NONE
                    logging.error("SSL certificate verification DISABLED for HTTP/3 - only use for authorized scanning")
                else:
                    self.quic_config.verify_mode = ssl.CERT_REQUIRED
                    logging.info("SSL certificate verification ENABLED for HTTP/3")
                
                logging.info("HTTP/3 client initialized with aioquic QUIC support")
            except ImportError:
                self.quic_available = False
                logging.info("HTTP/3 requested but aioquic not available, falling back to HTTP/2")
            except (ssl.SSLError, AttributeError, ValueError) as e:
                self.quic_available = False
                logging.error(f"HTTP/3 initialization failed: {e}")
    
    async def make_request(self, method, url, headers=None, body=None):
        """Make HTTP/3 request using QUIC protocol - returns NormalizedResponse"""
        if not self.enabled or not self.quic_available or not self.aioquic_available:
            return None
        
        start_time = time.time()
        
        try:
            parsed = urlparse(url)
            host = parsed.hostname
            port = parsed.port or (443 if parsed.scheme == 'https' else 80)
            path = parsed.path or '/'
            if parsed.query:
                path += '?' + parsed.query
            
            # Create QUIC connection
            import asyncio
            from aioquic.asyncio import connect
            
            # Set up event loop for QUIC
            loop = get_loop()
            
            # Create QUIC connection
            async with connect(
                host,
                port,
                configuration=self.quic_config,
                create_protocol=self.QuicConnectionProtocol,
            ) as protocol:
                # Get the QUIC connection
                quic = protocol.quic
                
                # Create HTTP/3 connection
                http = self.H3Connection(quic)
                
                # Prepare headers
                request_headers = [
                    (b":method", method.encode()),
                    (b":path", path.encode()),
                    (b":scheme", parsed.scheme.encode()),
                    (b":authority", f"{host}:{port}".encode()),
                    (b"user-agent", b"ULTRA-DAST-HTTP3-Scanner"),
                ]
                
                # Add custom headers
                if headers:
                    for key, value in headers.items():
                        request_headers.append((key.lower().encode(), str(value).encode()))
                
                # Send request
                stream_id = quic.get_next_available_stream_id()
                http.send_headers(stream_id, request_headers, end_stream=not body)
                
                # Send body if present
                if body:
                    if isinstance(body, str):
                        body = body.encode()
                    http.send_data(stream_id, body, end_stream=True)
                
                # Receive response
                response_headers = None
                response_data = b""
                end_stream = False
                
                while not end_stream:
                    # Wait for QUIC events
                    await protocol.wait_event()
                    
                    # Process HTTP/3 events
                    for event in http.handle_input(quic.pending_stream_data):
                        if isinstance(event, self.HeadersReceived):
                            response_headers = dict(event.headers)
                        elif isinstance(event, self.DataReceived):
                            response_data += event.data
                        elif isinstance(event, self.EndStreamReceived):
                            end_stream = True
                
                # Parse response
                status_code = int(response_headers.get(b":status", b"500"))
                response_headers_dict = {}
                for key, value in response_headers.items():
                    if not key.startswith(b":"):
                        response_headers_dict[key.decode('utf-8', errors='ignore') if key else ''] = value.decode('utf-8', errors='ignore') if value else ''

                elapsed = time.time() - start_time
                text = response_data.decode('utf-8', errors='ignore') if response_data else ''
                
                # Create NormalizedResponse
                result = NormalizedResponse(
                    status=status_code,
                    headers=response_headers_dict,
                    cookies={},
                    body=response_data,
                    text=text,
                    url=url,
                    elapsed=elapsed
                )
                
                # Add HTTP/3 specific metadata
                result.headers['x-http-version'] = 'HTTP/3'
                result.headers['x-protocol'] = 'QUIC'
                
                return result
                    
        except (asyncio.TimeoutError, ssl.SSLError, ConnectionError, asyncio.CancelledError) as e:
            logging.error(f"HTTP/3 request failed: {e}")
            return None
    
    def is_available(self):
        """Check if HTTP/3 support is available"""
        return self.enabled and self.quic_available and self.aioquic_available


