# Timeout profiles for consistent timeout management across the scanner
from dataclasses import dataclass
from typing import Optional

@dataclass
class TimeoutProfile:
    """Unified timeout configuration for HTTP requests"""
    total: float
    connect: float
    sock_read: float
    
    def to_client_timeout(self) -> ClientTimeout:
        """Convert to aiohttp ClientTimeout"""
        return ClientTimeout(total=self.total, connect=self.connect, sock_read=self.sock_read)
    
    def to_httpx_timeout(self) -> Optional['httpx.Timeout']:
        """Convert to httpx.Timeout if httpx is available"""
        try:
            import httpx
            return httpx.Timeout(connect=self.connect, read=self.sock_read, write=10.0, pool=5.0)
        except ImportError:
            return None

# Predefined timeout profiles for different use cases
TIMEOUT_PROFILES = {
    'fast': TimeoutProfile(total=10, connect=5, sock_read=8),
    'default': TimeoutProfile(total=30, connect=10, sock_read=20),
    'slow': TimeoutProfile(total=90, connect=15, sock_read=60),
    'oob': TimeoutProfile(total=180, connect=15, sock_read=120),
    'health_check': TimeoutProfile(total=30, connect=10, sock_read=20),
    'probe': TimeoutProfile(total=60, connect=15, sock_read=45),
}

# Phase 2: Network optimization constants
DNS_CACHE_TTL = 300  # 5 minutes DNS cache
DNS_CACHE_MAX_SIZE = 1000  # Maximum number of DNS entries to cache
CONNECTION_POOL_SIZE = 100  # Increased connection pool size
SSL_SESSION_CACHE_SIZE = 50  # SSL session cache size

# Phase 2: Simple DNS cache implementation with size limit
_dns_cache = {}
_dns_cache_lock = threading.Lock()

def get_dns_cache(host: str) -> Optional[str]:
    """Get cached DNS resolution for host."""
    with _dns_cache_lock:
        if host in _dns_cache:
            entry = _dns_cache[host]
            if time.time() - entry['timestamp'] < DNS_CACHE_TTL:
                return entry['ip']
            else:
                del _dns_cache[host]
    return None

def set_dns_cache(host: str, ip: str) -> None:
    """Cache DNS resolution for host with size limit."""
    with _dns_cache_lock:
        # Evict oldest entry if cache is full
        if len(_dns_cache) >= DNS_CACHE_MAX_SIZE and host not in _dns_cache:
            # Remove oldest entry based on timestamp
            oldest_host = min(_dns_cache.keys(), key=lambda k: _dns_cache[k]['timestamp'])
            del _dns_cache[oldest_host]
        _dns_cache[host] = {'ip': ip, 'timestamp': time.time()}

def clear_dns_cache() -> None:
    """Clear DNS cache."""
    with _dns_cache_lock:
        _dns_cache.clear()

# Phase 4: Memoization cache for expensive operations with size limit
MEMOIZATION_CACHE_MAX_SIZE = 5000  # Maximum number of memoized results
_memoization_cache = {}
_memoization_lock = threading.Lock()

def memoize_result(func_key: str, args_key: str, result: Any, ttl: int = 300) -> None:
    """Memoize function result with TTL and size limit."""
    with _memoization_lock:
        cache_key = (func_key, args_key)
        # Evict oldest entry if cache is full
        if len(_memoization_cache) >= MEMOIZATION_CACHE_MAX_SIZE and cache_key not in _memoization_cache:
            # Remove oldest entry based on timestamp
            oldest_key = min(_memoization_cache.keys(), key=lambda k: _memoization_cache[k]['timestamp'])
            del _memoization_cache[oldest_key]
        _memoization_cache[cache_key] = {
            'result': result,
            'timestamp': time.time(),
            'ttl': ttl
        }

def get_memoized_result(func_key: str, args_key: str) -> Optional[Any]:
    """Get memoized result if available and not expired."""
    with _memoization_lock:
        cache_key = (func_key, args_key)
        if cache_key in _memoization_cache:
            entry = _memoization_cache[cache_key]
            if time.time() - entry['timestamp'] < entry['ttl']:
                return entry['result']
            else:
                del _memoization_cache[cache_key]
    return None

def clear_memoization_cache() -> None:
    """Clear memoization cache."""
    with _memoization_lock:
        _memoization_cache.clear()

