def apply_performance_profile(config, profile_name="balanced"):
    """
    Apply a performance profile to the configuration.
    
    Args:
        config: Dictionary containing configuration values
        profile_name: Name of the performance profile to apply (balanced, fast, thorough, turbo, stealth-turbo, adaptive, resource-limited-turbo)
        
    Returns:
        dict: Updated configuration with profile settings applied
    """
    if profile_name not in PERFORMANCE_PROFILES:
        logging.error(f"Unknown performance profile '{profile_name}', using 'balanced'")
        profile_name = "balanced"
    
    profile = PERFORMANCE_PROFILES[profile_name]
    updated_config = config.copy()
    
    # Apply profile settings, but don't override explicit user settings
    for key, value in profile.items():
        if key not in updated_config:
            updated_config[key] = value
    
    logging.info(f"Applied performance profile: {profile_name}")
    return updated_config

# Configuration validation
def validate_config(config):
    """
    Validate configuration values and provide clear error messages.
    
    Args:
        config: Dictionary containing configuration values
        
    Returns:
        tuple: (is_valid, error_messages)
    """
    errors = []
    
    # Validate numeric ranges
    if 'depth' in config:
        if not isinstance(config['depth'], int) or config['depth'] < 1 or config['depth'] > 10:
            errors.append("depth must be an integer between 1 and 10")
    
    if 'threads' in config:
        if not isinstance(config['threads'], int) or config['threads'] < 1 or config['threads'] > 1000:
            errors.append("threads must be an integer between 1 and 1000")
    
    if 'delay' in config:
        if not isinstance(config['delay'], (int, float)) or config['delay'] < 0:
            errors.append("delay must be a non-negative number")
    
    # Validate timeout values
    if 'request_timeout' in config:
        if not isinstance(config['request_timeout'], (int, float)) or config['request_timeout'] < 1:
            errors.append("request_timeout must be a positive number")
    
    # Validate performance profile
    if 'performance_profile' in config:
        valid_profiles = list(PERFORMANCE_PROFILES.keys())
        profile = config.get('performance_profile')
        if not isinstance(profile, str):
            errors.append("performance_profile must be a string")
        elif profile not in valid_profiles:
            errors.append(f"performance_profile must be one of {valid_profiles}")
    
    # Validate crawl concurrency
    if 'crawl_concurrency' in config:
        if not isinstance(config['crawl_concurrency'], int) or config['crawl_concurrency'] < 1 or config['crawl_concurrency'] > 100:
            errors.append("crawl_concurrency must be an integer between 1 and 100")
    
    # Validate pagination configuration
    if 'pagination_enabled' in config:
        if not isinstance(config['pagination_enabled'], bool):
            errors.append("pagination_enabled must be a boolean value")
    
    if 'pagination_max_pages' in config:
        if not isinstance(config['pagination_max_pages'], int) or config['pagination_max_pages'] < 1 or config['pagination_max_pages'] > 50:
            errors.append("pagination_max_pages must be an integer between 1 and 50")
    
    if 'pagination_max_scrolls' in config:
        if not isinstance(config['pagination_max_scrolls'], int) or config['pagination_max_scrolls'] < 1 or config['pagination_max_scrolls'] > 10:
            errors.append("pagination_max_scrolls must be an integer between 1 and 10")
    
    if 'pagination_scroll_delay' in config:
        if not isinstance(config['pagination_scroll_delay'], (int, float)) or config['pagination_scroll_delay'] < 0.1 or config['pagination_scroll_delay'] > 10:
            errors.append("pagination_scroll_delay must be a number between 0.1 and 10")
    
    # Validate log level
    if 'log_level' in config:
        valid_log_levels = ['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL']
        log_level = config.get('log_level')
        if not isinstance(log_level, str):
            errors.append("log_level must be a string")
        elif log_level.upper() not in valid_log_levels:
            errors.append(f"log_level must be one of {valid_log_levels}")
    
    # Validate cache configuration
    if 'dedup_cache_size' in config:
        if not isinstance(config['dedup_cache_size'], int) or config['dedup_cache_size'] < 100:
            errors.append("dedup_cache_size must be an integer >= 100")
    
    if 'body_truncation_size' in config:
        if not isinstance(config['body_truncation_size'], int) or config['body_truncation_size'] < 100:
            errors.append("body_truncation_size must be an integer >= 100")
    
    # Validate rate limiting
    if 'verification_rate_limit' in config:
        if not isinstance(config['verification_rate_limit'], (int, float)) or config['verification_rate_limit'] < 0.1:
            errors.append("verification_rate_limit must be >= 0.1")
    
    if 'discovery_rate_limit' in config:
        if not isinstance(config['discovery_rate_limit'], (int, float)) or config['discovery_rate_limit'] < 0.1:
            errors.append("discovery_rate_limit must be >= 0.1")
    
    # Validate HTTP/2 downgrade page limit
    if 'http2_downgrade_page_limit' in config:
        if not isinstance(config['http2_downgrade_page_limit'], int) or config['http2_downgrade_page_limit'] < 1 or config['http2_downgrade_page_limit'] > 50:
            errors.append("http2_downgrade_page_limit must be an integer between 1 and 50")

    # Validate HTTP/2 rapid reset streams
    if 'http2_rapid_reset_streams' in config:
        if not isinstance(config['http2_rapid_reset_streams'], int) or config['http2_rapid_reset_streams'] < 10 or config['http2_rapid_reset_streams'] > 1000:
            errors.append("http2_rapid_reset_streams must be an integer between 10 and 1000")

    # Validate boolean flags
    boolean_fields = ['http2_enabled', 'http3_enabled', 'verify_ssl', 'request_deduplication_enabled']
    for field in boolean_fields:
        if field in config and not isinstance(config[field], bool):
            errors.append(f"{field} must be a boolean value")
    
    # Validate race condition engine configuration (Issue T6 fix)
    race_boolean_fields = ['race_http1_enabled', 'race_http2_enabled']
    for field in race_boolean_fields:
        if field in config and not isinstance(config[field], bool):
            errors.append(f"{field} must be a boolean value")
    
    if 'race_max_concurrent' in config:
        if not isinstance(config['race_max_concurrent'], int) or config['race_max_concurrent'] < 1 or config['race_max_concurrent'] > 1000:
            errors.append("race_max_concurrent must be an integer between 1 and 1000")
    
    if 'race_sync_timeout' in config:
        if not isinstance(config['race_sync_timeout'], (int, float)) or config['race_sync_timeout'] < 1 or config['race_sync_timeout'] > 300:
            errors.append("race_sync_timeout must be a number between 1 and 300")
    
    # Validate maturity_level
    if 'maturity_level' in config:
        if not isinstance(config['maturity_level'], int) or config['maturity_level'] not in [level.value for level in MaturityLevel]:
            errors.append(f"maturity_level must be one of {[level.value for level in MaturityLevel]}")
    
    # Validate boolean safety flags
    safety_boolean_fields = ['dry_run', 'auto_resume', 'disable_circuit_breaker', 'enable_multiprocessing', 'enable_control_payloads', 'enable_service_detection']
    for field in safety_boolean_fields:
        if field in config and not isinstance(config[field], bool):
            errors.append(f"{field} must be a boolean value")

    # Validate port scanning configuration
    if 'max_concurrent_ports' in config:
        if not isinstance(config['max_concurrent_ports'], int) or config['max_concurrent_ports'] < 1 or config['max_concurrent_ports'] > 10000:
            errors.append("max_concurrent_ports must be an integer between 1 and 10000")
    
    # Validate control_payload_threshold
    if 'control_payload_threshold' in config:
        if not isinstance(config['control_payload_threshold'], (int, float)):
            errors.append("control_payload_threshold must be a number")
        elif config['control_payload_threshold'] < 0 or config['control_payload_threshold'] > 1:
            errors.append("control_payload_threshold must be between 0 and 1")
    
    # Validate enable_advanced_oob
    if 'enable_advanced_oob' in config:
        if not isinstance(config['enable_advanced_oob'], bool):
            errors.append("enable_advanced_oob must be a boolean value")
        elif config['enable_advanced_oob']:
            # Validate OOB configuration when enabled
            if 'oob_ip' in config:
                oob_ip = config['oob_ip']
                if not isinstance(oob_ip, str):
                    errors.append("oob_ip must be a string")
                elif oob_ip in ['127.0.0.1', 'localhost', '::1']:
                    errors.append("oob_ip cannot be a loopback address when enable_advanced_oob is true")

    # Validate use_external_oob
    if 'use_external_oob' in config:
        if not isinstance(config['use_external_oob'], bool):
            errors.append("use_external_oob must be a boolean value")
        elif config['use_external_oob']:
            # Validate external OOB service configuration when enabled
            has_external_oob_url = 'external_oob_url' in config and config['external_oob_url']
            has_interactsh_server = 'interactsh_server' in config and config['interactsh_server']
            
            if not has_external_oob_url and not has_interactsh_server:
                errors.append("use_external_oob requires either external_oob_url or interactsh_server to be configured")
            
            # Validate external_oob_url if provided
            if has_external_oob_url:
                external_oob_url = config['external_oob_url']
                if not isinstance(external_oob_url, str):
                    errors.append("external_oob_url must be a string")
                else:
                    # Basic URL validation
                    try:
                        parsed = urlparse(external_oob_url)
                        if not parsed.scheme or not parsed.netloc:
                            errors.append("external_oob_url must be a valid URL with scheme and host")
                    except Exception:
                        errors.append("external_oob_url must be a valid URL")
            
            # Validate interactsh_server if provided
            if has_interactsh_server:
                interactsh_server = config['interactsh_server']
                if not isinstance(interactsh_server, str):
                    errors.append("interactsh_server must be a string")
                else:
                    # Basic URL validation
                    try:
                        parsed = urlparse(interactsh_server)
                        if not parsed.scheme or not parsed.netloc:
                            errors.append("interactsh_server must be a valid URL with scheme and host")
                    except Exception:
                        errors.append("interactsh_server must be a valid URL")
    
    # Validate Gray Zone handling configuration
    if 'gray_zone_handling' in config:
        gray_zone_config = config['gray_zone_handling']
        if not isinstance(gray_zone_config, dict):
            errors.append("gray_zone_handling must be a dictionary")
        else:
            if 'enabled' in gray_zone_config and not isinstance(gray_zone_config['enabled'], bool):
                errors.append("gray_zone_handling.enabled must be a boolean value")
            if 'manual_verification_enabled' in gray_zone_config and not isinstance(gray_zone_config['manual_verification_enabled'], bool):
                errors.append("gray_zone_handling.manual_verification_enabled must be a boolean value")

    # Validate deserialization detection configuration (Issue U28 fix)
    if 'deserialization_detection' in config:
        deserial_config = config['deserialization_detection']
        if not isinstance(deserial_config, dict):
            errors.append("deserialization_detection must be a dictionary")
        else:
            if 'enabled' in deserial_config and not isinstance(deserial_config['enabled'], bool):
                errors.append("deserialization_detection.enabled must be a boolean value")
            if 'auto_detect_frameworks' in deserial_config and not isinstance(deserial_config['auto_detect_frameworks'], bool):
                errors.append("deserialization_detection.auto_detect_frameworks must be a boolean value")
            if 'framework_specific_payloads' in deserial_config and not isinstance(deserial_config['framework_specific_payloads'], bool):
                errors.append("deserialization_detection.framework_specific_payloads must be a boolean value")
            # Validate tool paths if provided
            for tool_path in ['ysoserial_path', 'phpggc_path', 'ysoserial_net_path']:
                if tool_path in deserial_config:
                    path = deserial_config[tool_path]
                    if not isinstance(path, str):
                        errors.append(f"deserialization_detection.{tool_path} must be a string")
                    elif path and not os.path.exists(path):
                        logging.warning(f"deserialization_detection.{tool_path} path does not exist: {path}")
            if 'resend_count' in gray_zone_config:
                if not isinstance(gray_zone_config['resend_count'], int) or gray_zone_config['resend_count'] < 1 or gray_zone_config['resend_count'] > 100:
                    errors.append("gray_zone_handling.resend_count must be an integer between 1 and 100")
            if 'error_500_discard_threshold' in gray_zone_config:
                if not isinstance(gray_zone_config['error_500_discard_threshold'], int) or gray_zone_config['error_500_discard_threshold'] < 0 or gray_zone_config['error_500_discard_threshold'] > 10:
                    errors.append("gray_zone_handling.error_500_discard_threshold must be an integer between 0 and 10")
            if 'error_500_accept_threshold' in gray_zone_config:
                if not isinstance(gray_zone_config['error_500_accept_threshold'], int) or gray_zone_config['error_500_accept_threshold'] < 0 or gray_zone_config['error_500_accept_threshold'] > 10:
                    errors.append("gray_zone_handling.error_500_accept_threshold must be an integer between 0 and 10")
            if 'auto_process_on_scan_complete' in gray_zone_config and not isinstance(gray_zone_config['auto_process_on_scan_complete'], bool):
                errors.append("gray_zone_handling.auto_process_on_scan_complete must be a boolean value")
            if 'concurrent_limit' in gray_zone_config:
                if not isinstance(gray_zone_config['concurrent_limit'], int) or gray_zone_config['concurrent_limit'] < 1 or gray_zone_config['concurrent_limit'] > 10:
                    errors.append("gray_zone_handling.concurrent_limit must be an integer between 1 and 10")
            if 'rate_limit_per_second' in gray_zone_config:
                if not isinstance(gray_zone_config['rate_limit_per_second'], (int, float)) or gray_zone_config['rate_limit_per_second'] < 0.1 or gray_zone_config['rate_limit_per_second'] > 50:
                    errors.append("gray_zone_handling.rate_limit_per_second must be a number between 0.1 and 50")
            if 'burst_capacity' in gray_zone_config:
                if not isinstance(gray_zone_config['burst_capacity'], int) or gray_zone_config['burst_capacity'] < 1 or gray_zone_config['burst_capacity'] > 100:
                    errors.append("gray_zone_handling.burst_capacity must be an integer between 1 and 100")
    
    # Validate FSM stuck detection configuration
    if 'fsm_stuck_detection' in config:
        fsm_config = config['fsm_stuck_detection']
        if not isinstance(fsm_config, dict):
            errors.append("fsm_stuck_detection must be a dictionary")
        else:
            if 'enabled' in fsm_config and not isinstance(fsm_config['enabled'], bool):
                errors.append("fsm_stuck_detection.enabled must be a boolean value")
            if 'stuck_timeout' in fsm_config:
                if not isinstance(fsm_config['stuck_timeout'], int) or fsm_config['stuck_timeout'] < 10 or fsm_config['stuck_timeout'] > 120:
                    errors.append("fsm_stuck_detection.stuck_timeout must be an integer between 10 and 120 seconds (adaptive timeout default fallback)")
            if 'enable_manual_navigation_guidance' in fsm_config and not isinstance(fsm_config['enable_manual_navigation_guidance'], bool):
                errors.append("fsm_stuck_detection.enable_manual_navigation_guidance must be a boolean value")
    
    # Validate Stealth Mode configuration
    if 'stealth_mode' in config:
        stealth_config = config['stealth_mode']
        if not isinstance(stealth_config, dict):
            errors.append("stealth_mode must be a dictionary")
        else:
            if 'enabled' in stealth_config and not isinstance(stealth_config['enabled'], bool):
                errors.append("stealth_mode.enabled must be a boolean value")
            if 'window_hours' in stealth_config:
                if not isinstance(stealth_config['window_hours'], (int, float)) or stealth_config['window_hours'] < 1 or stealth_config['window_hours'] > 168:
                    errors.append("stealth_mode.window_hours must be a number between 1 and 168 hours (1 week)")
            if 'requests_per_window' in stealth_config:
                if not isinstance(stealth_config['requests_per_window'], int) or stealth_config['requests_per_window'] < 1:
                    errors.append("stealth_mode.requests_per_window must be a positive integer")
            if 'jitter_percentage' in stealth_config:
                if not isinstance(stealth_config['jitter_percentage'], (int, float)) or stealth_config['jitter_percentage'] < 0 or stealth_config['jitter_percentage'] > 50:
                    errors.append("stealth_mode.jitter_percentage must be a number between 0 and 50")
            if 'state_file' in stealth_config and not isinstance(stealth_config['state_file'], str):
                errors.append("stealth_mode.state_file must be a string")
    
    # Validate proxy_pool configuration
    if 'proxy_pool' in config:
        proxy_config = config['proxy_pool']
        if not isinstance(proxy_config, dict):
            errors.append("proxy_pool must be a dictionary")
        else:
            if 'enable_rotation' in proxy_config and not isinstance(proxy_config['enable_rotation'], bool):
                errors.append("proxy_pool.enable_rotation must be a boolean value")
            if 'rotation_interval' in proxy_config:
                if not isinstance(proxy_config['rotation_interval'], int) or proxy_config['rotation_interval'] < 1:
                    errors.append("proxy_pool.rotation_interval must be a positive integer")
            if 'health_check_interval' in proxy_config:
                if not isinstance(proxy_config['health_check_interval'], int) or proxy_config['health_check_interval'] < 1:
                    errors.append("proxy_pool.health_check_interval must be a positive integer")
            if 'prefer_geo_diverse' in proxy_config and not isinstance(proxy_config['prefer_geo_diverse'], bool):
                errors.append("proxy_pool.prefer_geo_diverse must be a boolean value")
            if 'max_failure_rate' in proxy_config:
                if not isinstance(proxy_config['max_failure_rate'], (int, float)) or proxy_config['max_failure_rate'] < 0 or proxy_config['max_failure_rate'] > 1:
                    errors.append("proxy_pool.max_failure_rate must be a number between 0 and 1")
            if 'auto_healing_enabled' in proxy_config and not isinstance(proxy_config['auto_healing_enabled'], bool):
                errors.append("proxy_pool.auto_healing_enabled must be a boolean value")
            if 'sticky_session_enabled' in proxy_config and not isinstance(proxy_config['sticky_session_enabled'], bool):
                errors.append("proxy_pool.sticky_session_enabled must be a boolean value")
            if 'sticky_session_duration' in proxy_config:
                if not isinstance(proxy_config['sticky_session_duration'], int) or proxy_config['sticky_session_duration'] < 1:
                    errors.append("proxy_pool.sticky_session_duration must be a positive integer")
            if 'state_file' in proxy_config and not isinstance(proxy_config['state_file'], str):
                errors.append("proxy_pool.state_file must be a string")
    
    # Validate Bayesian confidence configuration (Issue C19)
    if 'bayesian_confidence' in config:
        bayesian_config = config['bayesian_confidence']
        if not isinstance(bayesian_config, dict):
            errors.append("bayesian_confidence must be a dictionary")
        else:
            # Validate validation likelihood ratios
            validation_types = ['validation_1_original', 'validation_2_alternative', 'validation_3_manual']
            for vtype in validation_types:
                if vtype in bayesian_config:
                    vconfig = bayesian_config[vtype]
                    if not isinstance(vconfig, dict):
                        errors.append(f"bayesian_confidence.{vtype} must be a dictionary")
                    else:
                        # Validate likelihood ratios are positive numbers
                        for outcome in ['passed', 'failed', 'inconclusive']:
                            if outcome in vconfig:
                                if not isinstance(vconfig[outcome], (int, float)) or vconfig[outcome] <= 0:
                                    errors.append(f"bayesian_confidence.{vtype}.{outcome} must be a positive number")
            
            # Validate remediation test likelihood ratios
            if 'remediation_test' in bayesian_config:
                rt_config = bayesian_config['remediation_test']
                if not isinstance(rt_config, dict):
                    errors.append("bayesian_confidence.remediation_test must be a dictionary")
                else:
                    for outcome in ['critical', 'high', 'medium', 'low', 'error']:
                        if outcome in rt_config:
                            if not isinstance(rt_config[outcome], (int, float)) or rt_config[outcome] <= 0:
                                errors.append(f"bayesian_confidence.remediation_test.{outcome} must be a positive number")
            
            # Validate prior confidence
            if 'prior_confidence' in bayesian_config:
                if not isinstance(bayesian_config['prior_confidence'], (int, float)) or bayesian_config['prior_confidence'] < 0 or bayesian_config['prior_confidence'] > 1:
                    errors.append("bayesian_confidence.prior_confidence must be a number between 0 and 1")
            
            # Validate confidence floor and cap
            if 'confidence_floor' in bayesian_config:
                if not isinstance(bayesian_config['confidence_floor'], int) or bayesian_config['confidence_floor'] < 0 or bayesian_config['confidence_floor'] > 100:
                    errors.append("bayesian_confidence.confidence_floor must be an integer between 0 and 100")
            
            if 'confidence_cap' in bayesian_config:
                if not isinstance(bayesian_config['confidence_cap'], int) or bayesian_config['confidence_cap'] < 0 or bayesian_config['confidence_cap'] > 100:
                    errors.append("bayesian_confidence.confidence_cap must be an integer between 0 and 100")
            
            # Ensure floor < cap
            if 'confidence_floor' in bayesian_config and 'confidence_cap' in bayesian_config:
                if bayesian_config['confidence_floor'] >= bayesian_config['confidence_cap']:
                    errors.append("bayesian_confidence.confidence_floor must be less than confidence_cap")

    # Validate race Bayesian configuration (Issue C20)
    if 'race_bayesian' in config:
        race_config = config['race_bayesian']
        if not isinstance(race_config, dict):
            errors.append("race_bayesian must be a dictionary")
        else:
            # Validate persistence confirmed likelihood ratios
            if 'persistence_confirmed' in race_config:
                pc_config = race_config['persistence_confirmed']
                if not isinstance(pc_config, dict):
                    errors.append("race_bayesian.persistence_confirmed must be a dictionary")
                else:
                    for outcome in ['confirmed', 'not_confirmed', 'unknown']:
                        if outcome in pc_config:
                            if not isinstance(pc_config[outcome], (int, float)) or pc_config[outcome] <= 0:
                                errors.append(f"race_bayesian.persistence_confirmed.{outcome} must be a positive number")

            # Validate timing distribution likelihood ratios
            if 'timing_distribution' in race_config:
                td_config = race_config['timing_distribution']
                if not isinstance(td_config, dict):
                    errors.append("race_bayesian.timing_distribution must be a dictionary")
                else:
                    for outcome in ['bimodal', 'unimodal_success', 'unimodal_failure', 'flat']:
                        if outcome in td_config:
                            if not isinstance(td_config[outcome], (int, float)) or td_config[outcome] <= 0:
                                errors.append(f"race_bayesian.timing_distribution.{outcome} must be a positive number")

            # Validate race success rate likelihood ratios
            if 'race_success_rate' in race_config:
                rsr_config = race_config['race_success_rate']
                if not isinstance(rsr_config, dict):
                    errors.append("race_bayesian.race_success_rate must be a dictionary")
                else:
                    for outcome in ['high', 'medium', 'low', 'none']:
                        if outcome in rsr_config:
                            if not isinstance(rsr_config[outcome], (int, float)) or rsr_config[outcome] <= 0:
                                errors.append(f"race_bayesian.race_success_rate.{outcome} must be a positive number")

            # Validate race window size likelihood ratios
            if 'race_window_size' in race_config:
                rws_config = race_config['race_window_size']
                if not isinstance(rws_config, dict):
                    errors.append("race_bayesian.race_window_size must be a dictionary")
                else:
                    for outcome in ['tiny', 'small', 'medium', 'large', 'unknown']:
                        if outcome in rws_config:
                            if not isinstance(rws_config[outcome], (int, float)) or rws_config[outcome] <= 0:
                                errors.append(f"race_bayesian.race_window_size.{outcome} must be a positive number")

            # Validate prior probability
            if 'prior_probability' in race_config:
                if not isinstance(race_config['prior_probability'], (int, float)) or race_config['prior_probability'] < 0 or race_config['prior_probability'] > 1:
                    errors.append("race_bayesian.prior_probability must be a number between 0 and 1")

            # Validate probability floor and cap
            if 'probability_floor' in race_config:
                if not isinstance(race_config['probability_floor'], int) or race_config['probability_floor'] < 0 or race_config['probability_floor'] > 100:
                    errors.append("race_bayesian.probability_floor must be an integer between 0 and 100")

            if 'probability_cap' in race_config:
                if not isinstance(race_config['probability_cap'], int) or race_config['probability_cap'] < 0 or race_config['probability_cap'] > 100:
                    errors.append("race_bayesian.probability_cap must be an integer between 0 and 100")

            # Ensure floor < cap
            if 'probability_floor' in race_config and 'probability_cap' in race_config:
                if race_config['probability_floor'] >= race_config['probability_cap']:
                    errors.append("race_bayesian.probability_floor must be less than probability_cap")

    # Validate OOB configuration - require externally reachable endpoint when OOB is enabled
    enable_advanced_oob = config.get('enable_advanced_oob', False)
    oob_ip = config.get('oob_ip')
    
    if enable_advanced_oob:
        # Check if OOB IP is configured at all
        if oob_ip is None:
            errors.append(
                "OOB testing is enabled but 'oob_ip' is not configured. "
                "Remote targets cannot callback to the scanner without an externally reachable IP address. "
                "Please configure 'oob_ip' with an externally reachable IP address or disable OOB testing."
            )
        # Check if OOB IP is externally reachable (not loopback)
        elif oob_ip in ['127.0.0.1', 'localhost', '::1', '0.0.0.0']:
            errors.append(
                "OOB testing is enabled but 'oob_ip' is set to a loopback address (%s). "
                "Remote targets cannot callback to the scanner's loopback interface. "
                "Please configure an externally reachable IP address or disable OOB testing." % oob_ip
            )
        elif not validate_ip_address(oob_ip):
            errors.append(f"Invalid OOB IP address: {oob_ip}")

    # Validate Dual-Session IDOR Tester configuration (Issue T9 Fix)
    if 'dual_session_idor_enabled' in config:
        if not isinstance(config['dual_session_idor_enabled'], bool):
            errors.append("dual_session_idor_enabled must be a boolean value")
        elif config['dual_session_idor_enabled']:
            # If IDOR testing is enabled, validate required configuration
            has_registration = 'registration_url' in config and config['registration_url']
            has_login = 'login_url' in config and config['login_url']
            has_auth_config = 'auth_config' in config and config['auth_config']

            if not has_login:
                errors.append("dual_session_idor_enabled requires login_url to be configured")

            if has_auth_config:
                auth_config = config['auth_config']
                if not isinstance(auth_config, dict):
                    errors.append("auth_config must be a dictionary")
                else:
                    # Validate attacker_credentials if provided
                    if 'attacker_credentials' in auth_config:
                        attacker_creds = auth_config['attacker_credentials']
                        if not isinstance(attacker_creds, dict):
                            errors.append("auth_config.attacker_credentials must be a dictionary")
                        else:
                            if not (attacker_creds.get('email') or attacker_creds.get('username')):
                                errors.append("auth_config.attacker_credentials must contain email or username")
                            if not attacker_creds.get('password'):
                                errors.append("auth_config.attacker_credentials must contain password")

                    # Validate victim_credentials if provided
                    if 'victim_credentials' in auth_config:
                        victim_creds = auth_config['victim_credentials']
                        if not isinstance(victim_creds, dict):
                            errors.append("auth_config.victim_credentials must be a dictionary")
                        else:
                            if not (victim_creds.get('email') or victim_creds.get('username')):
                                errors.append("auth_config.victim_credentials must contain email or username")
                            if not victim_creds.get('password'):
                                errors.append("auth_config.victim_credentials must contain password")

    
    # Validate PDF report configuration (Issue M6)
    if 'pdf_report' in config:
        pdf_config = config['pdf_report']
        if not isinstance(pdf_config, dict):
            errors.append("pdf_report must be a dictionary")
        else:
            if 'evidence_truncation_length' in pdf_config:
                if not isinstance(pdf_config['evidence_truncation_length'], int) or pdf_config['evidence_truncation_length'] < 100:
                    errors.append("pdf_report.evidence_truncation_length must be an integer >= 100")
            if 'payload_truncation_length' in pdf_config:
                if not isinstance(pdf_config['payload_truncation_length'], int) or pdf_config['payload_truncation_length'] < 100:
                    errors.append("pdf_report.payload_truncation_length must be an integer >= 100")
            if 'response_truncation_length' in pdf_config:
                if not isinstance(pdf_config['response_truncation_length'], int) or pdf_config['response_truncation_length'] < 100:
                    errors.append("pdf_report.response_truncation_length must be an integer >= 100")
            if 'include_full_evidence_appendix' in pdf_config and not isinstance(pdf_config['include_full_evidence_appendix'], bool):
                errors.append("pdf_report.include_full_evidence_appendix must be a boolean value")
    
    # Validate side_channel_vuln_types configuration (Issue P11)
    if 'side_channel_vuln_types' in config:
        side_channel_types = config['side_channel_vuln_types']
        if not isinstance(side_channel_types, list):
            errors.append("side_channel_vuln_types must be a list of strings")
        else:
            if not all(isinstance(item, str) for item in side_channel_types):
                errors.append("All items in side_channel_vuln_types must be strings")
    
    return len(errors) == 0, errors

# Regression oracle constants
DEFAULT_BENIGN_SAMPLE_SIZE = 50
DEFAULT_REGRESSION_RETRIES = 3
DEFAULT_REGRESSION_DELAY = 1.0

# Schema inference constants
DEFAULT_INFERENCE_CONFIDENCE_THRESHOLD = 0.7
DEFAULT_MAX_PROBES_PER_PARAMETER = 20

# Mutation constants
DEFAULT_MUTATION_INTENSITY = 0.8
DEFAULT_MAX_MUTATIONS_PER_PARAMETER = 50

# Proxy pool constants
PROXY_ROTATION_INTERVAL = 100
PROXY_HEALTH_CHECK_INTERVAL = 300
PROXY_MAX_FAILURE_RATE = 0.5
PROXY_FAILURE_TRACKING_WINDOW = 60
PROXY_FAILURE_THRESHOLD = 0.8
PROXY_STICKY_SESSION_DURATION = 600

# Intelligent verification constants
# This fixes Issue 2.3: Lower default confidence thresholds for better detection coverage
DEFAULT_CONFIDENCE_THRESHOLD = 30  # Lowered from 50 to catch more legitimate vulnerabilities
DEFAULT_GRAY_ZONE_THRESHOLD = 20  # Increased from 10 to review more findings
DEFAULT_PROXIMITY_VALIDATION_SAMPLE_SIZE = 3

# Evidence size limits (Issue M2)
# Cap full_evidence size to prevent unbounded JSON report growth
DEFAULT_MAX_EVIDENCE_SIZE_BYTES = 65536  # 64KB default

# Side channel vulnerability types (Issue P11)
# These vulnerability types rely on side channels (callbacks, timing, etc.) and should never be suppressed
DEFAULT_SIDE_CHANNEL_VULN_TYPES = {
    'SSRF', 'Blind SSRF', 'Log4j', 'Text4Shell', 'XXE',
    'Blind SQLi', 'Time-based SQLi', 'Blind XSS', 'CommandInjection',
    'SSTI (Time-based)', 'SSTI (OOB)'
}

# Bayesian confidence calculation constants (Issue C19)
# These are likelihood ratios for evidence: P(evidence|vuln) / P(evidence|no-vuln)
# Values > 1.0 support vulnerability, values < 1.0 support no vulnerability
DEFAULT_BAYESIAN_CONFIDENCE_CONFIG = {
    'validation_1_original': {
        'passed': 10.0,      # Strong evidence for vulnerability
        'failed': 0.1,       # Strong evidence against vulnerability
        'inconclusive': 1.0   # Neutral evidence
    },
    'validation_2_alternative': {
        'passed': 8.0,       # Strong evidence for vulnerability
        'failed': 0.2,       # Evidence against vulnerability
        'inconclusive': 1.0  # Neutral evidence
    },
    'validation_3_manual': {
        'passed': 6.0,       # Moderate evidence for vulnerability
        'failed': 0.3,       # Evidence against vulnerability
        'inconclusive': 1.0  # Neutral evidence
    },
    'validation_4_poe': {
        'passed': 20.0,      # Very strong evidence - actual exploitation demonstrated
        'failed': 0.05,      # Very strong evidence against - cannot exploit
        'inconclusive': 1.0  # Neutral evidence
    },
    'remediation_test': {
        'critical': 15.0,    # Very strong evidence (CSP bypass, stacked queries)
        'high': 8.0,         # Strong evidence
        'medium': 4.0,       # Moderate evidence
        'low': 2.0,          # Weak evidence
        'error': 1.0         # Neutral (test failed)
    },
    'prior_confidence': 0.5,  # Default prior probability (50%)
    'confidence_floor': 5,    # Minimum confidence percentage
    'confidence_cap': 95      # Maximum confidence percentage
}

# Bayesian race condition probability calculation constants (Issue C20)
# These are likelihood ratios for race condition evidence: P(evidence|race) / P(evidence|no-race)
DEFAULT_RACE_BAYESIAN_CONFIG = {
    'persistence_confirmed': {
        'confirmed': 20.0,     # Very strong evidence: multiple successful requests with different state changes
        'not_confirmed': 0.5,  # Weak evidence: no persistence observed
        'unknown': 1.0         # Neutral evidence
    },
    'timing_distribution': {
        'bimodal': 15.0,       # Strong evidence: clear success/failure timing split
        'unimodal_success': 0.3,  # Evidence against: all requests succeeded (no race)
        'unimodal_failure': 0.2,   # Evidence against: all requests failed (no race)
        'flat': 1.0            # Neutral evidence
    },
    'race_success_rate': {
        'high': 10.0,          # Strong evidence: race consistently triggered
        'medium': 5.0,         # Moderate evidence: race occasionally triggered
        'low': 2.0,            # Weak evidence: race rarely triggered
        'none': 0.1            # Strong evidence against: race never triggered
    },
    'race_window_size': {
        'tiny': 8.0,           # Strong evidence: very small window (<10ms) indicates precise race
        'small': 5.0,          # Moderate evidence: small window (10-50ms)
        'medium': 3.0,         # Weak evidence: medium window (50-200ms)
        'large': 1.0,          # Neutral: large window (>200ms)
        'unknown': 1.0         # Neutral: window size unknown
    },
    'prior_probability': 0.3,  # Default prior probability for race conditions (30%)
    'probability_floor': 5,    # Minimum probability percentage
    'probability_cap': 95      # Maximum probability percentage
}

