def _stateless_payload_test_worker(task_data):
    """
    Stateless worker function for payload testing only.
    This worker is designed to be completely stateless - it receives all context
    needed for the request and returns only the response data for canonical detection.
    """
    import asyncio
    import aiohttp
    from aiohttp import ClientTimeout, FormData
    from datetime import datetime
    import time
    import traceback
    
    try:
        url = task_data['url']
        payload = task_data['payload']
        method = task_data.get('method', 'GET')
        headers = task_data.get('headers', {})
        cookies = task_data.get('cookies', {})  # Session context provided by master
        timeout = task_data.get('timeout', TIMEOUT_PROFILES['default'].total)
        vuln_type = task_data.get('vuln_type', 'Unknown')
        param_name = task_data.get('param_name', 'unknown')
        content_type = task_data.get('content_type', 'form')  # Issue C11 fix: content type field
    except (KeyError, TypeError, ValueError) as e:
        # Handle serialization errors when accessing task_data
        logging.error(f"Task data serialization error: {str(e)}")
        return {
            'error': f'Task data serialization error: {str(e)}',
            'success': False,
            'exception_type': type(e).__name__,
            'timestamp': datetime.now().isoformat(),
            'task_data_keys': list(task_data.keys()) if isinstance(task_data, dict) else 'non-dict task_data'
        }
    
    try:
        # Create isolated async loop for this process
        loop = get_loop()
        
        async def test():
            start_time = time.time()
            async with aiohttp.ClientSession() as session:
                if method == 'GET':
                    async with session.get(url, params=payload, headers=headers, cookies=cookies,
                                            timeout=TIMEOUT_PROFILES['default'].to_client_timeout()) as resp:
                        # Issue C10 fix: Read response as bytes first for proper decompression
                        content_bytes = await resp.read()
                        content_encoding = resp.headers.get('Content-Encoding', '')
                        content = decode_response_body(content_bytes, content_encoding)
                        resp_headers = response_headers(resp)
                        response_time = time.time() - start_time
                        return {
                            'url': url,
                            'payload': payload,
                            'status': response_status(resp),
                            'body': content,  # Include response body for detection
                            'content_length': len(content),
                            'headers': resp_headers,
                            'response_time': response_time,  # Include timing for time-based detection
                            'vuln_type': vuln_type,  # Include vulnerability type
                            'param_name': param_name,  # Include parameter name
                            'success': True
                        }
                else:
                    # Issue C11 fix: Handle different content types properly
                    if content_type == 'json':
                        # Send as JSON payload
                        async with session.post(url, json=payload, headers=headers, cookies=cookies,
                                                timeout=TIMEOUT_PROFILES['default'].to_client_timeout()) as resp:
                            # Issue C10 fix: Read response as bytes first for proper decompression
                            content_bytes = await resp.read()
                            content_encoding = resp.headers.get('Content-Encoding', '')
                            content = decode_response_body(content_bytes, content_encoding)
                            resp_headers = response_headers(resp)
                            response_time = time.time() - start_time
                            return {
                                'url': url,
                                'payload': payload,
                                'status': response_status(resp),
                                'body': content,  # Include response body for detection
                                'content_length': len(content),
                                'headers': response_headers,
                                'response_time': response_time,  # Include timing for time-based detection
                                'vuln_type': vuln_type,  # Include vulnerability type
                                'param_name': param_name,  # Include parameter name
                                'success': True
                            }
                    elif content_type == 'xml':
                        # Send as XML with proper Content-Type header
                        xml_headers = headers.copy()
                        xml_headers['Content-Type'] = 'application/xml'
                        async with session.post(url, data=payload, headers=xml_headers, cookies=cookies,
                                                timeout=TIMEOUT_PROFILES['default'].to_client_timeout()) as resp:
                            # Issue C10 fix: Read response as bytes first for proper decompression
                            content_bytes = await resp.read()
                            content_encoding = resp.headers.get('Content-Encoding', '')
                            content = decode_response_body(content_bytes, content_encoding)
                            resp_headers = response_headers(resp)
                            response_time = time.time() - start_time
                            return {
                                'url': url,
                                'payload': payload,
                                'status': response_status(resp),
                                'body': content,  # Include response body for detection
                                'content_length': len(content),
                                'headers': response_headers,
                                'response_time': response_time,  # Include timing for time-based detection
                                'vuln_type': vuln_type,  # Include vulnerability type
                                'param_name': param_name,  # Include parameter name
                                'success': True
                            }
                    else:
                        # Default: Use FormData for POST requests to properly handle form encoding
                        # This is especially important for multipart/form-data uploads
                        if isinstance(payload, dict):
                            # Convert dict to FormData for proper form encoding
                            form_data = FormData()
                            for key, value in payload.items():
                                form_data.add_field(key, str(value))
                            async with session.post(url, data=form_data, headers=headers, cookies=cookies,
                                                    timeout=TIMEOUT_PROFILES['default'].to_client_timeout()) as resp:
                                # Issue C10 fix: Read response as bytes first for proper decompression
                                content_bytes = await resp.read()
                                content_encoding = resp.headers.get('Content-Encoding', '')
                                content = decode_response_body(content_bytes, content_encoding)
                                resp_headers = response_headers(resp)
                                response_time = time.time() - start_time
                                return {
                                    'url': url,
                                    'payload': payload,
                                    'status': response_status(resp),
                                    'body': content,  # Include response body for detection
                                    'content_length': len(content),
                                    'headers': response_headers,
                                    'response_time': response_time,  # Include timing for time-based detection
                                    'vuln_type': vuln_type,  # Include vulnerability type
                                    'param_name': param_name,  # Include parameter name
                                    'success': True
                                }
                        else:
                            # For non-dict payloads (strings, etc.), use as-is
                            async with session.post(url, data=payload, headers=headers, cookies=cookies,
                                                    timeout=TIMEOUT_PROFILES['default'].to_client_timeout()) as resp:
                                # Issue C10 fix: Read response as bytes first for proper decompression
                                content_bytes = await resp.read()
                                content_encoding = resp.headers.get('Content-Encoding', '')
                                content = decode_response_body(content_bytes, content_encoding)
                                resp_headers = response_headers(resp)
                                response_time = time.time() - start_time
                                return {
                                    'url': url,
                                    'payload': payload,
                                    'status': response_status(resp),
                                    'body': content,  # Include response body for detection
                                    'content_length': len(content),
                                    'headers': response_headers,
                                    'response_time': response_time,  # Include timing for time-based detection
                                    'vuln_type': vuln_type,  # Include vulnerability type
                                    'param_name': param_name,  # Include parameter name
                                    'success': True
                                }
        
        result = loop.run_until_complete(test())
        loop.close()
        
        # Validate result can be serialized before returning
        try:
            # Test serialization by converting to JSON string
            import json
            json.dumps(result)
            return result
        except (TypeError, ValueError) as e:
            logging.error(f"Result serialization error: {str(e)}")
            return {
                'error': f'Result serialization error: {str(e)}',
                'success': False,
                'exception_type': type(e).__name__,
                'timestamp': datetime.now().isoformat(),
                'url': url,
                'vuln_type': vuln_type,
                'param_name': param_name
            }
    except (aiohttp.ClientError, asyncio.TimeoutError, ConnectionError) as e:
        import traceback
        try:
            error_result = {
                'url': url,
                'payload': payload,
                'error': str(e),
                'success': False,
                'exception_type': type(e).__name__,
                'timestamp': datetime.now().isoformat(),
                'stack_trace': traceback.format_exc(),
                'vuln_type': vuln_type,
                'param_name': param_name
            }
            # Validate error result can be serialized
            import json
            json.dumps(error_result)
            return error_result
        except (TypeError, ValueError) as serialization_error:
            logging.error(f"Error result serialization failure: {str(serialization_error)}")
            return {
                'error': f'Error result serialization failure: {str(serialization_error)}',
                'success': False,
                'exception_type': type(serialization_error).__name__,
                'timestamp': datetime.now().isoformat()
            }
    except Exception as e:
        import traceback
        logging.error(f"Unexpected worker error: {str(e)}")
        try:
            error_result = {
                'url': url,
                'payload': payload,
                'error': str(e),
                'success': False,
                'exception_type': type(e).__name__,
                'timestamp': datetime.now().isoformat(),
                'stack_trace': traceback.format_exc(),
                'vuln_type': vuln_type,
                'param_name': param_name
            }
            # Validate error result can be serialized
            import json
            json.dumps(error_result)
            return error_result
        except (TypeError, ValueError) as serialization_error:
            logging.error(f"Error result serialization failure: {str(serialization_error)}")
            return {
                'error': f'Error result serialization failure: {str(serialization_error)}',
                'success': False,
                'exception_type': type(serialization_error).__name__,
                'timestamp': datetime.now().isoformat()
            }

def _stateless_batch_worker(task_queue, result_queue, completed_counter, errors_counter, vulnerabilities_counter):
    """
    Stateless worker process implementation with retry mechanism.
    Only handles stateless payload testing - no crawling, FSM, or session management.
    All state is managed by the master process.

    Added batch processing to reduce pickling/unpickling overhead.
    Issue H1 fix: Use multiprocessing.Value for atomic counters instead of Manager().dict()
    Issue H3 fix: Use blocking queue.get() without timeout to prevent CPU waste when idle.
                    Workers now block indefinitely on queue and rely on poison pill (None) for shutdown.
    Issue S4 fix: Use multiprocessing.Queue directly instead of Manager().Queue() to reduce IPC overhead.
    """
    import asyncio
    import aiohttp

    while True:
        try:
            task = task_queue.get()  # Block indefinitely - no timeout (Issue H3 fix)
        except Exception as e:
            logging.error(f"Error: {e}")

            if task is None:  # Poison pill
                break

            task_type = task.get('type')
            task_data = task.get('data')

            # Handle batched payload testing
            if task_type == 'payload_test_batch':
                # Process batch of test cases
                batch_results = []
                for test_case in task_data:
                    result = _stateless_payload_test_worker(test_case)
                    batch_results.append(result)

                # Put aggregated results as a single item
                try:
                    result_queue.put(batch_results)
                except (BrokenPipeError, EOFError):
                    # Queue is closed during shutdown, exit gracefully
                    logging.error("Result queue closed during shutdown, worker exiting")
                    break

                # Update shared state for batch using atomic counters (Issue H1 fix)
                batch_completed = sum(1 for r in batch_results if r.get('success'))
                batch_errors = len(batch_results) - batch_completed

                with completed_counter.get_lock():
                    completed_counter.value += batch_completed

                with errors_counter.get_lock():
                    errors_counter.value += batch_errors

            elif task_type == 'payload_test':
                # Legacy single-task support for backward compatibility
                result = _stateless_payload_test_worker(task_data)
                try:
                    result_queue.put(result)
                except (BrokenPipeError, EOFError):
                    # Queue is closed during shutdown, exit gracefully
                    logging.error("Result queue closed during shutdown, worker exiting")
                    break

                if result.get('success'):
                    with completed_counter.get_lock():
                        completed_counter.value += 1
                else:
                    with errors_counter.get_lock():
                        errors_counter.value += 1
            else:
                result = {'error': f'Unknown or unsupported task type: {task_type}. Workers only handle stateless payload testing.'}
                try:
                    result_queue.put(result)
                except (BrokenPipeError, EOFError):
                    # Queue is closed during shutdown, exit gracefully
                    logging.error("Result queue closed during shutdown, worker exiting")
                    break
                
        except (KeyError, ValueError, TypeError, AttributeError) as e:
            try:
                result_queue.put({'error': str(e), 'task': task})
            except (BrokenPipeError, EOFError):
                # Queue is closed during shutdown, exit gracefully
                logging.error("Result queue closed during shutdown, worker exiting")
                break
            with errors_counter.get_lock():
                errors_counter.value += 1
        except (BrokenPipeError, EOFError):
            # Queue is closed during shutdown, exit gracefully
            logging.error("Task queue closed during shutdown, worker exiting")
            break
        except Exception as e:
            # Issue H3 fix: No queue.Empty handling needed with blocking get()
            try:
                result_queue.put({'error': str(e), 'task': None})
            except (BrokenPipeError, EOFError):
                # Queue is closed during shutdown, exit gracefully
                logging.error("Result queue closed during shutdown, worker exiting")
                break
            with errors_counter.get_lock():
                errors_counter.value += 1

class MultiprocessingScanner:
    """
    REDESIGNED: Multiprocessing scanner for stateless batch processing only.

    This scanner is specifically designed for stateless operations (payload injection testing).
    All stateful operations (crawling, FSM, session management, visited URLs) remain in the
    master process to ensure proper state synchronization and consistency.

    Architecture:
    - Master Process: Handles crawling, FSM, session management, visited URLs, state coordination
    - Worker Processes: Handle only stateless payload injection testing with provided context
    - Task Distribution: Master provides all necessary context (cookies, headers) with each task
    - Result Collection: Workers return only response data; master processes results

    Issue S4 fix: Uses multiprocessing.Queue directly instead of Manager().Queue() to reduce IPC overhead.
    """
    
    def __init__(self, num_processes=None, batch_size=50):
        self.num_processes = num_processes or multiprocessing.cpu_count()
        self.batch_size = batch_size  # Number of payloads to batch per task
        # Use multiprocessing.Queue directly (Issue S4 fix) - reduces IPC overhead
        self.task_queue = Queue()
        self.result_queue = Queue()
        self.processes = []
        # Use multiprocessing.Value with locks for atomic counters (Issue H1 fix)
        self.completed_counter = multiprocessing.Value('i', 0, lock=True)
        self.errors_counter = multiprocessing.Value('i', 0, lock=True)
        self.vulnerabilities_counter = multiprocessing.Value('i', 0, lock=True)
        self._shutdown_called = False
        self.workers_started = False
        self.scan_running = False  # Issue U6 fix: Flag for watchdog monitoring
        
    def start_workers(self):
        """Start stateless worker processes"""
        self.processes = []
        for _ in range(self.num_processes):
            p = Process(target=_stateless_batch_worker,
                        args=(self.task_queue, self.result_queue,
                                self.completed_counter, self.errors_counter, self.vulnerabilities_counter))
            p.start()
            self.processes.append(p)
        self.workers_started = True
        self.scan_running = True  # Issue U6 fix: Start watchdog flag

    async def _monitor_workers(self):
        """
        Issue U6 fix: Watchdog to detect and restart crashed worker processes.
        
        This method runs as a background task during scanning. It periodically checks
        if worker processes are still alive and restarts any that have crashed.
        This prevents the master process from waiting forever if workers die
        due to OOM, segfaults, or unhandled exceptions in C extensions.
        """
        while self.scan_running:
            for p in self.processes[:]:  # Iterate over a copy to allow modification
                if not p.is_alive():
                    logging.error(f"Worker {p.pid} died; restarting")
                    # Clean up the dead process
                    p.join(timeout=1.0)
                    if p.is_alive():
                        p.terminate()
                        p.join(timeout=1.0)
                    
                    # Remove dead process from list
                    self.processes.remove(p)
                    
                    # Start a replacement worker
                    new_p = Process(target=_stateless_batch_worker,
                                   args=(self.task_queue, self.result_queue,
                                         self.completed_counter, self.errors_counter, self.vulnerabilities_counter))
                    new_p.start()
                    self.processes.append(new_p)
                    logging.info(f"Started replacement worker {new_p.pid}")
            
            await asyncio.sleep(5)  # Check every 5 seconds

    
    def add_payload_test(self, url, payload, method='GET', headers=None, cookies=None, timeout=None, content_type='form', **kwargs):
        """
        Add a stateless payload test task to the queue.
        
        Args:
            url: Target URL for payload testing
            payload: Payload data to test
            method: HTTP method (GET/POST)
            headers: Request headers (including session context from master)
            cookies: Session cookies (provided by master process)
            timeout: Request timeout
            content_type: Content type for payload encoding ('form', 'json', 'xml') - Issue C11 fix
            **kwargs: Additional fields (vuln_type and param_name are REQUIRED for detection reporting - Issue H5 fix)
        """
        task_data = {
            'url': url,
            'payload': payload,
            'method': method,
            'headers': headers or {},
            'cookies': cookies or {},
            'timeout': timeout or DEFAULT_REQUEST_TIMEOUT,
            'content_type': content_type  # Issue C11 fix: content type for proper encoding
        }
        # Include additional fields for detection reporting
        task_data.update(kwargs)
        
        # Validate required fields at queue time (Issue H5 fix)
        required_fields = ['vuln_type', 'param_name']
        missing_fields = [field for field in required_fields if field not in task_data]
        if missing_fields:
            raise ValueError(f"Task missing required fields: {missing_fields}. "
                            f"Task data: {task_data}")
        
        self.task_queue.put({'type': 'payload_test', 'data': task_data})
    
    def add_payload_tests_batch(self, test_cases):
        """
        Add multiple stateless payload test tasks to the queue with batching.

        Batches test cases to reduce pickling/unpickling overhead. Each task contains
        up to batch_size payloads, which the worker processes iteratively.

        Args:
            test_cases: List of dictionaries with keys: url, payload, method, headers, cookies, timeout, content_type
                        REQUIRED fields: vuln_type, param_name (Issue H5 fix)
                        content_type field ('form', 'json', 'xml') is required for proper payload encoding (Issue C11 fix)
        """
        # Validate test cases at queue time (Issue H5 fix)
        required_fields = ['url', 'payload', 'method', 'vuln_type', 'param_name']
        for idx, test_case in enumerate(test_cases):
            missing_fields = [field for field in required_fields if field not in test_case]
            if missing_fields:
                raise ValueError(f"Test case {idx} missing required fields: {missing_fields}. "
                                f"Test case: {test_case}")
        
        # Batch test cases to reduce pickling overhead
        for i in range(0, len(test_cases), self.batch_size):
            batch = test_cases[i:i + self.batch_size]
            self.task_queue.put({'type': 'payload_test_batch', 'data': batch})
    
    def get_results(self, timeout=None):
        """Get results from the result queue"""
        results = []
        try:
            while True:
                result = self.result_queue.get(timeout=timeout or 0.1)
                results.append(result)
        except Exception as e:
            logging.error(e)
        return results
    
    def get_stats(self):
        """Get scanning statistics"""
        return {
            'completed': self.completed_counter.value,
            'errors': self.errors_counter.value,
            'vulnerabilities_found': self.vulnerabilities_counter.value
        }
    
    def shutdown(self):
        """Shutdown all worker processes"""
        if self._shutdown_called:
            return
        self._shutdown_called = True
        self.workers_started = False
        self.scan_running = False  # Issue U6 fix: Stop watchdog
        
        # Send poison pills to stop workers
        for _ in range(self.num_processes):
            try:
                self.task_queue.put(None, timeout=1.0)
            except (BrokenPipeError, EOFError):
                # Queue already closed, continue with shutdown
                logging.error("Task queue already closed during shutdown")
                break
        
        # Wait for processes to finish
        for p in self.processes:
            p.join(timeout=PROCESS_JOIN_TIMEOUT)
            if p.is_alive():
                p.terminate()
                p.join(timeout=1.0)  # Wait for termination to complete
    
    def stop_workers(self):
        """Alias for shutdown() method for compatibility"""
        self.shutdown()


class TaskStorage:
    """
    SQLite-based task storage for REST API server.
    Persists scan tasks to disk to prevent OOM on long-running servers.
    """

    def __init__(self, db_path='scan_tasks.db'):
        self.db_path = db_path
        self.lock = threading.Lock()

        # Initialize database
        with sqlite3.connect(db_path, check_same_thread=False) as conn:
            self._init_tables_sync(conn)

        # Keep connection open for long-lived operations
        self.conn = sqlite3.connect(db_path, check_same_thread=False)

    def _init_tables_sync(self, conn):
        """Synchronous table initialization"""
        conn.execute('''CREATE TABLE IF NOT EXISTS scan_tasks
                        (task_id TEXT PRIMARY KEY,
                         status TEXT,
                         target_url TEXT,
                         config TEXT,
                         start_time TEXT,
                         end_time TEXT,
                         results TEXT,
                         statistics TEXT,
                         error TEXT)''')
        conn.execute('''CREATE INDEX IF NOT EXISTS idx_status ON scan_tasks(status)''')
        conn.execute('''CREATE INDEX IF NOT EXISTS idx_start_time ON scan_tasks(start_time)''')

    def create_task(self, task_id: str, status: str, target_url: str, config: dict, start_time: str) -> bool:
        """Create a new task in storage"""
        with self.lock:
            try:
                self.conn.execute(
                    "INSERT INTO scan_tasks (task_id, status, target_url, config, start_time) VALUES (?, ?, ?, ?, ?)",
                    (task_id, status, target_url, json.dumps(config), start_time)
                )
                self.conn.commit()
                return True
            except sqlite3.IntegrityError:
                return False

    def update_task(self, task_id: str, **kwargs) -> bool:
        """Update task fields"""
        with self.lock:
            try:
                valid_fields = {'status', 'end_time', 'results', 'statistics', 'error'}
                updates = []
                values = []
                for field, value in kwargs.items():
                    if field in valid_fields:
                        updates.append(f"{field} = ?")
                        if field in ('results', 'statistics'):
                            values.append(json.dumps(value) if value is not None else None)
                        else:
                            values.append(value)
                if not updates:
                    return False
                values.append(task_id)
                self.conn.execute(
                    f"UPDATE scan_tasks SET {', '.join(updates)} WHERE task_id = ?",
                    values
                )
                self.conn.commit()
                return True
            except sqlite3.Error:
                return False

    def get_task(self, task_id: str) -> Optional[dict]:
        """Get task by ID"""
        with self.lock:
            cursor = self.conn.execute("SELECT * FROM scan_tasks WHERE task_id = ?", (task_id,))
            row = cursor.fetchone()
            if row is None:
                return None
            return self._row_to_dict(row)

    def get_all_tasks(self) -> Dict[str, dict]:
        """Get all tasks"""
        with self.lock:
            cursor = self.conn.execute("SELECT * FROM scan_tasks")
            return {row[0]: self._row_to_dict(row) for row in cursor.fetchall()}

    def get_active_tasks(self) -> Dict[str, dict]:
        """Get only active (running) tasks"""
        with self.lock:
            cursor = self.conn.execute("SELECT * FROM scan_tasks WHERE status = 'running'")
            return {row[0]: self._row_to_dict(row) for row in cursor.fetchall()}

    def get_recent_completed_tasks(self, limit: int = 100) -> Dict[str, dict]:
        """Get recent completed tasks, ordered by end_time descending"""
        with self.lock:
            cursor = self.conn.execute(
                "SELECT * FROM scan_tasks WHERE status IN ('completed', 'failed', 'stopped') ORDER BY end_time DESC LIMIT ?",
                (limit,)
            )
            return {row[0]: self._row_to_dict(row) for row in cursor.fetchall()}

    def delete_task(self, task_id: str) -> bool:
        """Delete a task"""
        with self.lock:
            cursor = self.conn.execute("DELETE FROM scan_tasks WHERE task_id = ?", (task_id,))
            self.conn.commit()
            return cursor.rowcount > 0

    def _row_to_dict(self, row) -> dict:
        """Convert database row to dictionary"""
        task = {
            'task_id': row[0],
            'status': row[1],
            'target_url': row[2],
            'config': json.loads(row[3]) if row[3] else {},
            'start_time': row[4],
            'end_time': row[5],
            'results': json.loads(row[6]) if row[6] else [],
            'statistics': json.loads(row[7]) if row[7] else {},
            'error': row[8]
        }
        return task

    def close(self):
        """Close database connection"""
        with self.lock:
            if self.conn:
                self.conn.close()


class RESTAPIServer:
    """
    REST API server for headless mode and CI/CD integration.
    Provides HTTP endpoints for controlling the scanner programmatically.
    """

    def __init__(self, host='127.0.0.1', port=8080):
        self.host = host
        self.port = port
        self.server = None
        self.scanner_instance = None
        self.task_storage = TaskStorage()
        self.active_tasks_cache = {}
        self.task_counter = 0
        # Issue U3 fix: Store tasks on instance to prevent GC mid-flight
        self._background_tasks = set()
        self._background_tasks_lock = threading.Lock()
        self.async_task_manager = AsyncTaskManager(
            external_task_set=self._background_tasks,
            external_task_lock=self._background_tasks_lock
        )
        self.recent_completed_tasks_cap = 100
        
    def set_scanner(self, scanner_instance):
        """Set the scanner instance to control"""
        self.scanner_instance = scanner_instance
        
    async def handle_request(self, request):
        """Handle incoming HTTP requests"""

        path = request.path
        method = request.method
        
        if path == '/api/scan' and method == 'POST':
            return await self.handle_start_scan(request)
        elif path.startswith('/api/scan/') and method == 'GET':
            task_id = path.split('/')[-1]
            return await self.handle_get_scan_status(task_id)
        elif path.startswith('/api/scan/') and method == 'DELETE':
            task_id = path.split('/')[-1]
            return await self.handle_stop_scan(task_id)
        elif path == '/api/results' and method == 'GET':
            return await self.handle_get_results(request)
        elif path == '/api/health' and method == 'GET':
            return await self.handle_health_check()
        elif path == '/api/config' and method == 'GET':
            return await self.handle_get_config()
        elif path == '/api/config' and method == 'POST':
            return await self.handle_set_config(request)
        else:
            return web.json_response({'error': 'Not found'}, status=404)
    
    async def handle_start_scan(self, request):
        """Handle scan start request"""
        try:
            data = await request.json()
            target_url = data.get('target_url')
            config = data.get('config', {})
            
            if not target_url:
                return web.json_response({'error': 'target_url required'}, status=400)
            
            if not self.scanner_instance:
                return web.json_response({'error': 'Scanner not initialized'}, status=500)
            
            # Clear previous findings for this target before starting new scan
            try:
                from urllib.parse import urlparse
                target_domain = urlparse(target_url).netloc
                if self.scanner_instance and hasattr(self.scanner_instance, 'reporting_engine') and hasattr(self.scanner_instance.reporting_engine, 'vulnerability_storage'):
                    self.scanner_instance.reporting_engine.vulnerability_storage.clear_vulnerabilities_by_target_domain(target_domain)
                    logging.info(f"Cleared previous findings for target domain: {target_domain}")
                
                # Clear baseline cache
                if self.scanner_instance and hasattr(self.scanner_instance, 'session_manager') and hasattr(self.scanner_instance.session_manager, 'request_cache'):
                    await self.scanner_instance.session_manager.request_cache.clear()
                    logging.info(f"Cleared baseline cache for fresh scan")
                
                # Clear OOB results (only if scanner instance is available)
                if self.scanner_instance:
                    try:
                        oob_lists = get_oob_results_lists()
                        oob_lists['oob_results'].clear()
                        oob_lists['dns_oob_results'].clear()
                        oob_lists['smtp_oob_results'].clear()
                        oob_lists['https_oob_results'].clear()
                        oob_lists['icmp_oob_results'].clear()
                        logging.info(f"Cleared OOB results for fresh scan")
                    except RuntimeError as e:
                        logging.warning(f"Cannot clear OOB results: {e}")
                else:
                    logging.warning("No scanner instance available to clear OOB results")
            except Exception as e:
                logging.error(f"Failed to clear previous scan data: {e}")
            
            # Create task ID
            task_id = str(uuid.uuid4())
            start_time = datetime.now().isoformat()

            # Persist task to SQLite
            self.task_storage.create_task(task_id, 'running', target_url, config, start_time)

            # Add to active tasks cache
            self.active_tasks_cache[task_id] = {
                'status': 'running',
                'target_url': target_url,
                'config': config,
                'start_time': start_time,
                'results': []
            }

            # Start scan in background with proper exception handling
            task = self.async_task_manager.create_task_sync(
                self.run_scan(task_id, target_url, config),
                task_name=f"scan_{task_id}",
                callback=lambda t: logging.info(f"Scan task {task_id} completed")
            )
            
            return web.json_response({
                'task_id': task_id,
                'status': 'started',
                'message': 'Scan started successfully'
            })
        except (ValueError, KeyError, AttributeError, RuntimeError) as e:
            import traceback
            error_context = {
                'error': str(e),
                'exception_type': type(e).__name__,
                'timestamp': datetime.now().isoformat(),
                'stack_trace': traceback.format_exc()
            }
            return web.json_response(error_context, status=500)
    
    async def run_scan(self, task_id, target_url, config):
        """Run scan in background"""
        try:
            # Update task status to running in both cache and storage
            self.active_tasks_cache[task_id]['status'] = 'running'
            self.active_tasks_cache[task_id]['start_time'] = datetime.now().isoformat()
            self.task_storage.update_task(task_id, status='running', start_time=datetime.now().isoformat())

            # Run the actual scan using the scanner instance
            if self.scanner_instance:
                # Configure the scanner with the provided config
                for key, value in config.items():
                    if hasattr(self.scanner_instance, key):
                        setattr(self.scanner_instance, key, value)

                # Execute the scan
                scan_results = []

                # Start the scan
                await self.scanner_instance.scan(target_url)

                # Collect results from the scanner
                if hasattr(self.scanner_instance, 'vulnerabilities'):
                    for vuln in self.scanner_instance.vulnerabilities:
                        scan_results.append({ 'type': vuln.get('type', 'Unknown'), 'severity': vuln.get('severity', 'Medium'), 'url': vuln.get('url', target_url), 'confidence': vuln.get('confidence', 50), 'evidence': vuln.get('evidence', ''), 'parameter': vuln.get('parameter', ''), 'cwe': vuln.get('cwe', '') })

                # Add statistics
                scan_stats = {
                    'total_requests': getattr(self.scanner_instance, 'total_requests', 0),
                    'tested_payloads': getattr(self.scanner_instance, 'tested_payloads', 0),
                    'scan_duration': getattr(self.scanner_instance, 'scan_duration', 0)
                }

                # Process Gray Zone findings if auto-processing is enabled
                gray_zone_config = config.get('gray_zone_handling', {})
                if gray_zone_config.get('auto_process_on_scan_complete', False):
                    try:
                        if hasattr(self.scanner_instance, 'validation_engine'):
                            logging.info("Auto-processing Gray Zone findings after scan completion")
                            gray_zone_results = await self.scanner_instance.validation_engine.process_gray_zone_bucket()
                            scan_stats['gray_zone_processing'] = gray_zone_results
                            logging.info(f"Gray Zone auto-processing completed: {gray_zone_results}")
                    except (AttributeError, KeyError, RuntimeError) as e:
                        logging.error(f"Error during Gray Zone auto-processing: {e}")
                        scan_stats['gray_zone_processing_error'] = str(e)

                # Update task status to completed
                end_time = datetime.now().isoformat()
                self.task_storage.update_task(task_id, status='completed', end_time=end_time, results=scan_results, statistics=scan_stats)

                # Remove from active cache and add to recent completed if within cap
                if task_id in self.active_tasks_cache:
                    del self.active_tasks_cache[task_id]
                self._manage_completed_tasks_cache(task_id, end_time, scan_results, scan_stats)
            else:
                # Scanner instance not initialized - mark as failed (Issue S28 fix)
                end_time = datetime.now().isoformat()
                error_msg = 'Scanner not initialized - cannot perform scan'
                self.task_storage.update_task(task_id, status='failed', end_time=end_time, error=error_msg)

                if task_id in self.active_tasks_cache:
                    del self.active_tasks_cache[task_id]
                logging.error(f"Scan failed for task {task_id}: {error_msg}")
        except (asyncio.CancelledError, KeyboardInterrupt):
            raise  # Re-raise cancellation signals
        except (ValueError, KeyError, AttributeError, RuntimeError, aiohttp.ClientError) as e:
            import traceback
            end_time = datetime.now().isoformat()
            self.task_storage.update_task(task_id, status='failed', end_time=end_time, error=str(e))
            if task_id in self.active_tasks_cache:
                del self.active_tasks_cache[task_id]
            logging.error(f"Scan failed for task {task_id} (target: {target_url})\n"
                            f"Exception Type: {type(e).__name__}\n"
                            f"Error: {e}\n"
                            f"Stack Trace:\n{traceback.format_exc()}")

    def _manage_completed_tasks_cache(self, task_id: str, end_time: str, results: list, statistics: dict):
        """Manage the in-memory cache for recently completed tasks"""
        if not hasattr(self, 'completed_tasks_cache'):
            self.completed_tasks_cache = {}

        # Add to cache
        self.completed_tasks_cache[task_id] = {
            'task_id': task_id,
            'end_time': end_time,
            'results': results,
            'statistics': statistics
        }

        # Enforce cap by removing oldest tasks
        if len(self.completed_tasks_cache) > self.recent_completed_tasks_cap:
            # Sort by end_time and remove oldest
            sorted_tasks = sorted(self.completed_tasks_cache.items(), key=lambda x: x[1]['end_time'])
            while len(self.completed_tasks_cache) > self.recent_completed_tasks_cap:
                oldest_task_id = sorted_tasks.pop(0)[0]
                del self.completed_tasks_cache[oldest_task_id]
    
    async def handle_get_scan_status(self, task_id):
        """Handle scan status request"""
        # Check active cache first for performance
        if task_id in self.active_tasks_cache:
            return web.json_response(self.active_tasks_cache[task_id])

        # Check completed tasks cache
        if hasattr(self, 'completed_tasks_cache') and task_id in self.completed_tasks_cache:
            cached = self.completed_tasks_cache[task_id]
            return web.json_response({
                'task_id': task_id,
                'status': 'completed',
                'end_time': cached['end_time'],
                'results': cached['results'],
                'statistics': cached['statistics']
            })

        # Fall back to database
        task = self.task_storage.get_task(task_id)
        if task is None:
            return web.json_response({'error': 'Task not found'}, status=404)

        return web.json_response(task)

    async def handle_stop_scan(self, task_id):
        """Handle scan stop request"""
        # Check active cache first
        if task_id in self.active_tasks_cache:
            self.active_tasks_cache[task_id]['status'] = 'stopped'
            self.task_storage.update_task(task_id, status='stopped')
            return web.json_response({'status': 'stopped'})

        # Check database
        task = self.task_storage.get_task(task_id)
        if task is None:
            return web.json_response({'error': 'Task not found'}, status=404)

        self.task_storage.update_task(task_id, status='stopped')
        return web.json_response({'status': 'stopped'})

    async def handle_get_results(self, request):
        """Handle results request"""
        task_id = request.query.get('task_id')

        if task_id:
            # Check active cache first
            if task_id in self.active_tasks_cache:
                return web.json_response(self.active_tasks_cache[task_id].get('results', []))

            # Check completed tasks cache
            if hasattr(self, 'completed_tasks_cache') and task_id in self.completed_tasks_cache:
                return web.json_response(self.completed_tasks_cache[task_id].get('results', []))

            # Fall back to database
            task = self.task_storage.get_task(task_id)
            if task is None:
                return web.json_response({'error': 'Task not found'}, status=404)
            return web.json_response(task.get('results', []))
        else:
            # Return all results from database
            all_tasks = self.task_storage.get_all_tasks()
            all_results = {}
            for tid, task in all_tasks.items():
                all_results[tid] = task.get('results', [])
            return web.json_response(all_results)
    
    async def handle_health_check(self):
        """Handle health check request"""
        active_tasks = self.task_storage.get_active_tasks()
        return web.json_response({
            'status': 'healthy',
            'timestamp': datetime.now().isoformat(),
            'active_tasks': len(active_tasks)
        })
    
    async def handle_get_config(self):
        """Handle get config request"""
        if self.scanner_instance:
            return web.json_response(getattr(self.scanner_instance, 'config', {}))
        return web.json_response({})
    
    async def handle_set_config(self, request):
        """Handle set config request"""
        try:
            config = await request.json()
            
            if self.scanner_instance:
                # Use the update_config method which includes validation
                self.scanner_instance.update_config(config, validate=True)
            return web.json_response({'status': 'updated'})
        except ValueError as e:
            # Handle validation errors
            error_context = {
                'error': 'Configuration validation failed',
                'validation_errors': str(e),
                'timestamp': datetime.now().isoformat()
            }
            return web.json_response(error_context, status=400)
        except (json.JSONDecodeError, KeyError) as e:
            import traceback
            error_context = {
                'error': str(e),
                'exception_type': type(e).__name__,
                'timestamp': datetime.now().isoformat(),
                'stack_trace': traceback.format_exc()
            }
            return web.json_response(error_context, status=500)
    
    async def start(self):
        """Start the REST API server"""

        app = web.Application()
        app.router.add_route('*', '/api/scan', self.handle_request)
        app.router.add_route('*', '/api/scan/{task_id}', self.handle_request)
        app.router.add_route('GET', '/api/results', self.handle_request)
        app.router.add_route('GET', '/api/health', self.handle_request)
        app.router.add_route('*', '/api/config', self.handle_request)
        
        runner = web.AppRunner(app)
        await runner.setup()
        site = web.TCPSite(runner, self.host, self.port)
        await site.start()
        
        logging.info(f"REST API server started on http://{self.host}:{self.port}")
        return runner
    
    async def stop(self):
        """Stop the REST API server"""
        if self.server:
            await self.server.cleanup()
        self.task_storage.close()
        # Issue U3 fix: Cancel background tasks
        if hasattr(self, 'async_task_manager'):
            try:
                await self.async_task_manager.cancel_all()
            except Exception as e:
                logging.error(f"Error cancelling REST API server background tasks: {e}")
        # Issue U3 fix: Clear instance task set
        if hasattr(self, '_background_tasks'):
            try:
                with self._background_tasks_lock:
                    self._background_tasks.clear()
            except Exception as e:
                logging.error(f"Error clearing REST API server task set: {e}")

    async def close(self):
        """Alias for stop() method for compatibility"""
        await self.stop()


class DeepOSFingerprinter:
    """
    Enhanced OS fingerprinting with deep TCP stack analysis.
    Analyzes TTL, window size, ISN, and other TCP characteristics.
    """
    
    # OS fingerprinting database based on TCP stack characteristics
    OS_SIGNATURES = {
        'Windows': {
            'ttl_range': (64, 128),
            'window_sizes': [8192, 16384, 65535],
            'isn_increment': 'random',
            'flags': ['MSS', 'NOP', 'WS', 'SACK_PERM']
        },
        'Linux': {
            'ttl_range': (64, 64),
            'window_sizes': [5840, 5792, 14600, 29200, 43890, 57344],
            'isn_increment': 'cryptographic',
            'flags': ['MSS', 'SACK_PERM', 'TS', 'NOP', 'WS']
        },
        'macOS': {
            'ttl_range': (64, 64),
            'window_sizes': [65535],
            'isn_increment': 'random',
            'flags': ['MSS', 'NOP', 'WS', 'SACK_PERM', 'TS']
        },
        'BSD': {
            'ttl_range': (64, 64),
            'window_sizes': [65535, 57344],
            'isn_increment': 'random',
            'flags': ['MSS', 'NOP', 'SACK_PERM']
        },
        'Cisco': {
            'ttl_range': (255, 255),
            'window_sizes': [4128, 8192, 16384],
            'isn_increment': 'incremental',
            'flags': ['MSS', 'NOP']
        },
        'Android': {
            'ttl_range': (64, 64),
            'window_sizes': [14600, 29200],
            'isn_increment': 'cryptographic',
            'flags': ['MSS', 'SACK_PERM', 'TS', 'NOP', 'WS']
        }
    }
    
    def __init__(self):
        self.fingerprint_cache = {}
        
    async def fingerprint_host(self, host, port=80, timeout=DEFAULT_HEALTH_CHECK_TIMEOUT):
        """
        Perform deep OS fingerprinting on a target host.
        
        Args:
            host: Target hostname or IP
            port: Target port (default 80)
            timeout: Connection timeout in seconds
            
        Returns:
            dict: Fingerprinting results with OS detection confidence
        """
        cache_key = f"{host}:{port}"
        if cache_key in self.fingerprint_cache:
            return self.fingerprint_cache[cache_key]
        
        results = {
            'host': host,
            'port': port,
            'tcp_analysis': {},
            'os_candidates': [],
            'confidence': 0.0,
            'detected_os': 'unknown'
        }
        
        try:
            # Perform TCP SYN analysis
            tcp_data = await self._analyze_tcp_stack(host, port, timeout)
            results['tcp_analysis'] = tcp_data
            
            # Match against OS signatures
            os_matches = self._match_os_signatures(tcp_data)
            results['os_candidates'] = os_matches
            
            if os_matches:
                best_match = os_matches[0]
                results['detected_os'] = best_match['os']
                results['confidence'] = best_match['confidence']
            
            # Cache results
            self.fingerprint_cache[cache_key] = results
            
        except (ConnectionError, socket.timeout, socket.gaierror, OSError) as e:
            import traceback
            results['error'] = str(e)
            error_details = f"OS fingerprinting failed for {host}:{port}\n"
            error_details += f"Exception Type: {type(e).__name__}\n"
            error_details += f"Error: {e}\n"
            error_details += f"Timestamp: {datetime.now().isoformat()}\n"
            error_details += f"Stack Trace:\n{traceback.format_exc()}"
            logging.error(error_details)
        
        return results
    
    async def _analyze_tcp_stack(self, host, port, timeout):
        """
        Analyze TCP stack characteristics via SYN/SYN-ACK handshake.
        Enhanced with proper TCP fingerprinting using various techniques.
        """
        import socket
        import struct
        import time
        
        tcp_data = {
            'ttl': None,
            'window_size': None,
            'isn': None,
            'tcp_flags': [],
            'mss': None,
            'timestamp': None,
            'window_scaling': None,
            'sack_permitted': False,
            'ip_id': None,
            'rtt': None
        }
        
        try:
            # Try to use scapy if available for advanced fingerprinting
            if SCAPY_AVAILABLE:
                logging.info("Using scapy for advanced TCP fingerprinting")

                # Send SYN packet with various options
                syn_packet = IP(dst=host)/TCP(dport=port, flags='S', options=[
                    ('MSS', 1460),
                    ('NOP', None),
                    ('WScale', 7),
                    ('NOP', None),
                    ('NOP', None),
                    ('SAckOK', '')
                ])
                
                start_time = time.time()
                ans, unans = sr(syn_packet, timeout=timeout, verbose=0)
                rtt = (time.time() - start_time) * 1000  # Convert to milliseconds
                tcp_data['rtt'] = round(rtt, 2)

                if ans:
                    for sent, received in ans:
                        if received.haslayer(TCP):
                            tcp_layer = received[TCP]
                            
                            # Extract TCP flags
                            tcp_data['tcp_flags'] = [
                                flag for flag in ['F', 'S', 'R', 'P', 'A', 'U', 'E', 'C']
                                if getattr(tcp_layer, flag, False)
                            ]
                            
                            # Extract window size
                            tcp_data['window_size'] = tcp_layer.window
                            
                            # Extract ISN (Initial Sequence Number)
                            tcp_data['isn'] = tcp_layer.seq
                            
                            # Extract TTL from IP layer
                            if received.haslayer(IP):
                                tcp_data['ttl'] = received[IP].ttl
                                tcp_data['ip_id'] = received[IP].id
                            
                            # Extract TCP options
                            tcp_options = {}
                            for opt in tcp_layer.options:
                                if opt[0] == 'MSS':
                                    tcp_data['mss'] = opt[1]
                                elif opt[0] == 'WScale':
                                    tcp_data['window_scaling'] = opt[1]
                                elif opt[0] == 'SAckOK':
                                    tcp_data['sack_permitted'] = True
                                elif opt[0] == 'Timestamp':
                                    if len(opt) > 1:
                                        tcp_data['timestamp'] = opt[1]
                            
                            logging.error(f"TCP fingerprinting results: {tcp_data}")
                            break
            else:
                logging.info("Scapy not available, using socket-based analysis")
                # Fallback to socket-based analysis
                s_connect = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s_connect.settimeout(timeout)
                
                start_time = time.time()
                s_connect.connect((host, port))
                rtt = (time.time() - start_time) * 1000
                tcp_data['rtt'] = round(rtt, 2)
                
                # Get socket options for window size
                try:
                    tcp_data['window_size'] = s_connect.getsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF)
                    tcp_data['mss'] = s_connect.getsockopt(socket.IPPROTO_TCP, socket.TCP_MAXSEG)
                except (socket.error, AttributeError):
                    pass
                
                # Get TCP_INFO if available (Linux)
                try:
                    tcp_info = s_connect.getsockopt(socket.SOL_TCP, socket.TCP_INFO, 92)  # struct tcp_info size
                    if tcp_info:
                        # Parse tcp_info structure (platform-dependent)
                        import struct
                        # Linux tcp_info structure parsing
                        if len(tcp_info) >= 92:
                            # Unpack based on Linux kernel struct tcp_info
                            # Fields: state, ca_state, retransmits, probes, backoff, options, snd_wscale, rcv_wscale,
                            # rto, rtt, rttvar, snd_ssthresh, snd_cwnd, advmss, reordering, rcv_rtt, rcv_space,
                            # total_retrans, and more...
                            try:
                                # Parse key fields (little-endian for x86_64)
                                state = struct.unpack('B', tcp_info[0:1])[0]
                                rtt = struct.unpack('I', tcp_info[16:20])[0]  # Round-trip time in microseconds
                                rttvar = struct.unpack('I', tcp_info[20:24])[0]  # RTT variance
                                snd_cwnd = struct.unpack('I', tcp_info[28:32])[0]  # Send congestion window
                                advmss = struct.unpack('I', tcp_info[36:40])[0]  # Advertised MSS
                                
                                tcp_data['tcp_state'] = state
                                if rtt > 0:
                                    tcp_data['tcp_rtt_us'] = rtt
                                    tcp_data['tcp_rtt_ms'] = rtt / 1000
                                if rttvar > 0:
                                    tcp_data['tcp_rttvar_us'] = rttvar
                                if snd_cwnd > 0:
                                    tcp_data['tcp_cwnd'] = snd_cwnd
                                if advmss > 0:
                                    tcp_data['tcp_advmss'] = advmss
                            except (struct.error, IndexError):
                                pass
                except (socket.error, AttributeError):
                    pass
                
                s_connect.close()
            
            # Perform HTTP analysis for additional OS clues
            http_data = await self._analyze_http_headers(host, port, timeout)
            tcp_data.update(http_data)
            
        except PermissionError:
            logging.error("Raw socket requires admin privileges, falling back to HTTP analysis")
            http_data = await self._analyze_http_headers(host, port, timeout)
            tcp_data.update(http_data)
            
        except (socket.timeout, socket.gaierror, ConnectionError, OSError) as e:
            import traceback
            error_details = f"TCP analysis failed for {host}:{port}\n"
            error_details += f"Exception Type: {type(e).__name__}\n"
            error_details += f"Error: {e}\n"
            error_details += f"Timestamp: {datetime.now().isoformat()}\n"
            error_details += f"Stack Trace:\n{traceback.format_exc()}"
            logging.error(error_details)
            http_data = await self._analyze_http_headers(host, port, timeout)
            tcp_data.update(http_data)
        
        return tcp_data
    
    async def _analyze_http_headers(self, host, port, timeout):
        """Analyze HTTP headers for OS clues"""
        import aiohttp
        
        http_data = {
            'server_header': '',
            'x_powered_by': '',
            'via': ''
        }
        
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(f"http://{host}:{port}", 
                                        timeout=TIMEOUT_PROFILES['default'].to_client_timeout()) as resp:
                    headers = response_headers(resp)
                    
                    http_data['server_header'] = headers.get('Server', '')
                    http_data['x_powered_by'] = headers.get('X-Powered-By', '')
                    http_data['via'] = headers.get('Via', '')
                    
        except (aiohttp.ClientError, asyncio.TimeoutError, ConnectionError, ConnectionRefusedError) as e:
            # Log connection failures as debug info to reduce noise
            if isinstance(e, ConnectionRefusedError):
                logging.debug(f"HTTP header analysis: No service listening on {host}:{port}")
            else:
                import traceback
                error_details = f"HTTP header analysis failed for {host}:{port}\n"
                error_details += f"Exception Type: {type(e).__name__}\n"
                error_details += f"Error: {e}\n"
                error_details += f"Timestamp: {datetime.now().isoformat()}\n"
                error_details += f"Stack Trace:\n{traceback.format_exc()}"
                logging.debug(error_details)  # Changed from error to debug
        
        return http_data

    def _match_os_signatures(self, tcp_data):
        """Match TCP data against OS signature database"""
        matches = []
        
        for os_name, signature in self.OS_SIGNATURES.items():
            score = 0
            max_score = 0
            
            # Check TTL
            ttl = tcp_data.get('ttl')
            if ttl and signature['ttl_range'][0] <= ttl <= signature['ttl_range'][1]:
                score += 1
            max_score += 1
            
            # Check window size
            window = tcp_data.get('window_size')
            if window and window in signature['window_sizes']:
                score += 1
            max_score += 1
            
            # Check server header for additional clues
            server = tcp_data.get('server_header') or ''
            server = server.lower() if server else ''
            if os_name.lower() in server:
                score += 2
            max_score += 2
            
            # Calculate confidence
            confidence = score / max_score if max_score > 0 else 0
            
            if confidence > 0.3:  # Minimum threshold
                matches.append({ 'os': os_name, 'confidence': confidence, 'score': score, 'max_score': max_score })

        # Sort by confidence
        matches.sort(key=lambda x: x['confidence'], reverse=True)

        return matches
    
    def clear_cache(self):
        """Clear fingerprinting cache"""
        self.fingerprint_cache.clear()


class CVETemplateEngine:
    """
    Plugin/Template Engine for CVE detection (Nuclei-style integration).
    
    Allows users to drop YAML/JSON files defining CVEs with:
    - Request headers and body
    - Detection regex patterns
    - Version requirements
    - Severity and CVSS scores
    
    This makes the scanner infinitely extensible without code changes.
    """
    
    def __init__(self, template_directory=None):
        self.template_directory = template_directory or os.path.join(os.path.dirname(__file__), 'cve_templates')
        self.templates = {}
        self.template_cache = {}
        self.version_engine = None  # Will be set by VersionDetectionEngine
        self._ensure_template_directory()
        self._load_templates()
        
    def _ensure_template_directory(self):
        """Ensure the template directory exists."""
        if not os.path.exists(self.template_directory):
            os.makedirs(self.template_directory)
            logging.info(f"Created CVE template directory: {self.template_directory}")
            
    def _load_templates(self):
        """Load all CVE templates from the template directory."""
        self.templates = {}
        
        # Load YAML templates
        yaml_files = []
        try:
            yaml_files = glob.glob(os.path.join(self.template_directory, '*.yaml'))
            yaml_files.extend(glob.glob(os.path.join(self.template_directory, '*.yml')))
        except (OSError, FileNotFoundError, PermissionError) as e:
            logging.error(f"Error searching for YAML templates: {e}")
        
        # Load JSON templates
        json_files = []
        try:
            json_files = glob.glob(os.path.join(self.template_directory, '*.json'))
        except (OSError, FileNotFoundError, PermissionError) as e:
            logging.error(f"Error searching for JSON templates: {e}")
        
        for template_file in yaml_files + json_files:
            try:
                template = self._load_template_file(template_file)
                if template:
                    cve_id = template.get('id', template.get('cve_id', os.path.basename(template_file)))
                    self.templates[cve_id] = template
                    logging.info(f"Loaded CVE template: {cve_id} from {template_file}")
            except (IOError, OSError, ValueError, KeyError, yaml.YAMLError, json.JSONDecodeError) as e:
                import traceback
                error_details = f"Failed to load template {template_file}\n"
                error_details += f"Exception Type: {type(e).__name__}\n"
                error_details += f"Error: {e}\n"
                error_details += f"Timestamp: {datetime.now().isoformat()}\n"
                error_details += f"Stack Trace:\n{traceback.format_exc()}"
                logging.error(error_details)
                
        logging.info(f"Loaded {len(self.templates)} CVE templates")
        
    def _load_template_file(self, file_path):
        """Load a single template file (YAML or JSON)."""
        file_ext = os.path.splitext(file_path)[1].lower()
        
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                if file_ext in ['.yaml', '.yml']:
                    if not YAML_AVAILABLE:
                        logging.error("YAML library not available, cannot load YAML templates")
                        return None
                    return yaml.safe_load(f)
                elif file_ext == '.json':
                    return json.load(f)
                else:
                    logging.error(f"Unsupported template format: {file_ext}")
                    return None
        except ImportError as e:
            logging.error(f"Missing required library for template loading: {e}")
            return None
        except (IOError, OSError, ValueError, Exception) as e:
            logging.error(f"Error loading template file {file_path}: {e}")
            return None
            
    def add_template(self, template_dict, template_id=None):
        """
        Add a template programmatically.
        
        Args:
            template_dict: Dictionary containing template definition
            template_id: Optional template ID (uses template['id'] if not provided)
        """
        template_id = template_id or template_dict.get('id', template_dict.get('cve_id'))
        if template_id:
            self.templates[template_id] = template_dict
            logging.info(f"Added CVE template: {template_id}")
            
    def get_template(self, template_id):
        """Get a specific template by ID."""
        return self.templates.get(template_id)
        
    def get_templates_by_software(self, software_name):
        """Get all templates for a specific software."""
        matching_templates = {}
        for template_id, template in self.templates.items():
            if template.get('software', '').lower() == software_name.lower():
                matching_templates[template_id] = template
        return matching_templates
        
    def get_templates_by_severity(self, severity):
        """Get all templates with a specific severity level."""
        severity = severity.upper()
        matching_templates = {}
        for template_id, template in self.templates.items():
            if template.get('severity', '').upper() == severity:
                matching_templates[template_id] = template
        return matching_templates
        
    def validate_template(self, template):
        """
        Validate a template structure.
        
        Returns:
            tuple: (is_valid, error_message)
        """
        required_fields = ['id', 'name', 'severity']
        
        for field in required_fields:
            if field not in template:
                return False, f"Missing required field: {field}"
                
        # Validate severity
        valid_severities = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO']
        if template.get('severity', '').upper() not in valid_severities:
            return False, f"Invalid severity: {template.get('severity')}"
            
        # Validate requests if present
        if 'requests' in template:
            if not isinstance(template['requests'], list):
                return False, "Requests must be a list"
                
            for request in template['requests']:
                if 'method' not in request or 'path' not in request:
                    return False, "Each request must have 'method' and 'path'"
                    
        return True, None
        
    def apply_template_to_vulnerability(self, vuln):
        """
        Apply template information to enhance vulnerability detection.
        
        Args:
            vuln: Vulnerability dictionary
            
        Returns:
            dict: Enhanced vulnerability dictionary
        """
        vuln_type = vuln.get('type', '').lower()
        
        # Search for matching templates based on vulnerability type
        for template_id, template in self.templates.items():
            template_type = template.get('type', '').lower()
            
            # Check if template matches vulnerability type
            if template_type in vuln_type or vuln_type in template_type:
                # Add template information to vulnerability
                vuln['template_id'] = template_id
                vuln['template_name'] = template.get('name', template_id)
                
                # Add additional template information
                if 'description' in template and 'description' not in vuln:
                    vuln['description'] = template['description']
                
                if 'severity' in template:
                    vuln['template_severity'] = template['severity']
                
                if 'cvss_score' in template:
                    vuln['template_cvss'] = template['cvss_score']
                
                if 'references' in template:
                    vuln['references'] = template['references']
                
                # Add detection methods from template
                if 'detection' in template:
                    vuln['detection_methods'] = template['detection']
                
                # If template has request patterns, add them for testing
                if 'requests' in template:
                    vuln['template_requests'] = template['requests']
                
                logging.error(f"Enhanced vulnerability {vuln_type} with template {template_id}")
                break
        
        return vuln
    
    def generate_detection_request(self, template_id, base_url, parameters=None):
        """
        Generate detection request parameters from a template.
        
        Args:
            template_id: Template identifier
            base_url: Target base URL
            parameters: Optional parameters to substitute in template
            
        Returns:
            dict: Request parameters (method, url, headers, body, etc.)
        """
        template = self.get_template(template_id)
        if not template:
            return None
            
        if 'requests' not in template or not template['requests']:
            return None
            
        # Use the first request from the template
        request_config = template['requests'][0]
        
        # Build the full URL
        path = request_config.get('path', '/')
        url = urljoin(base_url, path)
        
        # Substitute parameters if provided
        if parameters:
            for param_key, param_value in parameters.items():
                url = url.replace(f'{{{param_key}}}', str(param_value))
                
        # Build request parameters
        request_params = {
            'method': request_config.get('method', 'GET'),
            'url': url,
            'headers': request_config.get('headers', {}),
            'body': request_config.get('body', None),
            'cookies': request_config.get('cookies', {}),
        }
        
        # Add query parameters if present
        if 'query_parameters' in request_config:
            query_params = request_config['query_parameters']
            if parameters:
                # Substitute parameters in query values
                for key, value in query_params.items():
                    if isinstance(value, str):
                        for param_key, param_value in parameters.items():
                            value = value.replace(f'{{{param_key}}}', str(param_value))
                        query_params[key] = value
            request_params['params'] = query_params
            
        return request_params
        
    def check_detection_patterns(self, template_id, response_content, response_headers, status_code):
        """
        Check if response matches detection patterns from template.
        
        Args:
            template_id: Template identifier
            response_content: Response body content
            response_headers: Response headers
            status_code: HTTP status code
            
        Returns:
            tuple: (is_detected, matched_patterns, confidence)
        """
        template = self.get_template(template_id)
        if not template:
            return False, [], 0
            
        matched_patterns = []
        confidence = 0
        
        # Check status code if specified
        if 'status_code' in template:
            expected_status = template['status_code']
            if isinstance(expected_status, list):
                if status_code in expected_status:
                    matched_patterns.append(f"status_code:{status_code}")
                    confidence += 0.3
            elif status_code == expected_status:
                matched_patterns.append(f"status_code:{status_code}")
                confidence += 0.3
                
        # Check content patterns
        if 'matchers' in template:
            for matcher in template['matchers']:
                matcher_type = matcher.get('type', 'word')
                
                if matcher_type == 'word':
                    # Word matching
                    words = matcher.get('words', [])
                    for word in words:
                        if word in response_content:
                            matched_patterns.append(f"word:{word}")
                            confidence += 0.2
                            
                elif matcher_type == 'regex':
                    # Regex matching
                    patterns = matcher.get('regex', [])
                    for pattern in patterns:
                        try:
                            if re.search(pattern, response_content, re.IGNORECASE):
                                matched_patterns.append(f"regex:{pattern}")
                                confidence += 0.4
                        except re.error:
                            logging.error(f"Invalid regex pattern: {pattern}")
                            
                elif matcher_type == 'binary':
                    # Binary matching
                    binaries = matcher.get('binary', [])
                    for binary in binaries:
                        if binary.encode() in response_content.encode():
                            matched_patterns.append(f"binary:{binary}")
                            confidence += 0.3
                            
                elif matcher_type == 'status':
                    # Status code matching
                    expected_status = matcher.get('status')
                    if status_code == expected_status:
                        matched_patterns.append(f"matcher_status:{status_code}")
                        confidence += 0.5
                        
        # Check header patterns
        if 'header_matchers' in template:
            for header_matcher in template['header_matchers']:
                header_name = header_matcher.get('name')
                expected_value = header_matcher.get('value')
                
                if header_name in response_headers:
                    actual_value = response_headers[header_name]
                    if expected_value in actual_value:
                        matched_patterns.append(f"header:{header_name}")
                        confidence += 0.3
                        
        # Normalize confidence to 0-100 range
        confidence = min(confidence * 100, 100)
        
        is_detected = confidence >= (template.get('confidence_threshold', 50))
        
        return is_detected, matched_patterns, confidence
        
    def create_sample_template(self, cve_id, software, name, severity, description):
        """
        Create a sample CVE template structure.
        
        Args:
            cve_id: CVE identifier (e.g., CVE-2024-1234)
            software: Affected software name
            name: Template name
            severity: Severity level (CRITICAL, HIGH, MEDIUM, LOW)
            description: Vulnerability description
            
        Returns:
            dict: Sample template structure
        """
        return {
            'id': cve_id,
            'info': {
                'name': name,
                'severity': severity,
                'description': description,
                'author': 'Auto-generated',
                'software': software
            },
            'requests': [
                {
                    'method': 'GET',
                    'path': '/vulnerable-endpoint',
                    'headers': {
                        'User-Agent': 'Scanner-UA'
                    },
                    'query_parameters': {
                        'param1': 'test_value'
                    }
                }
            ],
            'matchers': [
                {
                    'type': 'regex',
                    'regex': [
                        r'vulnerability_pattern_1',
                        r'vulnerability_pattern_2'
                    ]
                },
                {
                    'type': 'word',
                    'words': [
                        'error_message',
                        'vulnerable_component'
                    ]
                }
            ],
            'severity': severity,
            'confidence_threshold': 70
        }
        
    def save_template(self, template, filename=None):
        """
        Save a template to a file.
        
        Args:
            template: Template dictionary
            filename: Optional filename (uses template ID if not provided)
        """
        if not filename:
            template_id = template.get('id', template.get('cve_id', 'template'))
            filename = f"{template_id}.yaml"
            
        file_path = os.path.join(self.template_directory, filename)
        
        try:
            if YAML_AVAILABLE:
                with open(file_path, 'w', encoding='utf-8') as f:
                    yaml.dump(template, f, default_flow_style=False)
                logging.info(f"Saved template to: {file_path}")
                return True
            else:
                # Fallback to JSON if YAML is not available
                with open(file_path.replace('.yaml', '.json'), 'w', encoding='utf-8') as f:
                    json.dump(template, f, indent=2)
                logging.info(f"Saved template to JSON: {file_path}")
                return True
        except (IOError, OSError, PermissionError, ValueError) as e:
            logging.error(f"Failed to save template: {e}")
            return False


class VersionDetectionEngine:
    """
    Software version detection and CVE signature database.
    Enables intelligent version-based vulnerability testing instead of blind payload injection.
    
    Now integrated with CVETemplateEngine for extensible template-based detection.
    """
    
    def __init__(self, template_directory=None, cve_feed_integration=None):
        self.version_cache = {}
        self.software_signatures = self._build_software_signatures()
        self.cve_version_mappings = self._build_cve_version_mappings()
        self.template_engine = CVETemplateEngine(template_directory)
        self.cve_feed_integration = cve_feed_integration
        
        # Link template engine back to version detection for cross-referencing
        if self.template_engine:
            self.template_engine.version_engine = self
        
