# Custom JSONDecoder with nesting depth and key count limit to prevent RecursionError
class SafeJSONDecoder(json.JSONDecoder):
    """JSON decoder that limits nesting depth and total key count to prevent RecursionError"""
    def __init__(self, *args, **kwargs):
        self.max_depth = kwargs.pop('max_depth', 100)
        self.max_keys = kwargs.pop('max_keys', 10000)
        super().__init__(*args, **kwargs)
    
    def decode(self, s, _w=json.decoder.WHITESPACE.match):
        """Decode with depth and key count tracking"""
        depth = 0
        max_depth = self.max_depth
        max_keys = self.max_keys
        key_count = 0
        in_string = False
        escape = False
        string_char = None  # '"' or "'"
        
        # Scan for depth violations and key count limits with proper string/escape tracking
        for i, char in enumerate(s):
            if escape:
                # Previous char was backslash, this char is escaped
                escape = False
                continue
            
            if char == '\\':
                # Start of escape sequence
                escape = True
                continue
            
            if in_string:
                # Inside a string literal
                if char == string_char:
                    # End of string
                    in_string = False
                    string_char = None
                # All other chars inside strings are ignored for depth/key counting
                continue
            
            # Not in string, check for string start
            if char in '"\'':
                in_string = True
                string_char = char
                continue
            
            # Count depth and keys only when not in string
            if char in '{[':
                depth += 1
                if depth > max_depth:
                    raise json.JSONDecodeError(
                        f"JSON nesting depth exceeds maximum allowed depth of {max_depth}",
                        s,
                        i
                    )
            elif char in '}]':
                depth -= 1
            elif char == ':':
                # Colon indicates a key-value pair, count as one key
                key_count += 1
                if key_count > max_keys:
                    raise json.JSONDecodeError(
                        f"JSON key count exceeds maximum allowed keys of {max_keys}",
                        s,
                        i
                    )
        
        return super().decode(s, _w)

# Safe JSON loading function with depth and key count limit
def safe_json_loads(s, max_depth=100, max_keys=10000):
    """Load JSON with nesting depth and key count limits to prevent RecursionError"""
    try:
        return json.loads(s, cls=SafeJSONDecoder, max_depth=max_depth, max_keys=max_keys)
    except json.JSONDecodeError as e:
        if "nesting depth" in str(e):
            logging.error(f"JSON nesting depth exceeded: {e}")
            raise
        if "key count" in str(e):
            logging.error(f"JSON key count exceeded: {e}")
            raise
        raise

