# FIX: Custom asyncio exception handler to suppress expected WebSocket send failures
# This reduces warning noise during WebSocket fuzzing when connections close during writes
def _setup_asyncio_warning_suppression():
    """Setup custom asyncio exception handler to suppress expected WebSocket send failures."""
    import asyncio

    loop = get_loop()

    original_handler = loop.get_exception_handler()

    def custom_handler(loop, context):
        exception = context.get('exception', '')
        if exception and 'socket.send' in str(exception):
            # Suppress expected WebSocket send failures during fuzzing
            return
        if original_handler:
            original_handler(loop, context)

    loop.set_exception_handler(custom_handler)

