# SHARED ENGINE MIXINS: SESSION & GRPC REFLECTION UTILITIES
# ---------------------------------------------------------------------
def grpc_reflect(stub, request, timeout=5, metadata=None):
    """
    Centralized gRPC reflection call that always wraps request in iter([request]).
    This is a module-level function to be used by InjectionEngine, OmegaDAST, and ValidationEngine.
    """
    kwargs = {'timeout': timeout}
    if metadata is not None:
        kwargs['metadata'] = metadata
    return stub.ServerReflectionInfo(iter([request]), **kwargs)

_grpc_reflect = grpc_reflect


class SessionUtilsMixin:
    """Shared mixin providing unified fresh HTTP session resolution."""

    def _get_fresh_session(self):
        """
        Get a fresh session from the session manager if available.
        This ensures we use a valid session that hasn't been closed or invalidated.
        
        Returns:
            A valid session object, or the stored session if no session_manager is available
        """
        session_manager = getattr(self, 'session_manager', None)
        if session_manager and hasattr(session_manager, 'async_session') and session_manager.async_session:
            async_sess = session_manager.async_session
            if hasattr(async_sess, 'session') and async_sess.session:
                return async_sess.session
            return async_sess
        session = getattr(self, 'session', None)
        if session and hasattr(session, 'session') and session.session:
            return session.session
        return session


class GRPCUtilsMixin:
    """Shared mixin providing unified gRPC reflection utilities."""

    def _grpc_reflect(self, stub, request, timeout=5, metadata=None):
        """
        Centralized gRPC reflection call that always wraps request in iter([request]).
        Can be called as an instance method self._grpc_reflect(...)
        """
        return grpc_reflect(stub, request, timeout=timeout, metadata=metadata)

    def grpc_reflect(self, stub, request, timeout=5, metadata=None):
        """
        Instance access to grpc_reflect.
        """
        return grpc_reflect(stub, request, timeout=timeout, metadata=metadata)


class SharedEngineMixin(SessionUtilsMixin, GRPCUtilsMixin):
    """
    Combined shared mixin for InjectionEngine, ValidationEngine, and OmegaDAST.
    Provides unified session management and gRPC reflection utilities.
    """
    
    async def _add_vulnerability(self, vuln):
        """
        Report a vulnerability. Delegates to vulnerability_callback if available.
        
        Args:
            vuln: Vulnerability dictionary with standard fields
        """
        if self.vulnerability_callback:
            if asyncio.iscoroutinefunction(self.vulnerability_callback):
                await self.vulnerability_callback(vuln)
            else:
                self.vulnerability_callback(vuln)

