# ---------------------------------------------------------------------
# BEAUTIFULSOUP CACHING
# ---------------------------------------------------------------------
class BeautifulSoupCache:
    """
    Thread-safe cache for BeautifulSoup objects to avoid redundant parsing.
    Caches based on HTML content hash to handle identical content efficiently.
    Implements memory-aware eviction to prevent excessive memory consumption.
    Phase 1.3: Enhanced with async support for parallel HTML parsing.
    """
    def __init__(self, max_size=500, max_memory_mb=200):
        if not BS4_AVAILABLE:
            logging.warning("BeautifulSoup not available, cache disabled")
            self._disabled = True
            return

        self._disabled = False
        self._cache = {}
        self._max_size = max_size  # Maximum number of entries
        self._max_memory_bytes = max_memory_mb * 1024 * 1024  # Maximum memory in bytes
        self._lock = threading.Lock()
        self._hits = 0
        self._misses = 0
        self._current_memory = 0  # Track current memory usage
        self._access_order = []  # Track access order for LRU eviction
        self._executor = ThreadPoolExecutor(max_workers=4)  # For async parsing
        self._entry_timestamps = {}  # Track when entries were added for TTL-based cleanup
        self._entry_sizes = {}  # Track pre-computed memory sizes for cached entries
        self._cleanup_task = None  # Background cleanup task
        self._cleanup_running = False
    
    def _get_hash(self, html_content: str) -> str:
        """Generate a hash key for HTML content."""
        return hashlib.md5(html_content.encode('utf-8')).hexdigest()
    
    def _estimate_memory_size(self, soup: BeautifulSoup) -> int:
        """
        Estimate memory size of a BeautifulSoup object.
        This is a rough estimate based on string length and object overhead.
        """
        try:
            # Estimate based on string representation length and object overhead
            # BeautifulSoup objects are typically 2-3x the size of the HTML string
            html_str = str(soup)
            base_size = len(html_str.encode('utf-8'))
            # Add overhead for BeautifulSoup's internal structures
            estimated_size = base_size * 3  # Conservative estimate
            return estimated_size
        except Exception as e:
            logging.error(e)
            # Fallback to a reasonable default estimate
            return 1024 * 1024  # 1MB default estimate
    
    def _evict_if_needed(self, new_item_size: int):
        """
        Evict entries if adding a new item would exceed memory or size limits.
        Uses LRU eviction policy.
        """
        # Check if we need to evict based on count
        while len(self._cache) >= self._max_size:
            if not self._access_order:
                break
            oldest_key = self._access_order.pop(0)
            if oldest_key in self._cache:
                old_item = self._cache.pop(oldest_key)
                old_size = self._entry_sizes.pop(oldest_key, 0)
                self._current_memory -= old_size

        # Check if we need to evict based on memory
        while self._current_memory + new_item_size > self._max_memory_bytes:
            if not self._access_order:
                break
            oldest_key = self._access_order.pop(0)
            if oldest_key in self._cache:
                old_item = self._cache.pop(oldest_key)
                old_size = self._entry_sizes.pop(oldest_key, 0)
                self._current_memory -= old_size
    
    def get(self, html_content: str, parser: str = 'html.parser') -> BeautifulSoup:
        """
        Get cached BeautifulSoup object or create new one if not cached.

        Args:
            html_content: The HTML content to parse
            parser: The parser to use (default: 'html.parser')

        Returns:
            BeautifulSoup object
        """
        if self._disabled:
            return None

        # Handle empty or invalid content
        if not html_content or not isinstance(html_content, str):
            html_content = '<html></html>'
        
        # Check if content looks like a filename instead of HTML
        if len(html_content) < 100 and not any(tag in html_content.lower() for tag in ['<html', '<body', '<div', '<span', '<p>', '<a ']):
            # If it looks like a filename, treat it as such and try to read the file
            import os
            if os.path.exists(html_content):
                try:
                    with open(html_content, 'r', encoding='utf-8', errors='ignore') as f:
                        html_content = f.read()
                except Exception as e:
                    logging.error(e)
                    html_content = '<html></html>'
            else:
                # Not a valid file or HTML, use placeholder
                html_content = '<html></html>'
            
        content_hash = self._get_hash(html_content)
        cache_key = f"{content_hash}:{parser}"
        
        with self._lock:
            if cache_key in self._cache:
                self._hits += 1
                # Update access order for LRU
                if cache_key in self._access_order:
                    self._access_order.remove(cache_key)
                self._access_order.append(cache_key)
                return self._cache[cache_key]
            
            self._misses += 1
            
            # Create new BeautifulSoup object with explicit parser
            # Suppress the MarkupResemblesLocatorWarning and XMLParsedAsHTMLWarning
            with warnings.catch_warnings():
                warnings.filterwarnings("ignore", category=bs4.MarkupResemblesLocatorWarning)
                warnings.filterwarnings("ignore", message=".*XMLParsedAsHTMLWarning.*")
                soup = BeautifulSoup(html_content, 'html.parser')

            # Estimate memory size of new item
            new_item_size = self._estimate_memory_size(soup)

            # Evict entries if needed based on memory and size limits
            self._evict_if_needed(new_item_size)

            # Add new entry to cache with pre-computed size
            self._cache[cache_key] = soup
            self._entry_sizes[cache_key] = new_item_size
            self._current_memory += new_item_size
            self._access_order.append(cache_key)
            self._entry_timestamps[cache_key] = time.time()  # Track entry timestamp for cleanup
            
            return soup
    
    def clear(self):
        """Clear the cache."""
        with self._lock:
            self._cache.clear()
            self._access_order.clear()
            self._entry_timestamps.clear()
            self._entry_sizes.clear()
            self._current_memory = 0
            self._hits = 0
            self._misses = 0
    
    def get_stats(self) -> dict:
        """Get cache statistics."""
        with self._lock:
            total_requests = self._hits + self._misses
            hit_rate = (self._hits / total_requests * 100) if total_requests > 0 else 0
            memory_mb = self._current_memory / (1024 * 1024)
            return {
                'size': len(self._cache),
                'max_size': self._max_size,
                'memory_mb': f"{memory_mb:.2f}",
                'max_memory_mb': self._max_memory_bytes / (1024 * 1024),
                'hits': self._hits,
                'misses': self._misses,
                'hit_rate': f"{hit_rate:.2f}%"
            }
    
    def start_background_cleanup(self, ttl_seconds=3600, cleanup_interval=300):
        """
        Start background task to periodically clean up stale entries.
        
        Args:
            ttl_seconds: Time-to-live for cache entries in seconds (default: 1 hour)
            cleanup_interval: How often to run cleanup in seconds (default: 5 minutes)
        """
        if self._cleanup_running:
            return  # Already running
        
        self._cleanup_running = True
        self._ttl_seconds = ttl_seconds
        self._cleanup_interval = cleanup_interval
        
        def cleanup_worker():
            while self._cleanup_running:
                try:
                    try:
                        loop = asyncio.get_running_loop()
                        loop.run_in_executor(None, time.sleep, self._cleanup_interval)
                    except RuntimeError:
                        # No running loop, use blocking sleep
                        time.sleep(self._cleanup_interval)
                    self._cleanup_stale_entries()
                except Exception as e:
                    logging.error(f"Error in cache cleanup: {e}")
        
        self._cleanup_thread = threading.Thread(target=cleanup_worker, daemon=True)
        self._cleanup_thread.start()
        logging.info("BeautifulSoupCache background cleanup started")
    
    def stop_background_cleanup(self):
        """Stop the background cleanup task."""
        self._cleanup_running = False
        if hasattr(self, '_cleanup_thread') and self._cleanup_thread.is_alive():
            self._cleanup_thread.join(timeout=5)
        logging.info("BeautifulSoupCache background cleanup stopped")
    
    def _cleanup_stale_entries(self):
        """Remove entries that have exceeded their TTL."""
        current_time = time.time()
        stale_keys = []
        
        with self._lock:
            for cache_key, timestamp in self._entry_timestamps.items():
                if current_time - timestamp > self._ttl_seconds:
                    stale_keys.append(cache_key)
            
            for key in stale_keys:
                if key in self._cache:
                    old_item = self._cache.pop(key)
                    old_size = self._entry_sizes.pop(key, 0)
                    self._current_memory -= old_size
                    self._entry_timestamps.pop(key, None)
                    if key in self._access_order:
                        self._access_order.remove(key)
        
        if stale_keys:
            logging.info(f"Cleaned up {len(stale_keys)} stale BeautifulSoup cache entries")
    
    async def get_async(self, html_content: str, parser: str = 'html.parser', loop=None) -> BeautifulSoup:
        """
        Get cached BeautifulSoup object asynchronously or create new one if not cached.
        This method enables parallel HTML parsing for improved performance.

        Args:
            html_content: The HTML content to parse
            parser: The parser to use (default: 'html.parser')
            loop: Event loop for async operations (optional)

        Returns:
            BeautifulSoup object
        """
        if self._disabled:
            return None

        # Handle empty or invalid content
        if not html_content or not isinstance(html_content, str):
            html_content = '<html></html>'
        
        # Check if content looks like a filename instead of HTML
        if len(html_content) < 100 and not any(tag in html_content.lower() for tag in ['<html', '<body', '<div', '<span', '<p>', '<a ']):
            # If it looks like a filename, treat it as such and try to read the file
            import os
            if os.path.exists(html_content):
                try:
                    with open(html_content, 'r', encoding='utf-8', errors='ignore') as f:
                        html_content = f.read()
                except Exception as e:
                    logging.error(e)
                    html_content = '<html></html>'
            else:
                # Not a valid file or HTML, use placeholder
                html_content = '<html></html>'
        
        content_hash = self._get_hash(html_content)
        cache_key = f"{content_hash}:{parser}"
        
        with self._lock:
            if cache_key in self._cache:
                self._hits += 1
                # Update access order for LRU
                if cache_key in self._access_order:
                    self._access_order.remove(cache_key)
                self._access_order.append(cache_key)
                return self._cache[cache_key]
        
        # Parse HTML in thread pool for parallel processing
        loop = loop or get_loop()
        
        def parse_html():
            # Create new BeautifulSoup object with explicit parser
            # Suppress the MarkupResemblesLocatorWarning and XMLParsedAsHTMLWarning
            with warnings.catch_warnings():
                warnings.filterwarnings("ignore", category=bs4.MarkupResemblesLocatorWarning)
                warnings.filterwarnings("ignore", message=".*XMLParsedAsHTMLWarning.*")
                return BeautifulSoup(html_content, parser)
        
        soup = await loop.run_in_executor(self._executor, parse_html)
        
        with self._lock:
            self._misses += 1
            
            # Check again if another thread added it while we were parsing
            if cache_key in self._cache:
                self._hits += 1
                return self._cache[cache_key]
            
            # Estimate memory size of new item
            new_item_size = self._estimate_memory_size(soup)

            # Evict entries if needed based on memory and size limits
            self._evict_if_needed(new_item_size)

            # Add new entry to cache with pre-computed size
            self._cache[cache_key] = soup
            self._entry_sizes[cache_key] = new_item_size
            self._current_memory += new_item_size
            self._access_order.append(cache_key)
            self._entry_timestamps[cache_key] = time.time()  # Track entry timestamp for cleanup
            
            return soup
    
    def shutdown(self):
        """Shutdown the thread pool executor."""
        self._executor.shutdown(wait=True)

# Global cache instance with memory-aware eviction (deprecated - use instance cache)
_bs4_cache = BeautifulSoupCache(max_size=1000, max_memory_mb=300)  # Increased for Phase 1.3 optimization

def get_cached_soup(html_content: str, parser: str = 'html.parser', scanner_instance=None) -> BeautifulSoup:
    """
    Convenience function to get cached BeautifulSoup object.

    Args:
        html_content: The HTML content to parse
        parser: The parser to use (default: 'html.parser')
        scanner_instance: Optional scanner instance to use instance cache (preferred)

    Returns:
        BeautifulSoup object
    """
    # Prefer instance cache if available
    if scanner_instance and hasattr(scanner_instance, 'bs4_cache'):
        return scanner_instance.bs4_cache.get(html_content, parser)
    # Fallback to global cache
    return _bs4_cache.get(html_content, parser)

async def get_cached_soup_async(html_content: str, parser: str = 'html.parser', loop=None, scanner_instance=None) -> BeautifulSoup:
    """
    Async convenience function to get cached BeautifulSoup object with parallel parsing.

    Args:
        html_content: The HTML content to parse
        parser: The parser to use (default: 'html.parser')
        loop: Event loop for async operations (optional)
        
    Returns:
        BeautifulSoup object
    """
    return await _bs4_cache.get_async(html_content, parser, loop)

def extract_form_parameters(form, playwright_page=None):
    """
    Extract form parameters with extended selector support.
    
    This function addresses Issue E4 by including:
    - Standard inputs: input, textarea, select
    - Buttons with name + value (form submission params)
    - contenteditable divs
    - Playwright mode: JavaScript FormData serialization for dynamic inputs
    
    Args:
        form: BeautifulSoup form element
        playwright_page: Optional Playwright page for JavaScript-based extraction
        
    Returns:
        list: List of parameter names found in the form
    """
    # If Playwright page is available, use JavaScript for accurate extraction
    if playwright_page and PLAYWRIGHT_AVAILABLE:
        try:
            # Use JavaScript to serialize FormData and get all real keys
            # This captures dynamically added inputs, buttons with name/value, and contenteditable elements
            js_script = """
            () => {
                const forms = document.querySelectorAll('form');
                const allKeys = new Set();
                
                forms.forEach(form => {
                    // Get all standard form elements
                    const formData = new FormData(form);
                    formData.forEach((value, key) => {
                        allKeys.add(key);
                    });
                    
                    // Also check for buttons with name attributes (not always included in FormData)
                    const buttons = form.querySelectorAll('button[name]');
                    buttons.forEach(button => {
                        allKeys.add(button.name);
                    });
                    
                    // Check for contenteditable divs with data-name or id
                    const contenteditables = form.querySelectorAll('[contenteditable]');
                    contenteditables.forEach(elem => {
                        if (elem.dataset.name) {
                            allKeys.add(elem.dataset.name);
                        } else if (elem.id) {
                            allKeys.add(elem.id);
                        }
                    });
                    
                    // Check for data-* attributes used as parameters by frameworks
                    const allElements = form.querySelectorAll('*');
                    allElements.forEach(elem => {
                        ['data-param', 'data-field', 'data-value', 'data-name'].forEach(attr => {
                            if (elem.dataset && elem.dataset[attr]) {
                                allKeys.add(elem.dataset[attr]);
                            }
                        });
                    });
                });
                
                return Array.from(allKeys);
            }
            """
            keys = playwright_page.evaluate(js_script)
            if keys:
                return keys
        except Exception as e:
            logging.warning(f"Playwright form parameter extraction failed: {e}")
    
    # Fallback to BeautifulSoup with extended selectors
    parameters = []
    
    # Standard form elements
    standard_elements = form.find_all(['input', 'textarea', 'select'])
    for elem in standard_elements:
        name = elem.get('name')
        if name:
            parameters.append(name)
    
    # Buttons with name + value (form submission params)
    buttons = form.find_all('button', attrs={'name': True})
    for button in buttons:
        name = button.get('name')
        if name:
            parameters.append(name)
    
    # contenteditable divs with data-name or id attributes
    contenteditable_divs = form.find_all('div', attrs={'contenteditable': True})
    for div in contenteditable_divs:
        # Check for data-name attribute (common in frameworks)
        name = div.get('data-name')
        if name:
            parameters.append(name)
        # Fallback to id if data-name not present
        else:
            elem_id = div.get('id')
            if elem_id:
                parameters.append(elem_id)
    
    # Check for data-* attributes used as parameters by frameworks
    # Common framework patterns: data-param, data-field, data-value
    all_elements = form.find_all(True)
    for elem in all_elements:
        for attr in elem.attrs:
            if attr.startswith('data-') and attr in ['data-param', 'data-field', 'data-value', 'data-name']:
                value = elem.get(attr)
                if value:
                    parameters.append(value)
    
    return parameters

def clear_bs4_cache():
    """Clear the global BeautifulSoup cache."""
    _bs4_cache.clear()

def get_bs4_cache_stats() -> dict:
    """Get statistics for the global BeautifulSoup cache."""
    return _bs4_cache.get_stats()

