class SQLGrammarDetector:
    """
    Grammar-based SQL injection detector that extracts offending tokens from error messages
    and confirms they match the injected payload.

    This implements signature-free detection by parsing SQL error messages with dialect-specific
    grammars to extract the offending syntax token, then verifying it appears in the payload.
    """
    
    def __init__(self, dialect='mysql'):
        self.dialect = dialect
    
    def detect(self, response_body: str, payload: str = None) -> dict:
        """
        Parse the response for SQL-like error patterns using dialect-specific grammar.
        Extract the offending token and confirm it matches a portion of the injected payload.
        
        Args:
            response_body: The HTTP response body to analyze
            payload: Optional payload that was injected (for token matching)
            
        Returns:
            dict: {
                'is_sqli': bool,
                'confidence': float,
                'dialect': str,
                'offending_token': str,
                'evidence': str,
                'reason': str
            }
        """
        import re
        
        result = {
            'is_sqli': False,
            'confidence': 0.0,
            'dialect': self.dialect,
            'offending_token': None,
            'evidence': '',
            'reason': ''
        }
        
        if not response_body:
            result['reason'] = 'Empty response body'
            return result
        
        # Normalize response to handle HTML entities and whitespace
        response_normalized = normalize_error_text(response_body)
        
        # Try to detect dialect if not specified
        detected_dialect = self._detect_dialect(response_normalized)
        if detected_dialect:
            self.dialect = detected_dialect
            result['dialect'] = detected_dialect
        
        # Extract offending token based on dialect-specific grammar
        offending_token = self._extract_offending_token(response_normalized, self.dialect)
        
        if not offending_token:
            result['reason'] = 'No offending token extracted from error message'
            return result
        
        result['offending_token'] = offending_token
        
        # If payload provided, confirm token matches payload
        if payload:
            if self._token_matches_payload(offending_token, payload):
                result['is_sqli'] = True
                result['confidence'] = 0.85
                result['evidence'] = f"Offending token '{offending_token}' found in payload"
                result['reason'] = f"SQLi confirmed via grammar-based token matching ({self.dialect})"
            else:
                result['confidence'] = 0.3
                result['reason'] = f"Token '{offending_token}' does not match payload - possible false positive"
        else:
            # Without payload, still report high confidence if token is SQL-like
            if self._is_sql_like_token(offending_token):
                result['is_sqli'] = True
                result['confidence'] = 0.7
                result['evidence'] = f"SQL-like offending token '{offending_token}' detected"
                result['reason'] = f"SQLi suspected via grammar-based token extraction ({self.dialect})"
            else:
                result['confidence'] = 0.4
                result['reason'] = f"Token '{offending_token}' not clearly SQL-like"
        
        return result
    
    def _detect_dialect(self, response: str) -> str:
        """
        Auto-detect SQL dialect from error message patterns.
        
        Returns:
            str: Detected dialect (mysql, postgresql, sqlserver, oracle, sqlite) or None
        """
        import re
        
        response_lower = response.lower()
        
        # MySQL/MariaDB patterns
        if re.search(r'\bmysql|mariadb\b', response_lower):
            return 'mysql'
        
        # PostgreSQL patterns
        if re.search(r'\bpostgresql|postgres|pg::|sqlstate\[', response_lower):
            return 'postgresql'
        
        # SQL Server patterns
        if re.search(r'\bsql server|microsoft sql|sqlserver|\[microsoft\]\[odbc', response_lower):
            return 'sqlserver'
        
        # Oracle patterns
        if re.search(r'\bora-|pls-|oracle\b', response_lower):
            return 'oracle'
        
        # SQLite patterns
        if re.search(r'\bsqlite\b', response_lower):
            return 'sqlite'
        
        return None
    
    def _extract_offending_token(self, response: str, dialect: str) -> str:
        """
        Extract the offending token from error message using dialect-specific grammar.
        
        Args:
            response: Normalized error message
            dialect: SQL dialect (mysql, postgresql, sqlserver, oracle, sqlite)
            
        Returns:
            str: Extracted offending token or None
        """
        import re
        
        if dialect == 'mysql':
            # MySQL: "You have an error in your SQL syntax near 'OR 1=1' at line 42"
            match = re.search(r"near\s+['\"]([^'\"]+)['\"]\s+at line", response, re.IGNORECASE)
            if match:
                return match.group(1)
            
            # MySQL: "near 'OR 1=1'"
            match = re.search(r"near\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
        
        elif dialect == 'postgresql':
            # PostgreSQL: "ERROR: syntax error at or near 'OR'"
            match = re.search(r"syntax error at or near\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
            
            # PostgreSQL: "ERROR: syntax error near 'OR'"
            match = re.search(r"syntax error near\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
        
        elif dialect == 'sqlserver':
            # MSSQL: "Incorrect syntax near 'OR'"
            match = re.search(r"Incorrect syntax near\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
            
            # MSSQL: "near 'OR'"
            match = re.search(r"near\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
        
        elif dialect == 'oracle':
            # Oracle: "ORA-00933: SQL command not properly ended"
            # Extract context from ORA errors - tokens usually appear after the error code
            match = re.search(r"ORA-\d{5}:[^']*", response, re.IGNORECASE)
            if match:
                # Return the full error message as context
                return match.group(0)
            
            # Oracle: "invalid identifier 'COLUMN_NAME'"
            match = re.search(r"invalid identifier\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
        
        elif dialect == 'sqlite':
            # SQLite: "near 'OR': syntax error"
            match = re.search(r"near\s+['\"]([^'\"]+)['\"]:\s*syntax error", response, re.IGNORECASE)
            if match:
                return match.group(1)
            
            # SQLite: "near 'OR'"
            match = re.search(r"near\s+['\"]([^'\"]+)['\"]", response, re.IGNORECASE)
            if match:
                return match.group(1)
        
        # Generic fallback: try to extract quoted tokens after "near"
        match = re.search(r"near\s+['\"]([^'\"]{1,50})['\"]", response, re.IGNORECASE)
        if match:
            return match.group(1)
        
        return None
    
    def _token_matches_payload(self, token: str, payload: str) -> bool:
        """
        Confirm the offending token matches a portion of the injected payload.
        
        Args:
            token: The offending token extracted from error message
            payload: The payload that was injected
            
        Returns:
            bool: True if token appears in payload (case-insensitive)
        """
        if not token or not payload:
            return False
        
        # Normalize both for comparison
        token_normalized = token.strip().lower()
        payload_normalized = payload.lower()
        
        # Direct match
        if token_normalized in payload_normalized:
            return True
        
        # Check for partial matches (token might be a substring of a payload token)
        # Split payload into SQL-like tokens
        import re
        payload_tokens = re.findall(r"[\w']+|[\"']+|[\-\+\*/=<>!]+", payload_normalized)
        
        for payload_token in payload_tokens:
            if token_normalized in payload_token or payload_token in token_normalized:
                return True
        
        return False
    
    def _is_sql_like_token(self, token: str) -> bool:
        """
        Check if the token looks like SQL syntax (without payload matching).
        
        Args:
            token: The token to check
            
        Returns:
            bool: True if token appears to be SQL syntax
        """
        if not token:
            return False
        
        import re
        token_lower = token.lower()
        
        # SQL keywords
        sql_keywords = [
            'select', 'insert', 'update', 'delete', 'drop', 'create', 'alter',
            'union', 'where', 'and', 'or', 'xor', 'not', 'in', 'is', 'null',
            'order', 'by', 'group', 'having', 'limit', 'offset', 'join', 'inner',
            'left', 'right', 'outer', 'on', 'as', 'from', 'into', 'values',
            'set', 'execute', 'exec', 'sp_', 'xp_', 'declare', 'cast', 'convert'
        ]
        
        # Check if token is a SQL keyword
        if token_lower in sql_keywords:
            return True
        
        # Check if token contains SQL operators
        if re.search(r'[=<>!]+|and|or|xor|not', token_lower):
            return True
        
        # Check if token looks like a SQL comment
        if re.search(r'--|#|/\*|\*/', token):
            return True
        
        # Check if token looks like a SQL function call
        if re.search(r'\w+\(|@@\w+', token_lower):
            return True
        
        return False

def normalize_dynamic_tokens(text: str) -> str:
    """
    Differential Response Analyzer: Removes dynamic tokens before comparing lengths.
    Ignores CSRF tokens, timestamps, session IDs, UUIDs, and other dynamic elements.
    """
    import re
    
    if not text:
        return text
    
    # Patterns for dynamic tokens to normalize
    dynamic_patterns = [
        # CSRF tokens and nonces
        r'csrf[_-]?token["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'nonce["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'_token["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'authenticity_token["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        
        # Timestamps (Unix timestamps, ISO dates, etc.)
        r'\b\d{10,13}\b',  # Unix timestamps (10 or 13 digits)
        r'\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}',  # ISO 8601 dates
        r'\d{2}/\d{2}/\d{4}\s+\d{2}:\d{2}:\d{2}',  # US date format
        
        # UUIDs and GUIDs
        r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}',
        r'\{[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\}',
        
        # Session IDs and random strings
        r'session[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        r'PHPSESSID["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        r'JSESSIONID["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        r'ASP\.NET_SessionId["\']?\s*[:=]\s*["\'][a-zA-Z0-9]{20,}["\']',
        
        # Request/Trace IDs
        r'request[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'trace[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        r'correlation[_-]?id["\']?\s*[:=]\s*["\'][a-zA-Z0-9/_-]{20,}["\']',
        
        # JWT tokens
        r'eyJ[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+',
        
        # Generic random hex/base64 strings (longer than 16 chars)
        r'["\'][a-zA-Z0-9/_-]{32,}["\']',
        
        # Cache busting parameters
        r'\?v=\d+',
        r'&v=\d+',
        r'\?_=\d+',
        r'&_=\d+',
    ]
    
    normalized = text
    for pattern in dynamic_patterns:
        normalized = re.sub(pattern, '[DYNAMIC]', normalized, flags=re.IGNORECASE)
    
    return normalized

