class PathTraversalContentMatcher:
    """
    Enhanced path traversal content matcher with multi-line support,
    URL/HTML decoding, and per-file-type pattern matching.
    """
    
    # Linux /etc/passwd patterns (require >= 2 of these signatures)
    ETC_PASSWD_SIGNATURES = [
        r'root:x:0:0:',
        r'daemon:x:',
        r'bin:x:',
        r'sys:x:',
        r'sync:x:',
        r'games:x:',
        r'man:x:',
        r'lp:x:',
        r'mail:x:',
        r'news:x:',
        r'uucp:x:',
        r'proxy:x:',
        r'www-data:x:',
        r'backup:x:',
        r'list:x:',
        r'irc:x:',
        r'gnats:x:',
        r'nobody:x:',
    ]
    
    # Linux id command output patterns
    LINUX_ID_PATTERNS = [
        r'uid=\d+\(',
        r'gid=\d+\(',
        r'groups=\d+\(',
    ]
    
    # Windows win.ini patterns
    WIN_INI_PATTERNS = [
        r'\[extensions\]',
        r'\[fonts\]',
        r'\[mci extensions\]',
        r'\[files\]',
        r'for 16-bit app support',
    ]
    
    # /proc/self/environ patterns (null-separated KEY=VALUE)
    PROC_ENVIRON_PATTERNS = [
        r'[A-Z_]+=\w+\x00',
        r'PATH=',
        r'HOME=',
        r'USER=',
        r'SHELL=',
    ]
    
    @staticmethod
    def decode_content(content: str) -> str:
        """
        Apply URL decoding and HTML entity decoding to content.
        """
        import urllib.parse
        import html
        
        # URL decode
        try:
            content = urllib.parse.unquote(content)
        except Exception as e:
            logging.debug(f"Error: {e}")
        
        # HTML entity decode
        try:
            content = html.unescape(content)
        except Exception as e:
            logging.debug(f"Error: {e}")
        
        return content
    
    @staticmethod
    def match_etc_passwd(content: str) -> bool:
        """
        Match /etc/passwd content requiring >= 2 signature matches.
        Handles multi-line content, JSON responses, and HTML <pre> sections.
        """
        # Normalize newlines and whitespace
        normalized = content.replace('\r\n', '\n').replace('\r', '\n')
        
        # Count signature matches
        signature_count = 0
        for signature in PathTraversalContentMatcher.ETC_PASSWD_SIGNATURES:
            if re.search(signature, normalized, re.IGNORECASE):
                signature_count += 1
                if signature_count >= 2:
                    return True
        
        return False
    
    @staticmethod
    def match_linux_id(content: str) -> bool:
        """
        Match Linux 'id' command output.
        """
        for pattern in PathTraversalContentMatcher.LINUX_ID_PATTERNS:
            if re.search(pattern, content, re.IGNORECASE):
                return True
        return False
    
    @staticmethod
    def match_win_ini(content: str) -> bool:
        """
        Match Windows win.ini content.
        """
        for pattern in PathTraversalContentMatcher.WIN_INI_PATTERNS:
            if re.search(pattern, content, re.IGNORECASE):
                return True
        return False
    
    @staticmethod
    def match_proc_environ(content: str) -> bool:
        """
        Match /proc/self/environ content (null-separated KEY=VALUE).
        """
        for pattern in PathTraversalContentMatcher.PROC_ENVIRON_PATTERNS:
            if re.search(pattern, content, re.IGNORECASE):
                return True
        return False
    
    @staticmethod
    def match_any(content: str, baseline_content: str = None) -> tuple:
        """
        Match any path traversal content type.
        Returns (matched: bool, evidence: str, file_type: str)
        """
        # Decode content first
        decoded = PathTraversalContentMatcher.decode_content(content)
        
        # Check each file type
        if PathTraversalContentMatcher.match_etc_passwd(decoded):
            # Verify not in baseline
            if baseline_content:
                baseline_decoded = PathTraversalContentMatcher.decode_content(baseline_content)
                if PathTraversalContentMatcher.match_etc_passwd(baseline_decoded):
                    return False, "", ""
            return True, "Multiple /etc/passwd entries detected", "/etc/passwd"
        
        if PathTraversalContentMatcher.match_linux_id(decoded):
            if baseline_content:
                baseline_decoded = PathTraversalContentMatcher.decode_content(baseline_content)
                if PathTraversalContentMatcher.match_linux_id(baseline_decoded):
                    return False, "", ""
            return True, "Linux 'id' command output detected", "Linux id"
        
        if PathTraversalContentMatcher.match_win_ini(decoded):
            if baseline_content:
                baseline_decoded = PathTraversalContentMatcher.decode_content(baseline_content)
                if PathTraversalContentMatcher.match_win_ini(baseline_decoded):
                    return False, "", ""
            return True, "Windows win.ini content detected", "win.ini"
        
        if PathTraversalContentMatcher.match_proc_environ(decoded):
            if baseline_content:
                baseline_decoded = PathTraversalContentMatcher.decode_content(baseline_content)
                if PathTraversalContentMatcher.match_proc_environ(baseline_decoded):
                    return False, "", ""
            return True, "/proc/self/environ content detected", "/proc/self/environ"
        
        return False, "", ""

    def matches(self, content: str) -> bool:
        """
        Check if content matches any path traversal pattern.
        Returns boolean for backward compatibility with tests.
        """
        matched, _, _ = self.match_any(content)
        return matched

    def match(self, content: str) -> dict:
        """
        Check if content matches any path traversal pattern.
        Returns dict with 'is_vulnerable' key for test compatibility.
        """
        matched, evidence, file_type = self.match_any(content)
        return {
            'is_vulnerable': matched,
            'evidence': evidence,
            'file_type': file_type
        }

