# OS detection function for command injection payload selection (Issue R17 fix)
def detect_target_os(headers: Dict[str, str]) -> str:
    """
    Detect target OS from response headers for command injection payload selection.
    
    Uses Server header and application fingerprinting to determine if target is Windows or Linux.
    Defaults to 'Linux' if detection fails (safer default for command injection testing).
    
    Args:
        headers: Response headers dictionary
        
    Returns:
        'Windows' or 'Linux'
    """
    if not headers:
        return 'Linux'
    
    server_header = headers.get('Server', '').lower()
    x_powered_by = headers.get('X-Powered-By', '').lower()
    
    # Windows signatures
    windows_signatures = ['iis', 'microsoft', 'win32', 'asp.net', 'windows']
    for sig in windows_signatures:
        if sig in server_header or sig in x_powered_by:
            return 'Windows'
    
    # Linux signatures
    linux_signatures = ['apache', 'nginx', 'unix', 'linux', 'freebsd', 'openbsd']
    for sig in linux_signatures:
        if sig in server_header or sig in x_powered_by:
            return 'Linux'
    
    # Default to Linux if no clear signature
    return 'Linux'

# Context-aware filtering for command injection detection
def is_in_documentation_context(html: str, match_start: int) -> bool:
    """
    Check if a match is within documentation or code block context that should be excluded.
    
    This prevents false positives from man pages, documentation, code examples, etc.
    """
    # Check for common documentation/code block wrappers
    documentation_contexts = [
        '<pre class="docs">',
        '<pre class="documentation">',
        '<pre class="man">',
        '<div class="documentation">',
        '<div class="docs">',
        '<code class="language-',
        '<code class="hljs">',
        '<pre><code>',
        '```',
        '<pre class="',
    ]
    
    # Get a window around the match to check for context
    window_size = 500
    start = max(0, match_start - window_size)
    end = min(len(html), match_start + window_size)
    context_window = html[start:end]
    
    # Check if match is within any documentation context
    for context in documentation_contexts:
        if context in context_window:
            return True
    
    return False

_OBF_CACHE = OrderedDict()

def _get_waf_specific_variants(payload, waf_type):
    """
    Generate WAF-specific evasion variants based on detected WAF type.

    Research shows different WAFs have different signatures:
    - URL Double Encoding: 72% success rate
    - Case Variation: 45% success rate
    - HTML Entity Encoding: 68% success rate
    - Unicode Normalization: 61% success rate
    - Chunked Transfer Encoding: 83% success rate

    This function selects the most effective techniques for each WAF type.

    Args:
        payload: Original payload to obfuscate
        waf_type: Detected WAF type (generic, cloudflare, aws-waf, sucuri)

    Returns:
        List of WAF-specific payload variants
    """
    variants = []

    # WAF-specific technique selection based on research data
    if waf_type == 'cloudflare':
        # Cloudflare: Chunked Transfer Encoding (83%) + Unicode Normalization (61%)
        # Cloudflare is strong against URL encoding, but weaker against Unicode tricks
        if ' ' in payload:
            variants.append(payload.replace(' ', '\u0000'))  # Unicode null byte
        if 'SELECT' in payload.upper():
            variants.append(payload.replace('SELECT', '/*!00000SELECT*/'))
        if 'script' in payload.lower():
            variants.append(payload.replace('script', 'scr<!-- -->ipt'))
        # Unicode normalization variants
        variants.append(''.join(f'\\u{ord(c):04x}' for c in payload))

    elif waf_type == 'aws-waf':
        # AWS WAF: URL Double Encoding (72%) + Case Variation (45%)
        # AWS WAF has good detection of simple encoding but struggles with double encoding
        variants.append(quote(quote(payload, safe=''), safe=''))  # Double URL encoding
        if ' ' in payload:
            variants.append(payload.replace(' ', '%u0020'))  # Unicode space
        if '=' in payload:
            variants.append(payload.replace('=', '%u003d'))  # Unicode equals
        # Case variation
        if 'UNION' in payload.upper():
            variants.append(payload.replace('UNION', 'un%u0069on'))
            variants.append(payload.replace('UNION', 'UN%u0049ON'))

    elif waf_type == 'sucuri':
        # Sucuri: HTML Entity Encoding (68%) + URL Double Encoding (72%)
        variants.append(''.join(f'&#{ord(c)};' for c in payload))  # HTML entity encoding
        variants.append(quote(quote(payload, safe=''), safe=''))  # Double URL encoding
        if ' ' in payload:
            variants.append(payload.replace(' ', '%0a'))  # Newline encoding

    else:  # generic
        # Generic: Use balanced approach with highest overall success rates
        # Chunked Transfer Encoding (83%) + URL Double Encoding (72%)
        variants.append(quote(quote(payload, safe=''), safe=''))  # Double URL encoding
        if ' ' in payload:
            variants.append(payload.replace(' ', '\u0000'))  # Unicode null byte
            variants.append(payload.replace(' ', '%0a'))  # Newline encoding
        # HTML entity encoding as fallback
        variants.append(''.join(f'&#{ord(c)};' for c in payload))

    return variants

def obfuscate(payload, context="param", waf_type="generic"):
    """
    Context-aware payload obfuscation for different injection contexts.

    Contexts:
    - param: URL parameter injection (default)
    - json: JSON body injection
    - html: HTML injection (innerHTML, etc.)
    - js: JavaScript code injection
    - url: URL fragment/path injection
    - css: CSS injection
    - sql: SQL injection context

    Args:
        payload: Original payload to obfuscate
        context: Injection context (param, json, html, js, url, css, sql)
        waf_type: Detected WAF type for evasion technique selection (generic, cloudflare, aws-waf, sucuri)

    Returns:
        tuple: (variants_list, variant_to_original_map)
        - variants_list: List of obfuscated payload variants
        - variant_to_original_map: Dict mapping each variant back to the original payload
    """
    # Create cache key using JSON serialization to handle unhashable types (dict/list)
    key = f"{context}:{waf_type}:{json.dumps(payload, sort_keys=True, default=str)}"
    if key in _OBF_CACHE:
        cached_result = _OBF_CACHE[key]
        # Handle backward compatibility: if cached result is a list (old format), convert to new format
        if isinstance(cached_result, list):
            return cached_result, {variant: payload for variant in cached_result}
        return cached_result
    
    def generate_variants():
        yield payload

        # WAF-specific evasion technique selection (Issue U8 fix)
        # Select techniques with highest success rate for detected WAF
        waf_specific_variants = _get_waf_specific_variants(payload, waf_type)
        for variant in waf_specific_variants:
            yield variant

        # Context-specific escaping
        if context == "json":
            # JSON-in-HTML context: Handle JSON encoding and HTML entity encoding
            yield json_escape(payload)
            yield json_unicode_escape(payload)
            yield json_html_escape(payload)
            # JSON property name obfuscation
            if "=" in payload or ":" in payload:
                obfuscated = json_property_obfuscation(payload)
                if obfuscated != payload:
                    yield obfuscated
                
        elif context == "html":
            # HTML injection context: Handle entity encoding and script tags
            yield html_entity_encode(payload)
            yield html_hex_encode(payload)
            yield html_decimal_encode(payload)
            # Script tag obfuscation
            if "<script" in payload.lower() or "alert(" in payload.lower():
                yield script_tag_obfuscation(payload)
                
        elif context == "js":
            # JavaScript injection context: Handle string escaping and code obfuscation
            yield js_string_escape(payload)
            yield js_unicode_escape(payload)
            yield js_backtick_escape(payload)
            # JavaScript code obfuscation
            if "alert(" in payload.lower() or "document." in payload.lower():
                yield js_code_obfuscation(payload)
                
        elif context == "url":
            # URL fragment/path injection: Handle URL encoding and JavaScript protocols
            yield url_encode(payload)
            yield url_double_encode(payload)
            url_obf = url_fragment_obfuscation(payload)
            if url_obf != payload:
                yield url_obf
            # JavaScript protocol obfuscation
            if "javascript:" in payload.lower():
                js_proto_obf = javascript_protocol_obfuscation(payload)
                if js_proto_obf != payload:
                    yield js_proto_obf
                
        elif context == "css":
            # CSS injection context: Handle CSS encoding and expression obfuscation
            yield css_escape(payload)
            yield css_hex_escape(payload)
            css_expr_obf = css_expression_obfuscation(payload)
            if css_expr_obf != payload:
                yield css_expr_obf
            
        elif context == "sql":
            # SQL injection context: Use legacy methods
            # ContextAwareSemanticMutator integration happens in InjectionEngine
            yield sql_comment_obfuscation(payload)
            yield sql_whitespace_obfuscation(payload)
            sql_kw_obf = sql_keyword_obfuscation(payload)
            if sql_kw_obf != payload:
                yield sql_kw_obf
        
        # Default param context and general obfuscations
        yield quote(payload, safe='')
        yield quote(quote(payload, safe=''), safe='')
        
        def randomize_case(text):
            return ''.join(c.upper() if random.random() > 0.5 else c.lower() for c in text)
        
        if "SELECT" in payload.upper() or "ALERT" in payload.upper() or "UNION" in payload.upper():
            yield randomize_case(payload)
            yield payload.upper()
            yield payload.lower()
            
        if " " in payload:
            yield payload.replace(" ", "\u0000")  # Semantic null byte instead of /**/
            
        def to_fullwidth(text):
            result = []
            for c in text:
                code = ord(c)
                if 33 <= code <= 126:
                    result.append(chr(code + 0xFEE0))
                else:
                    result.append(c)
            return ''.join(result)
            
        yield to_fullwidth(payload)
        
        keywords = ["SELECT", "UNION", "FROM", "WHERE", "AND", "OR", "INSERT", "UPDATE", "DELETE", "DROP", "alert", "script"]
        for keyword in keywords:
            if keyword in payload.upper():
                yield payload.replace(keyword, keyword[0] + "\u200B" + keyword[1:])  # Zero-width space instead of %09
                yield payload.replace(keyword, keyword[0] + "%0a" + keyword[1:])
                break
        
        def json_unicode_escape(text):
            result = []
            for c in text:
                if c == "'":
                    result.append("\\u0027")
                elif c == '"':
                    result.append("\\u0022")
                elif ord(c) < 32 or ord(c) > 126:
                    result.append(f"\\u{ord(c):04x}")
                else:
                    result.append(c)
            return ''.join(result)
        
        html_entity = ''.join(f"&#{ord(c)};" for c in payload)
        yield html_entity
        
        unicode_escaped = ''.join(f"\\u{ord(c):04x}" for c in payload)
        yield unicode_escaped
        
        yield quote(quote(quote(payload, safe=''), safe=''))
        yield payload.replace(" ", " %00")
        
        if " " in payload:
            comment_variant = payload.replace(" ", "\u0000")  # Semantic null byte instead of /**/
            yield quote(comment_variant, safe='')
            yield quote(quote(comment_variant, safe=''), safe='')
            
        if "SELECT" in payload.upper() and " " in payload:
            mixed_case = randomize_case(payload)
            yield mixed_case.replace(" ", "\u0000")  # Semantic null byte instead of /**/
            
        if "SELECT" in payload.upper():
            fullwidth = to_fullwidth(payload)
            for keyword in keywords:
                if keyword in payload.upper():
                    yield fullwidth.replace(keyword.upper(), keyword.upper()[0] + "\u200B" + keyword.upper()[1:])  # Zero-width space instead of %09
                    break
    
    # Generate variants and build variant->original map
    # Filter out unhashable types (lists, dicts) before deduplication
    variants_list = []
    for variant in generate_variants():
        if isinstance(variant, (str, int, float, bool, tuple)):
            variants_list.append(variant)
        else:
            # Skip unhashable variants, log warning
            logging.warning(f"Skipping unhashable variant type: {type(variant)}")
    
    # Deduplicate while preserving order
    seen = set()
    variants = []
    for variant in variants_list:
        if variant not in seen:
            seen.add(variant)
            variants.append(variant)
    
    variant_to_original = {variant: payload for variant in variants}
    
    # Cache both variants and map
    _OBF_CACHE[key] = (variants, variant_to_original)
    if len(_OBF_CACHE) > 1000:
        _OBF_CACHE.popitem(last=False)
    
    return variants, variant_to_original

# Context-specific obfuscation functions
def json_escape(payload):
    """JSON string escaping with proper quote handling."""
    escaped = payload.replace('\\', '\\\\').replace('"', '\\"')
    return f'"{escaped}"'

def json_unicode_escape(payload):
    """Unicode escape for JSON context."""
    result = []
    for c in payload:
        if c == "'":
            result.append("\\u0027")
        elif c == '"':
            result.append("\\u0022")
        elif c == '\\':
            result.append("\\u005C")
        elif ord(c) < 32 or ord(c) > 126:
            result.append(f"\\u{ord(c):04x}")
        else:
            result.append(c)
    return ''.join(result)

def json_html_escape(payload):
    """Combined JSON and HTML entity escaping for JSON-in-HTML context."""
    # First JSON escape, then HTML entity encode
    json_escaped = json_escape(payload)
    html_escaped = json_escaped.replace('"', '&quot;').replace("'", '&#39;')
    return html_escaped

def json_property_obfuscation(payload):
    """Obfuscate JSON property names and structure."""
    if '=' in payload:
        key, value = payload.split('=', 1)
        # Obfuscate key with various techniques
        obfuscated_keys = [
            f'"{key}"',
            f"'{key}'",
            f'\\u{ord(key[0]):04x}{key[1:]}',
            key,
            f' {key} ',
            f'/*comment*/{key}/*comment*/'
        ]
        # Return first variant as string
        return f'{obfuscated_keys[0]}={value}'
    return payload

def html_entity_encode(payload):
    """HTML entity encoding."""
    return ''.join(f'&#{ord(c)};' for c in payload)

def html_hex_encode(payload):
    """HTML hexadecimal entity encoding."""
    return ''.join(f'&#x{ord(c):x};' for c in payload)

def html_decimal_encode(payload):
    """HTML decimal encoding with mixed case."""
    return ''.join(f'&#{ord(c)};' if random.random() > 0.5 else f'&#x{ord(c):x};' for c in payload)

def script_tag_obfuscation(payload):
    """Script tag obfuscation techniques."""
    obfuscated = payload.lower()
    # Replace script tag variations
    obfuscated = obfuscated.replace('<script', '<scr\0ipt')
    obfuscated = obfuscated.replace('<script', '<scr<!-- -->ipt')
    obfuscated = obfuscated.replace('<script', '<script/x')
    # Replace alert variations
    obfuscated = obfuscated.replace('alert(', 'window[\'alert\'](')
    obfuscated = obfuscated.replace('alert(', 'window["alert"](')
    obfuscated = obfuscated.replace('alert(', '\\u0061\\u006c\\u0065\\u0072\\u0074(')
    return obfuscated

def js_string_escape(payload):
    """JavaScript string escaping."""
    escaped = payload.replace('\\', '\\\\').replace("'", "\\'").replace('"', '\\"')
    return f"'{escaped}'"

def js_unicode_escape(payload):
    """JavaScript unicode escaping."""
    return ''.join(f'\\u{ord(c):04x}' for c in payload)

def js_backtick_escape(payload):
    """JavaScript template literal escaping."""
    escaped = payload.replace('`', '\\`').replace('${', '\\${')
    return f'`{escaped}`'

def js_code_obfuscation(payload):
    """JavaScript code obfuscation."""
    obfuscated = payload
    # Replace common JavaScript patterns
    obfuscated = obfuscated.replace('document.', 'window[\'document\'].')
    obfuscated = obfuscated.replace('document.', 'window["document"].')
    obfuscated = obfuscated.replace('window.', 'self[\'window\'].')
    obfuscated = obfuscated.replace('location.', 'window[\'location\'].')
    obfuscated = obfuscated.replace('alert(', 'window[\\\'alert\\\'](')
    # Access property obfuscation
    obfuscated = obfuscated.replace('.cookie', '[\\\'cookie\\\']')
    obfuscated = obfuscated.replace('.location', '[\\\'location\\\']')
    return obfuscated

def url_encode(payload):
    """URL encoding."""
    return quote(payload, safe='')

def url_double_encode(payload):
    """Double URL encoding."""
    return quote(quote(payload, safe=''), safe='')

def url_fragment_obfuscation(payload):
    """URL fragment obfuscation."""
    # Encode for URL fragment context
    encoded = quote(payload, safe='!#$&\'()*+,/:;=?@[]~')
    # Return first variant
    return encoded

def javascript_protocol_obfuscation(payload):
    """JavaScript protocol obfuscation for URL context."""
    obfuscated = payload.lower()
    # JavaScript protocol variations - use first one
    if 'javascript:' in obfuscated:
        return obfuscated.replace('javascript:', 'javascript\\u003a')
    return payload

def css_escape(payload):
    """CSS escaping."""
    escaped = payload.replace('\\', '\\\\').replace('"', '\\"').replace("'", "\\'")
    return f'"{escaped}"'

def css_hex_escape(payload):
    """CSS hexadecimal escaping."""
    return ''.join(f'\\{ord(c):x} ' if ord(c) > 127 else c for c in payload)

def css_expression_obfuscation(payload):
    """CSS expression obfuscation."""
    obfuscated = payload.lower()
    # CSS expression variations
    obfuscated = obfuscated.replace('expression(', 'exp/*comment*/ression(')
    obfuscated = obfuscated.replace('expression(', 'e\\xpression(')
    obfuscated = obfuscated.replace('expression(', 'e\\78 xpression(')
    return obfuscated

