# Global scanner registry with weak references to prevent stale references
# and allow proper garbage collection. Scoped by target for multi-target support.
# Uses UUID instead of id() to prevent issues with GC-reused memory addresses (Issue S13).
_scanner_registry = {}  # (target, instance_uuid, counter) -> weakref to scanner instance
_registry_lock = threading.Lock()
_registry_counter = 0  # Monotonically increasing counter for ordering


def register_scanner_instance(scanner_instance):
    """Register a scanner instance in the global registry."""
    global _registry_counter
    with _registry_lock:
        target = getattr(scanner_instance, 'target', 'unknown')
        instance_uuid = getattr(scanner_instance, '_scanner_instance_uuid', None)
        if instance_uuid is None:
            # Generate UUID if not already set (defensive programming)
            instance_uuid = str(uuid.uuid4())
            scanner_instance._scanner_instance_uuid = instance_uuid
        
        _registry_counter += 1
        counter = _registry_counter
        _scanner_registry[(target, instance_uuid, counter)] = weakref.ref(scanner_instance)
        logging.debug(f"Registered scanner instance {instance_uuid} (counter={counter}) for target {target} in global registry")


def unregister_scanner_instance(scanner_instance):
    """Unregister a scanner instance from the global registry."""
    with _registry_lock:
        target = getattr(scanner_instance, 'target', 'unknown')
        instance_uuid = getattr(scanner_instance, '_scanner_instance_uuid', None)
        if instance_uuid is None:
            logging.warning("Attempted to unregister scanner instance without UUID")
            return
        
        # Find and remove all entries matching the instance_uuid
        keys_to_remove = [key for key in _scanner_registry.keys() if key[1] == instance_uuid]
        for key in keys_to_remove:
            del _scanner_registry[key]
            logging.debug(f"Unregistered scanner instance {instance_uuid} for target {target} from global registry")


def get_active_scanner_instance(target=None):
    """Get the active scanner instance from the registry.

    Args:
        target: Optional target URL to filter by. If None, returns the most recently registered instance.

    Returns the most recently registered living scanner instance for the target,
    or None if no active instances exist.
    """
    with _registry_lock:
        # Clean up dead references first
        dead_keys = [key for key, ref in _scanner_registry.items() if ref() is None]
        for key in dead_keys:
            del _scanner_registry[key]

        if not _scanner_registry:
            return None

        # If target specified, return the most recent instance for that target
        if target:
            target_instances = [(key, ref) for key, ref in _scanner_registry.items() if key[0] == target]
            if target_instances:
                # Return the most recently registered instance for this target (highest counter)
                target_instances.sort(key=lambda x: x[0][2])  # Sort by counter
                key, ref = target_instances[-1]
                return ref()
            return None

        # Return the most recently registered living instance overall (highest counter)
        target_instances = list(_scanner_registry.items())
        target_instances.sort(key=lambda x: x[0][2])  # Sort by counter
        key, ref = target_instances[-1]
        return ref()


# Legacy thread-local reference holder for backward compatibility (deprecated)
_oob_scanner_local = threading.local()

# Event-based notification system for OOB callbacks
_oob_callback_events = {}  # marker -> asyncio.Event
_oob_callback_lock = asyncio.Lock()

def get_oob_results_lists():
    """Get the current OOB results lists from the scanner instance using global registry.
    
    Uses a weak reference registry to prevent stale references and allow proper
    garbage collection. Raises an exception if no active scanner is registered,
    preventing cross-scan contamination from global fallback lists.
    
    Raises:
        RuntimeError: If no scanner instance is registered. The scanner must be
                        registered before OOB functionality is used.
    """
    scanner_instance = get_active_scanner_instance()
    if scanner_instance:
        return {
            'oob_results': scanner_instance.oob_results,
            'smtp_oob_results': scanner_instance.smtp_oob_results,
            'dns_oob_results': scanner_instance.dns_oob_results,
            'https_oob_results': scanner_instance.https_oob_results,
            'icmp_oob_results': scanner_instance.icmp_oob_results,
            'oob_unified_lock': scanner_instance.oob_unified_lock,
            'oob_unified_lock_threading': scanner_instance.oob_unified_lock_threading,
            'oob_results_lock': scanner_instance.oob_results_lock,
            'smtp_oob_lock': scanner_instance.smtp_oob_lock,
            'dns_oob_lock': scanner_instance.dns_oob_lock,
            'https_oob_lock': scanner_instance.https_oob_lock,
            'icmp_oob_lock': scanner_instance.icmp_oob_lock
        }
    
    # No scanner registered - raise exception instead of using global fallbacks
    # This prevents cross-scan contamination from shared global state
    raise RuntimeError(
        "No scanner instance registered. OOB functionality requires an active scanner. "
        "Ensure the scanner is properly initialized and registered before using OOB features."
    )

pending_oob_markers = {}  # marker -> timestamp when registered
pending_oob_lock = threading.Lock()
oob_marker_history = {}  # marker -> timestamp when registered (for expired markers)
oob_marker_history_lock = threading.Lock()
OOB_MARKER_HISTORY_TTL = 300  # Keep markers in history for 5 minutes after expiry

class PortAllocator:
    _used_ports = set()
    _lock = threading.Lock()
    @classmethod
    def get_available_port(cls, preferred_port=None):
        with cls._lock:
            if preferred_port and preferred_port not in cls._used_ports:
                cls._used_ports.add(preferred_port)
                return preferred_port
            import socket
            for _ in range(100):
                port = random.randint(49152, 65535)
                if port not in cls._used_ports:
                    try:
                        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                            s.bind(('0.0.0.0', port))
                            cls._used_ports.add(port)
                            return port
                    except OSError:
                        continue
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.bind(('0.0.0.0', 0))
                port = s.getsockname()[1]
                cls._used_ports.add(port)
                return port
    @classmethod
    def release_port(cls, port):
        with cls._lock:
            cls._used_ports.discard(port)

def extract_oob_marker_from_path(path):
    """
    Extract the most likely OOB marker from a path by scanning for the longest
    hex/alphanumeric token in the entire path and query string.
    
    This fixes the issue where payloads like /OOB_MARKER/abc123 would extract
    'OOB_MARKER' (the literal) instead of 'abc123' (the actual marker).
    
    Args:
        path: The full request path including query string
        
    Returns:
        The longest hex/alphanumeric token found, or None if no suitable token exists
    """
    import re
    
    if not path or path == '/':
        return None
    
    # Parse the path to separate path components from query string
    parsed = urlparse(path)
    path_components = parsed.path.strip('/').split('/')
    query_params = parse_qs(parsed.query)
    
    # Collect all potential markers from path components and query parameters
    candidates = []
    
    # Check path components (prefer longer tokens)
    for component in path_components:
        if component:
            # Look for hex or alphanumeric tokens (6+ chars to be a marker)
            if re.match(r'^[a-fA-F0-9]{6,}$', component) or re.match(r'^[a-zA-Z0-9]{6,}$', component):
                candidates.append(component)
    
    # Check query parameters
    for param_name, param_values in query_params.items():
        for value in param_values:
            if value:
                if re.match(r'^[a-fA-F0-9]{6,}$', value) or re.match(r'^[a-zA-Z0-9]{6,}$', value):
                    candidates.append(value)
    
    # Return the longest candidate (most likely to be the actual marker)
    if candidates:
        return max(candidates, key=len)
    
    # Fallback: if no suitable hex/alphanumeric token, return first path component
    # This maintains backward compatibility for simple cases
    if path_components:
        return path_components[0]
    
    return None

class OOBCallbackHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        # Extract marker from path (scan entire path for longest hex/alphanumeric token)
        marker = extract_oob_marker_from_path(self.path)

        callback_data = {
            'path': self.path,
            'source': self.client_address[0],
            'time': datetime.now().isoformat(),
            'marker': marker
        }

        # Get active scanner instance for per-scanner state
        # Extract target from the path if available for proper scoping
        target = None
        try:
            parsed = urlparse(self.path)
            if parsed.hostname:
                target = f"{parsed.scheme}://{parsed.hostname}:{parsed.port if parsed.port else (443 if parsed.scheme == 'https' else 80)}"
        except Exception as e:
            logging.debug(f"Error: {e}")
        scanner_instance = get_active_scanner_instance(target)

        try:
            oob_lists = get_oob_results_lists()
            # Use threading lock for synchronous HTTP handler context
            oob_unified_lock_threading = oob_lists.get('oob_unified_lock_threading')
            if oob_unified_lock_threading:
                with oob_unified_lock_threading:
                    oob_lists['oob_results'].append(callback_data)
            else:
                # Fallback to async lock (should not happen in normal operation)
                loop = get_loop()
                try:
                    loop.run_until_complete(
                        oob_lists['oob_unified_lock'].acquire()
                    )
                    oob_lists['oob_results'].append(callback_data)
                    oob_lists['oob_unified_lock'].release()
                except Exception as e:
                    logging.error(f"Error: {e}")
                finally:
                    loop.close()
            # No scanner registered - log and ignore callback
            logging.warning(f"Received OOB callback but no scanner instance registered. Ignoring callback from {self.client_address[0]}")
        except Exception as e:
            logging.error(f"Error: {e}")

        # Mark as received if this marker was pending or in history (race condition protection)
        # Also trigger events for all potential markers in the path for flexibility
        if marker:
            # Use scanner instance's pending_oob_markers if available, otherwise fall back to global
            pending_markers_dict = getattr(scanner_instance, 'pending_oob_markers', pending_oob_markers) if scanner_instance else pending_oob_markers
            pending_lock = getattr(scanner_instance, 'pending_oob_lock', pending_oob_lock) if scanner_instance else pending_oob_lock
            history_dict = getattr(scanner_instance, 'oob_marker_history', oob_marker_history) if scanner_instance else oob_marker_history
            history_lock = getattr(scanner_instance, 'oob_marker_history_lock', oob_marker_history_lock) if scanner_instance else oob_marker_history_lock
            async_task_mgr = getattr(scanner_instance, 'async_task_manager', ASYNC_TASK_MANAGER) if scanner_instance else ASYNC_TASK_MANAGER

            with pending_lock:
                if marker in pending_markers_dict:
                    callback_data['pending'] = True
                    del pending_markers_dict[marker]
                else:
                    # Check history buffer for expired markers
                    with history_lock:
                        if marker in history_dict:
                            callback_data['pending'] = True
                            callback_data['late_arrival'] = True
                            del history_dict[marker]

            # Scan path for all potential markers and trigger events for flexibility
            parsed = urlparse(self.path)
            path_components = parsed.path.strip('/').split('/')
            query_params = parse_qs(parsed.query)

            potential_markers = set()
            for component in path_components:
                if component and (re.match(r'^[a-fA-F0-9]{6,}$', component) or re.match(r'^[a-zA-Z0-9]{6,}$', component)):
                    potential_markers.add(component)
            for param_name, param_values in query_params.items():
                for value in param_values:
                    if value and (re.match(r'^[a-fA-F0-9]{6,}$', value) or re.match(r'^[a-zA-Z0-9]{6,}$', value)):
                        potential_markers.add(value)

            # Trigger event-based notification for all potential markers
            for potential_marker in potential_markers:
                try:
                    async_task_mgr.create_task_sync(
                        trigger_oob_callback_event(potential_marker),
                        task_name=f"oob_callback_{potential_marker[:8]}",
                        callback=lambda t: logging.debug(f"OOB callback event triggered for marker {potential_marker[:8]}")
                    )
                except RuntimeError:
                    pass  # No event loop available
        
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"OK")
        
    def do_POST(self):
        import re
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length)

        # Extract marker from path (scan entire path for longest hex/alphanumeric token)
