def start_oob_server(bind="127.0.0.1", preferred_port=None):
    """Start OOB server with error handling for port conflicts using multithreaded server.
    
    Security Note: Binds to 127.0.0.1 by default to prevent external access.
    Use bind='0.0.0.0' only if specifically required and with proper firewall rules.
    """
    try:
        port = PortAllocator.get_available_port(preferred_port)
        # Use ThreadingHTTPServer for concurrent request handling
        server = ThreadingHTTPServer((bind, port), OOBCallbackHandler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        logging.info(f"OOB server started on {bind}:{port} with multithreaded support")
        if bind == "0.0.0.0":
            logging.error("OOB server bound to 0.0.0.0 - accessible from external networks. Ensure proper firewall rules are in place.")
        return server, port
    except OSError as e:
        logging.error(f"Failed to start OOB server on {bind}:{preferred_port or 'any port'}: {e}")
        # Try with a different port if preferred port fails
        if preferred_port:
            try:
                port = PortAllocator.get_available_port(None)
                server = ThreadingHTTPServer((bind, port), OOBCallbackHandler)
                thread = threading.Thread(target=server.serve_forever, daemon=True)
                thread.start()
                logging.error(f"OOB server started on alternative port {port} with multithreaded support")
                return server, port
            except OSError as e2:
                logging.error(f"Failed to start OOB server on alternative port: {e2}")
                raise
        raise

def register_oob_marker(marker, timeout_seconds=30):
    """Register a marker as pending for OOB callback detection"""
    current_time = datetime.now().timestamp()
    with pending_oob_lock:
        pending_oob_markers[marker] = current_time + timeout_seconds
    # Also add to history for late arrival detection (shorter TTL since sweeper handles this)
    with oob_marker_history_lock:
        oob_marker_history[marker] = current_time + timeout_seconds + 15

def unregister_oob_marker(marker):
    """Unregister a marker from pending OOB callback detection"""
    with pending_oob_lock:
        if marker in pending_oob_markers:
            del pending_oob_markers[marker]

async def register_oob_callback_event(marker):
    """Register an asyncio.Event for a marker to enable event-based notification"""
    async with _oob_callback_lock:
        if marker not in _oob_callback_events:
            _oob_callback_events[marker] = asyncio.Event()
        return _oob_callback_events[marker]

async def unregister_oob_callback_event(marker):
    """Unregister an asyncio.Event for a marker"""
    async with _oob_callback_lock:
        if marker in _oob_callback_events:
            del _oob_callback_events[marker]

async def trigger_oob_callback_event(marker):
    """Trigger the event for a specific marker when callback is received"""
    async with _oob_callback_lock:
        if marker in _oob_callback_events:
            _oob_callback_events[marker].set()

async def wait_for_oob_callback_async(marker, timeout_seconds=60, check_interval=1.0):
    """
    Async wait for an OOB callback for a specific marker with event-based notification.
    This solves the issue where network delays cause callbacks to arrive 2-3 seconds later.
    Uses event-based notification instead of polling for better efficiency.
    Falls back to polling if event system is not available.
    Uses a single unified lock to prevent deadlock.
    Extended timeout to catch late-arriving callbacks from history buffer.
    
    Raises:
        RuntimeError: If no scanner instance is registered.
    """
    start_time = time.time()
    end_time = start_time + timeout_seconds
    
    # Register the marker as pending
    register_oob_marker(marker, timeout_seconds)
    
    # Register event for this marker (keep it alive for history TTL to catch late arrivals)
    callback_event = await register_oob_callback_event(marker)
    
    # Get OOB lists and unified lock
    oob_lists = get_oob_results_lists()
    oob_unified_lock = oob_lists['oob_unified_lock']
    oob_results = oob_lists['oob_results']
    dns_oob_results = oob_lists['dns_oob_results']
    smtp_oob_results = oob_lists['smtp_oob_results']
    icmp_oob_results = oob_lists['icmp_oob_results']
    
    try:
        # Use event-based waiting with timeout loop for periodic checks
        # Cap total wait at timeout_seconds + 15 to prevent indefinite waiting
        # Late arrivals are handled by a separate background sweeper
        extended_timeout = timeout_seconds + 15
        check_interval = 1.0  # Check every second for better responsiveness
        
        # Loop with periodic checks instead of one long wait
        while time.time() < end_time + 15:
            try:
                # Wait for the event with a small timeout to allow periodic checks
                await asyncio.wait_for(callback_event.wait(), timeout=check_interval)
                # Event was set, break out of the loop
                break
            except asyncio.TimeoutError:
                # Timeout for this interval, continue the loop
                continue
        
        # Event was triggered or timeout occurred - check for actual results
        async with oob_unified_lock:
            # Check HTTP OOB results (including late arrivals from history buffer)
            for result in oob_results:
                if result.get('marker') == marker:
                    # Return result even if it's a late arrival - the exploit worked
                    return result
            
            # Check DNS OOB results for the marker
            for result in dns_oob_results:
                if marker in result.get('domain', ''):
                    return result
            
            # Check SMTP OOB results for the marker
            for result in smtp_oob_results:
                marker_in_mail_from = marker in result.get('mail_from', '') if result.get('mail_from') else False
                marker_in_rcpt_to = any(marker in rcpt for rcpt in result.get('rcpt_to', [])) if result.get('rcpt_to') else False
                marker_in_headers = any(marker in value for value in result.get('headers', {}).values()) if result.get('headers') else False
                
                if marker_in_mail_from or marker_in_rcpt_to or marker_in_headers:
                    return result
            
            # Check ICMP OOB results for the marker
            for result in icmp_oob_results:
                marker_in_data = marker in result.get('data', '') if result.get('data') else False
                marker_in_source = marker in result.get('source_ip', '') if result.get('source_ip') else False
                
                if marker_in_data or marker_in_source:
                    return result
        
        return None
    except Exception as e:
        if isinstance(e, asyncio.CancelledError):
            raise
        logging.error(f"Error: {e}")
    finally:
        # Always unregister the marker and event, even if an exception occurs
        unregister_oob_marker(marker)
        await unregister_oob_callback_event(marker)

def wait_for_oob_callback(marker, timeout_seconds=30, check_interval=0.5):
    """
    Synchronous wrapper for OOB callback detection.
    This is a blocking call - for async code, use wait_for_oob_callback_async instead.
    Uses a single unified lock to prevent deadlock.
    Extended timeout to catch late-arriving callbacks from history buffer.
    Uses asyncio.run() for proper event loop lifecycle management.
    """
    return run_async_safely(wait_for_oob_callback_async(marker, timeout_seconds, check_interval))

async def start_oob_polling_task(marker, timeout_seconds=60, check_interval=1.0, scanner_instance=None):
    """
    Start a background async task that polls for OOB callbacks non-blocking.
    This spawns a background task that polls oob_results every 1 second for 60 seconds.
    Returns the task object which can be awaited or cancelled.
    """
    # Use scanner instance's async_task_manager if available, otherwise fall back to global
    async_task_mgr = getattr(scanner_instance, 'async_task_manager', ASYNC_TASK_MANAGER) if scanner_instance else ASYNC_TASK_MANAGER
    task = async_task_mgr.create_task_sync(
        wait_for_oob_callback_async(marker, timeout_seconds, check_interval),
        task_name=f"oob_polling_{marker[:8]}",
        callback=lambda t: logging.info(f"OOB polling task for marker {marker[:8]} completed")
    )
    return task

def cleanup_expired_markers(scanner_instance=None):
    """Clean up expired markers from pending tracking and history buffer"""
    # Use scanner instance's state if available, otherwise fall back to global
    pending_markers_dict = getattr(scanner_instance, 'pending_oob_markers', pending_oob_markers) if scanner_instance else pending_oob_markers
    pending_lock = getattr(scanner_instance, 'pending_oob_lock', pending_oob_lock) if scanner_instance else pending_oob_lock
    history_dict = getattr(scanner_instance, 'oob_marker_history', oob_marker_history) if scanner_instance else oob_marker_history
    history_lock = getattr(scanner_instance, 'oob_marker_history_lock', oob_marker_history_lock) if scanner_instance else oob_marker_history_lock

    current_time = datetime.now().timestamp()
    with pending_lock:
        expired_markers = [
            marker for marker, expiry in pending_markers_dict.items()
            if expiry < current_time
        ]
        for marker in expired_markers:
            del pending_markers_dict[marker]

    # Also clean up history buffer
    with history_lock:
        expired_history_markers = [
            marker for marker, expiry in history_dict.items()
            if expiry < current_time
        ]
        for marker in expired_history_markers:
            del oob_marker_history[marker]

async def oob_late_arrival_sweeper():
    """
    Background async task to detect and process late-arriving OOB callbacks.
    
    This sweeper runs continuously and checks for callbacks that arrive after
    the normal timeout period but within the history TTL window (timeout + 15s).
    It processes these late arrivals and logs them appropriately.
    
    This prevents the wait_for_oob_callback_async function from needing to wait
    for the full history TTL, which would cause indefinite blocking when many
    markers are pending.
    """
    global oob_late_arrival_sweeper_running
    oob_late_arrival_sweeper_running = True
    
    logging.info("OOB late arrival sweeper started")
    
    while oob_late_arrival_sweeper_running:
        try:
            await asyncio.sleep(5)  # Check every 5 seconds
            
            current_time = datetime.now().timestamp()
            oob_lists = get_oob_results_lists()
            oob_results = oob_lists['oob_results']
            oob_unified_lock = oob_lists['oob_unified_lock']
            
            # Check for late arrivals in history buffer
            with oob_marker_history_lock:
                expired_markers = [
                    marker for marker, expiry in oob_marker_history.items()
                    if expiry < current_time
                ]
                for marker in expired_markers:
                    del oob_marker_history[marker]
            
            # If no expired markers, continue
            if not expired_markers:
                continue
            
            # Check OOB results for late arrivals matching expired markers
            async with oob_unified_lock:
                for result in oob_results:
                    marker = result.get('marker')
                    if marker and marker in expired_markers:
                        # This is a late arrival - log it
                        result['late_arrival'] = True
                        logging.info(f"Late OOB callback detected for marker {marker[:8]} from {result.get('source')}")
                        
                        # Trigger event notification if any waiters are still listening
                        try:
                            await trigger_oob_callback_event(marker)
                        except Exception as e:
                            logging.debug(f"Failed to trigger event for late arrival {marker[:8]}: {e}")
        
        except Exception as e:
            logging.error(f"OOB late arrival sweeper error: {e}")
            await asyncio.sleep(10)  # Wait longer on error to avoid tight error loops
    
    logging.info("OOB late arrival sweeper stopped")

oob_late_arrival_sweeper_running = False

