    def get_discovered_routes(self):
        """Get all discovered routes from framework instrumentation"""
        try:
            get_routes_script = """
            return {
                discovered_routes: window.__discovered_routes || [],
                route_transitions: window.__route_transitions || [],
                framework_info: window.__framework_info || {}
            };
            """
            
            route_data = self.driver.execute_script(get_routes_script)
            
            # Update internal state
            if route_data.get('discovered_routes'):
                for route in route_data['discovered_routes']:
                    if isinstance(route, dict):
                        route_key = route.get('path') or route.get('source') or str(route)
                        self.discovered_routes.add(route_key)
                        
                        # Also add to discovered URLs with source tracking
                        source = route.get('source', 'framework_instrumentation')
                        path = route.get('path') or route.get('source')
                        if path and isinstance(path, str):
                            with self.lock:
                                self.discovered_urls.append({ 'url': path, 'discovery_source': source })
            
            if route_data.get('route_transitions'):
                self.route_transitions.extend(route_data['route_transitions'])
            
            if route_data.get('framework_info'):
                self.framework_routers.update(route_data['framework_info'])
            
            return route_data
            
        except Exception as e:
            logging.error(f"Failed to get discovered routes: {e}")
            return {
                'discovered_routes': list(self.discovered_routes),
                'route_transitions': self.route_transitions,
                'framework_info': self.framework_routers
            }
    
    def monitor_route_changes(self, duration=30):
        """Passively monitor route changes for specified duration"""
        if not self.driver or not self.passive_route_monitoring:
            logging.error("Route monitoring not enabled")
            return []
        
        logging.info(f"Monitoring route changes for {duration} seconds...")
        start_time = time.time()
        initial_route_count = len(self.discovered_routes)
        
        try:
            while time.time() - start_time < duration:
                # Get current routes
                route_data = self.get_discovered_routes()
                
                # Simulate user interaction to trigger lazy-loaded routes
                if random.random() < 0.3:  # 30% chance to interact
                    self._simulate_random_interaction()
                
                try:
                    loop = asyncio.get_running_loop()
                    loop.run_in_executor(None, time.sleep, 2)
                except RuntimeError:
                    # No running loop, use blocking sleep
                    time.sleep(2)  # Check every 2 seconds
            
            new_routes = len(self.discovered_routes) - initial_route_count
            logging.info(f"Route monitoring complete. Discovered {new_routes} new routes.")
            
            return list(self.discovered_routes)
            
        except Exception as e:
            logging.error(f"Route monitoring error: {e}")
            return list(self.discovered_routes)
    
    async def get_discovered_urls(self):
        """Get all dynamically discovered URLs with their sources"""
        with self.lock:
            return list(self.discovered_urls)
    
    def clear_discovered_urls(self):
        """Clear discovered URLs queue"""
        with self.lock:
            self.discovered_urls.clear()
    
    def _simulate_random_interaction(self):
        """Simulate random user interaction to trigger lazy-loaded routes"""
        try:
            interaction_script = """
            // Find and click random interactive elements
            const interactiveElements = document.querySelectorAll('a, button, [onclick], [role="button"]');
            if (interactiveElements.length > 0) {
                const randomElement = interactiveElements[Math.floor(Math.random() * interactiveElements.length)];
                if (randomElement.offsetParent !== null) { // Element is visible
                    randomElement.click();
                    return { clicked: true, element: randomElement.tagName };
                }
            }
            return { clicked: false };
            """
            
            result = self.driver.execute_script(interaction_script)
            if result.get('clicked'):
                logging.error(f"Simulated click on {result.get('element')}")
                
        except Exception as e:
            logging.error(f"Random interaction simulation failed: {e}")
    
    def monitor_websocket_traffic(self, timeout=DEFAULT_REQUEST_TIMEOUT):
        """Monitor WebSocket traffic for a specified timeout period"""
        if not self.driver or not self.websocket_monitoring_enabled:
            return []
        
        websocket_data = []
        start_time = time.time()
        
        try:
            while time.time() - start_time < timeout:
                # Get network logs using CDP
                try:
                    logs = self.driver.get_log('performance')
                    
                    for entry in logs:
                        message = safe_json_loads(entry['message'], max_depth=100)
                        message_data = message.get('message', {})
                        
                        # Check for WebSocket messages
                        if message_data.get('method') == 'Network.webSocketFrameReceived':
                            frame_data = message_data.get('params', {})
                            payload_data = frame_data.get('response', {}).get('payloadData', '')
                            
                            # FIX: Detect fragmented frames and track them
                            websocket_data.append({ 'type': 'received', 'timestamp': frame_data.get('timestamp'), 'data': payload_data, 'is_fragmented': len(payload_data) > 1024, 'fragment_size': len(payload_data) })
                        elif message_data.get('method') == 'Network.webSocketFrameSent':
                            frame_data = message_data.get('params', {})
                            payload_data = frame_data.get('response', {}).get('payloadData', '')
                            
                            # FIX: Detect fragmented frames and track them
                            websocket_data.append({
                                'type': 'sent',
                                'timestamp': frame_data.get('timestamp'),
                                'data': payload_data,
                                'is_fragmented': len(payload_data) > 1024,  # Track large payloads
                                'fragment_size': len(payload_data)
                            })
                
                except Exception as log_error:
                    logging.error(f"Error getting performance logs: {log_error}")
                
                # Also capture WebSocket messages from JavaScript interception
                try:
                    js_messages = self.driver.execute_script("""
                        if (window.__ultradast_websocket_messages) {
                            const messages = window.__ultradast_websocket_messages;
                            window.__ultradast_websocket_messages = [];
                            return messages;
                        }
                        return [];
                    """)
                    
                    for msg in js_messages:
                        payload_data = msg.get('data', '')
                        websocket_data.append({
                            'type': msg.get('type', 'unknown'),
                            'timestamp': msg.get('timestamp', time.time()),
                            'data': payload_data,
                            'url': msg.get('url', ''),
                            'is_fragmented': len(payload_data) > 1024,  # Track large payloads
                            'fragment_size': len(payload_data)
                        })
                
                except Exception as js_error:
                    logging.error(f"Error getting JavaScript WebSocket messages: {js_error}")
                
                try:
                    loop = asyncio.get_running_loop()
                    loop.run_in_executor(None, time.sleep, 0.5)
                except RuntimeError:
                    # No running loop, use blocking sleep
                    time.sleep(0.5)
            
            # Store captured WebSocket messages
            with self.lock:
                self.websocket_messages.extend(websocket_data)
            
            # FIX: Log fragmentation statistics
            fragmented_count = sum(1 for msg in websocket_data if msg.get('is_fragmented'))
            if fragmented_count > 0:
                logging.info(f"Captured {len(websocket_data)} WebSocket messages ({fragmented_count} fragmented)")
            else:
                logging.info(f"Captured {len(websocket_data)} WebSocket messages")
            
            return websocket_data
            
        except Exception as e:
            logging.error(f"WebSocket monitoring error: {e}")
            return []
    
    def get_websocket_messages(self):
        """Get captured WebSocket messages"""
        with self.lock:
            # FIX: Return messages with fragmentation statistics
            messages = list(self.websocket_messages)
            fragmented_count = sum(1 for msg in messages if msg.get('is_fragmented'))
            if fragmented_count > 0:
                logging.info(f"Retrieved {len(messages)} WebSocket messages ({fragmented_count} fragmented)")
            return messages
    
    def clear_websocket_messages(self):
        """Clear captured WebSocket messages"""
        with self.lock:
            self.websocket_messages.clear()
    
    def set_local_storage_item(self, key, value):
        """Set a localStorage item"""
        if not self.driver:
            return False
        
        try:
            script = f"""
            window.localStorage.setItem('{key}', '{value}');
            return true;
            """
            result = self.driver.execute_script(script)
            logging.error(f"Set localStorage[{key}] = {value}")
            return result
        except Exception as e:
            logging.error(f"Error setting localStorage item: {e}")
            return False
    
    def get_local_storage_item(self, key):
        """Get a localStorage item"""
        if not self.driver:
            return None
        
        try:
            script = f"""
            return window.localStorage.getItem('{key}');
            """
            result = self.driver.execute_script(script)
            logging.error(f"Got localStorage[{key}] = {result}")
            return result
        except Exception as e:
            logging.error(f"Error getting localStorage item: {e}")
            return None
    
