# SEMANTIC BUSINESS LOGIC INFERENCER - Issue T2 Fix
# ============================================================================

class BusinessLogicInferencer:
    """
    Semantic Business Logic Inferencer for detecting business logic vulnerabilities.

    This class addresses the fundamental limitation of DAST tools: they cannot understand
    application semantics. By learning business rules from observed traffic, it can detect
    violations like "transfer €1 to yourself" or coupon stacking that would be invisible
    to black-box scanners.

    Architecture:
    - observe(): Records request/response pairs during crawling
    - infer_rules(): Extracts business constraints from observed patterns
    - test_rules(): Validates inferred rules by sending violating requests
    - learn_from_database(): Persists and retrieves learned rules across scans

    Supported Rule Types:
    - Price/amount validation (tampering detection)
    - Quantity validation (negative/zero rejection)
    - Coupon stacking prevention
    - User-id validation (session matching)
    - Rate limiting detection
    - Idempotency validation
    - Sequential flow enforcement
    """

    def __init__(self, session_manager, config):
        """
        Initialize the Business Logic Inferencer.

        Args:
            session_manager: SessionManager instance for making requests
            config: Scanner configuration dictionary
        """
        self.session_manager = session_manager
        self.config = config
        self.target = config.get('target', '')

        # Observation data structures
        self.observed_flows = []  # List of (request, response) tuples
        self.max_observed_flows = config.get('business_logic_max_observations', 10000)

        # Inferred business rules
        self.business_rules = []  # List of BusinessRule objects
        self.rule_confidence = {}  # rule_id -> confidence score (0-100)

        # Learned state transitions (augments FSM)
        self.state_machine = {}  # learned state -> transitions

        # Field tracking for rule inference
        self.field_observations = defaultdict(lambda: {
            'values': [],
            'patterns': set(),
            'occurrences': 0,
            'endpoints': set(),
            'min_value': None,
            'max_value': None,
            'data_type': None
        })

        # Known-good values for validation
        self.known_good_values = {}  # field_name -> set of valid values

        # Database for persistent rule storage
        self.db_path = config.get('business_logic_db_path', 'business_logic_rules.db')
        self._init_database()

        # Configuration
        self.min_confidence_threshold = config.get('business_logic_min_confidence', 70)
        self.enable_persistence = config.get('business_logic_persistence', True)
        self.learning_enabled = config.get('business_logic_learning', True)

        logging.info("BusinessLogicInferencer initialized")

    def _init_database(self):
        """Initialize SQLite database for persistent rule storage."""
        import sqlite3
        with sqlite3.connect(self.db_path, check_same_thread=False) as conn:
            cursor = conn.cursor()
            # Table for storing learned business rules
            cursor.execute('''CREATE TABLE IF NOT EXISTS business_rules
                    (rule_id TEXT PRIMARY KEY,
                     target TEXT,
                     rule_type TEXT,
                     field_name TEXT,
                     rule_constraint TEXT,
                     conf REAL,
                     created_at TEXT,
                     last_seen TEXT,
                     violations_count INTEGER DEFAULT 0)''')
            # Table for storing field observations
            cursor.execute('''CREATE TABLE IF NOT EXISTS field_observations
                    (target TEXT,
                     field_name TEXT,
                     value TEXT,
                     endpoint TEXT,
                     observed_at TEXT,
                     PRIMARY KEY (target, field_name, value, endpoint))''')
            # Table for storing state transitions
            cursor.execute('''CREATE TABLE IF NOT EXISTS state_transitions
                    (target TEXT,
                     from_state TEXT,
                     to_state TEXT,
                     transition_action TEXT,
                     confidence REAL,
                     PRIMARY KEY (target, from_state, to_state, transition_action))''')
            conn.commit()
        logging.info(f"BusinessLogicInferencer database initialized: {self.db_path}")

    def observe(self, request, response):
        """
        Record a request/response pair for learning business rules.

        Extracts and analyzes:
        - Form fields (price, quantity, coupon, user_id)
        - Hidden inputs
        - JSON body fields
        - Query parameters
        - Response patterns (error messages, validation failures)

        Args:
            request: Request object or dict with url, method, headers, body
            response: Response object or NormalizedResponse
        """
        if not self.learning_enabled:
            return

        try:
            # Normalize request
            if isinstance(request, dict):
                req_data = request
            else:
                req_data = {
                    'url': getattr(request, 'url', ''),
                    'method': getattr(request, 'method', 'GET'),
                    'headers': dict(getattr(request, 'headers', {})),
                    'body': getattr(request, 'body', '')
                }

            # Normalize response
            if isinstance(response, NormalizedResponse):
                resp_data = {
                    'status': response.status,
                    'headers': response.headers,
                    'body': response.text,
                    'url': response.url
                }
            elif isinstance(response, dict):
                resp_data = response
            else:
                resp_data = {
                    'status': getattr(response, 'status', 0),
                    'headers': dict(getattr(response, 'headers', {})),
                    'body': getattr(response, 'text', ''),
                    'url': getattr(response, 'url', '')
                }

            # Store observation
            self.observed_flows.append((req_data, resp_data))

            # Limit memory usage
            if len(self.observed_flows) > self.max_observed_flows:
                self.observed_flows = self.observed_flows[-self.max_observed_flows:]

            # Extract fields from request
            self._extract_fields_from_request(req_data, resp_data)

            # Extract patterns from response
            self._extract_patterns_from_response(resp_data)

        except Exception as e:
            logging.error(f"Error in BusinessLogicInferencer.observe: {e}")

    def _extract_fields_from_request(self, request, response):
        """Extract and track business-relevant fields from request."""
        import re
        from urllib.parse import parse_qs

        url = request.get('url', '')
        method = request.get('method', 'GET')
        body = request.get('body', '')
        headers = request.get('headers', {})

        # Extract fields from query parameters
        parsed_url = urlparse(url)
        query_params = parse_qs(parsed_url.query)
        for param_name, param_values in query_params.items():
            for value in param_values:
                self._track_field(param_name, value, url, 'query')

        # Extract fields from form data (POST)
        if method in ['POST', 'PUT', 'PATCH'] and body:
            # Try JSON parsing
            try:
                import json
                json_data = json.loads(body)
                if isinstance(json_data, dict):
                    for field_name, field_value in json_data.items():
                        if isinstance(field_value, (str, int, float)):
                            self._track_field(field_name, str(field_value), url, 'json')
            except (json.JSONDecodeError, ValueError):
                # Try form-urlencoded parsing
                form_data = parse_qs(body)
                for field_name, field_values in form_data.items():
                    for value in field_values:
                        self._track_field(field_name, value, url, 'form')

        # Extract fields from headers
        for header_name, header_value in headers.items():
            if header_name.lower() in ['x-user-id', 'x-customer-id', 'x-account-id']:
                self._track_field(header_name, header_value, url, 'header')

    def _track_field(self, field_name, field_value, url, source):
        """Track field observations for rule inference."""
        field_lower = field_name.lower()
        obs = self.field_observations[field_name]

        # Track value
        obs['values'].append(field_value)
        obs['occurrences'] += 1
        obs['endpoints'].add(url)

        # Track data type
        try:
            float_val = float(field_value)
            if obs['min_value'] is None or float_val < obs['min_value']:
                obs['min_value'] = float_val
            if obs['max_value'] is None or float_val > obs['max_value']:
                obs['max_value'] = float_val
            obs['data_type'] = 'numeric'
        except (ValueError, TypeError):
            obs['data_type'] = 'string'

        # Track patterns (e.g., email format, UUID)
        if '@' in field_value and '.' in field_value:
            obs['patterns'].add('email')
        elif re.match(r'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$', field_value.lower()):
            obs['patterns'].add('uuid')
        elif re.match(r'^\d+$', field_value):
            obs['patterns'].add('integer')

        # Persist to database if enabled
        if self.enable_persistence:
            self._persist_field_observation(field_name, field_value, url, source)

    def _persist_field_observation(self, field_name, field_value, url, source):
        """Persist field observation to database."""
        import sqlite3
        from datetime import datetime

        try:
            with sqlite3.connect(self.db_path, check_same_thread=False) as conn:
                cursor = conn.cursor()
                cursor.execute('''INSERT OR REPLACE INTO field_observations
                        (target, field_name, value, endpoint, observed_at)
                        VALUES (?, ?, ?, ?, ?)''',
                        (self.target, field_name, field_value, url, datetime.now().isoformat()))
                conn.commit()
        except Exception as e:
            logging.error(f"Error persisting field observation: {e}")

    def _extract_patterns_from_response(self, response):
        """Extract validation patterns from response."""
        status = response.get('status', 0)
        body = response.get('body', '')

        # Track error patterns
        if status >= 400:
            # Look for validation error messages
            if 'invalid' in body.lower() or 'validation' in body.lower():
                self._track_validation_pattern('validation_error')
            if 'duplicate' in body.lower():
                self._track_validation_pattern('duplicate_error')
            if 'unauthorized' in body.lower() or 'forbidden' in body.lower():
                self._track_validation_pattern('authorization_error')

    def _track_validation_pattern(self, pattern_name):
        """Track validation error patterns."""
        if pattern_name not in self.field_observations:
            self.field_observations[pattern_name] = {
                'values': [],
                'patterns': set(),
                'occurrences': 0,
                'endpoints': set(),
                'min_value': None,
                'max_value': None,
                'data_type': 'pattern'
            }
        self.field_observations[pattern_name]['occurrences'] += 1

    def infer_rules(self):
        """
        Infer business rules from observed traffic.

        Rules inferred:
        1. Price/amount validation: If a field named "price" or "amount" appears,
           the server should validate it against a known-good value.
        2. Quantity validation: If a field named "quantity" appears, the server should
           reject negative or zero values.
        3. Coupon stacking: If a field named "coupon" appears, the server should
           reject stacking of multiple coupons.
        4. User-id validation: If a field named "user_id" appears, the server should
           reject requests where the id does not match the session.
        5. Rate limiting: Detect endpoints that rate limit based on response patterns.
        6. Idempotency: Detect endpoints that should be idempotent but aren't.

        Returns:
            List of inferred BusinessRule objects
        """
        if not self.learning_enabled:
            return []

        inferred_rules = []

        try:
            # Rule 1: Price/amount validation
            price_rule = self._infer_price_validation_rule()
            if price_rule:
                inferred_rules.append(price_rule)

            # Rule 2: Quantity validation
            quantity_rule = self._infer_quantity_validation_rule()
            if quantity_rule:
                inferred_rules.append(quantity_rule)

            # Rule 3: Coupon stacking
            coupon_rule = self._infer_coupon_stacking_rule()
            if coupon_rule:
                inferred_rules.append(coupon_rule)

            # Rule 4: User-id validation
            user_id_rule = self._infer_user_id_validation_rule()
            if user_id_rule:
                inferred_rules.append(user_id_rule)

            # Rule 5: Rate limiting
            rate_limit_rule = self._infer_rate_limiting_rule()
            if rate_limit_rule:
                inferred_rules.append(rate_limit_rule)

            # Rule 6: Idempotency
            idempotency_rule = self._infer_idempotency_rule()
            if idempotency_rule:
                inferred_rules.append(idempotency_rule)

            # Store inferred rules
            self.business_rules = inferred_rules

            # Persist to database
            if self.enable_persistence:
                self._persist_rules(inferred_rules)

            logging.info(f"Inferred {len(inferred_rules)} business rules")

        except Exception as e:
            logging.error(f"Error in BusinessLogicInferencer.infer_rules: {e}")

        return inferred_rules

    def _infer_price_validation_rule(self):
        """Infer price/amount validation rule."""
        price_fields = ['price', 'amount', 'total', 'cost', 'fee', 'subtotal']
        for field_name, obs in self.field_observations.items():
            if any(pf in field_name.lower() for pf in price_fields):
                if obs['data_type'] == 'numeric' and obs['min_value'] is not None:
                    # Infer that values should be positive and within reasonable range
                    rule = {
                        'rule_id': f"price_validation_{field_name}",
                        'rule_type': 'price_validation',
                        'field_name': field_name,
                        'constraint': f"value >= 0 and value <= {obs['max_value'] * 2}",
                        'confidence': min(100, obs['occurrences'] * 10),
                        'description': f"Field '{field_name}' should be non-negative and within observed range"
                    }
                    self.rule_confidence[rule['rule_id']] = rule['confidence']
                    return rule
        return None

    def _infer_quantity_validation_rule(self):
        """Infer quantity validation rule."""
        quantity_fields = ['quantity', 'qty', 'count', 'num', 'number']
        for field_name, obs in self.field_observations.items():
            if any(qf in field_name.lower() for qf in quantity_fields):
                if obs['data_type'] == 'numeric':
                    # Infer that values should be positive integers
                    rule = {
                        'rule_id': f"quantity_validation_{field_name}",
                        'rule_type': 'quantity_validation',
                        'field_name': field_name,
                        'constraint': "value > 0 and value.is_integer()",
                        'confidence': min(100, obs['occurrences'] * 10),
                        'description': f"Field '{field_name}' should be a positive integer"
                    }
                    self.rule_confidence[rule['rule_id']] = rule['confidence']
                    return rule
        return None

    def _infer_coupon_stacking_rule(self):
        """Infer coupon stacking prevention rule."""
        coupon_fields = ['coupon', 'discount', 'promo', 'voucher']
        for field_name, obs in self.field_observations.items():
            if any(cf in field_name.lower() for cf in coupon_fields):
                if obs['occurrences'] > 1:
                    # Infer that multiple coupons should not be accepted
                    rule = {
                        'rule_id': f"coupon_stacking_{field_name}",
                        'rule_type': 'coupon_stacking',
                        'field_name': field_name,
                        'constraint': "count(active_coupons) <= 1",
                        'confidence': min(100, obs['occurrences'] * 5),
                        'description': f"Multiple '{field_name}' values should not be accepted in a single transaction"
                    }
                    self.rule_confidence[rule['rule_id']] = rule['confidence']
                    return rule
        return None

    def _infer_user_id_validation_rule(self):
        """Infer user-id validation rule."""
        user_id_fields = ['user_id', 'userid', 'customer_id', 'account_id']
        for field_name, obs in self.field_observations.items():
            if any(uid in field_name.lower() for uid in user_id_fields):
                if 'uuid' in obs['patterns']:
                    # Infer that user_id should match session
                    rule = {
                        'rule_id': f"user_id_validation_{field_name}",
                        'rule_type': 'user_id_validation',
                        'field_name': field_name,
                        'constraint': "user_id == session_user_id",
                        'confidence': min(100, obs['occurrences'] * 10),
                        'description': f"Field '{field_name}' should match the authenticated session user"
                    }
                    self.rule_confidence[rule['rule_id']] = rule['confidence']
                    return rule
        return None

    def _infer_rate_limiting_rule(self):
        """Infer rate limiting rule from response patterns."""
        if 'validation_error' in self.field_observations:
            obs = self.field_observations['validation_error']
            if obs['occurrences'] > 5:
                rule = {
                    'rule_id': 'rate_limiting_detection',
                    'rule_type': 'rate_limiting',
                    'field_name': 'request_rate',
                    'constraint': 'requests_per_minute <= threshold',
                    'confidence': min(100, obs['occurrences'] * 5),
                    'description': 'Endpoint enforces rate limiting on requests'
                }
                self.rule_confidence[rule['rule_id']] = rule['confidence']
                return rule
        return None

    def _infer_idempotency_rule(self):
        """Infer idempotency requirement for state-changing operations."""
        # Look for POST/PUT requests to the same endpoint
        endpoint_counts = defaultdict(int)
        for request, response in self.observed_flows:
            url = request.get('url', '')
            method = request.get('method', '')
            if method in ['POST', 'PUT', 'DELETE']:
                endpoint_counts[url] += 1

        for url, count in endpoint_counts.items():
            if count > 3:
                rule = {
                    'rule_id': f"idempotency_{hash(url) % 10000}",
                    'rule_type': 'idempotency',
                    'field_name': 'request_idempotency',
                    'constraint': 'duplicate_requests should be rejected',
                    'confidence': min(100, count * 10),
                    'description': f'Endpoint {url} should handle duplicate requests idempotently'
                }
                self.rule_confidence[rule['rule_id']] = rule['confidence']
                return rule
        return None

    def _persist_rules(self, rules):
        """Persist inferred rules to database."""
        import sqlite3
        from datetime import datetime

        try:
            with sqlite3.connect(self.db_path, check_same_thread=False) as conn:
                cursor = conn.cursor()
                for rule in rules:
                    cursor.execute('''INSERT OR REPLACE INTO business_rules
                            (rule_id, target, rule_type, field_name, rule_constraint, conf, created_at, last_seen)
                            VALUES (?, ?, ?, ?, ?, ?, ?, ?)''',
                            (rule['rule_id'], self.target, rule['rule_type'],
                             rule['field_name'], rule['constraint'], rule['confidence'],
                             datetime.now().isoformat(), datetime.now().isoformat()))
                conn.commit()
        except Exception as e:
            logging.error(f"Error persisting business rules: {e}")

    async def test_rules(self, target_url):
        """
        Test inferred business rules by sending violating requests.

        For each inferred rule:
        1. Craft a request that violates the rule
        2. Send the request to the target
        3. Check if the server accepts the violation
        4. Report vulnerabilities if violations are accepted

        Args:
            target_url: Base URL of the target application

        Returns:
            List of detected business logic vulnerabilities
        """
        vulnerabilities = []

        if not self.business_rules:
            logging.warning("No business rules to test")
            return vulnerabilities

        try:
            for rule in self.business_rules:
                # Skip low-confidence rules
                confidence = self.rule_confidence.get(rule['rule_id'], 0)
                if confidence < self.min_confidence_threshold:
                    logging.info(f"Skipping low-confidence rule: {rule['rule_id']} (confidence: {confidence})")
                    continue

                # Test the rule
                vuln = await self._test_single_rule(rule, target_url)
                if vuln:
                    vulnerabilities.append(vuln)

            logging.info(f"Business logic testing completed: {len(vulnerabilities)} vulnerabilities found")

        except Exception as e:
            logging.error(f"Error in BusinessLogicInferencer.test_rules: {e}")

        return vulnerabilities

    async def _test_single_rule(self, rule, target_url):
        """
        Test a single business rule.

        Args:
            rule: Business rule dictionary
            target_url: Base URL of the target

        Returns:
            Vulnerability dict if violation accepted, None otherwise
        """
        import json

        try:
            rule_type = rule['rule_type']
            field_name = rule['field_name']

            # Find an endpoint that uses this field
            test_endpoint = self._find_test_endpoint(field_name)
            if not test_endpoint:
                logging.info(f"No test endpoint found for field: {field_name}")
                return None

            # Craft violating request based on rule type
            if rule_type == 'price_validation':
                # Test with negative price
                violating_data = {field_name: -100}
            elif rule_type == 'quantity_validation':
                # Test with negative quantity
                violating_data = {field_name: -1}
            elif rule_type == 'coupon_stacking':
                # Test with multiple coupons
                violating_data = {field_name: ['COUPON1', 'COUPON2']}
            elif rule_type == 'user_id_validation':
                # Test with mismatched user_id
                violating_data = {field_name: '00000000-0000-0000-0000-000000000000'}
            elif rule_type == 'rate_limiting':
                # Test rapid requests
                return await self._test_rate_limiting(test_endpoint)
            elif rule_type == 'idempotency':
                # Test duplicate requests
                return await self._test_idempotency(test_endpoint)
            else:
                return None

            # Send violating request
            try:
                if not self.session_manager or not self.session_manager.async_session:
                    logging.warning("SessionManager not available for business logic testing")
                    return None

                async with self.session_manager.async_session.post(
                    test_endpoint,
                    json=violating_data,
                    headers={'Content-Type': 'application/json'}
                ) as resp:
                    response_text = await resp.text()

                    # Check if violation was accepted (status 2xx or 3xx)
                    if resp.status < 400:
                        # Violation accepted - vulnerability found
                        vuln = {
                            'type': f'Business Logic Violation: {rule_type}',
                            'severity': 'High',
                            'url': test_endpoint,
                            'field': field_name,
                            'evidence': f'Server accepted violating {field_name}: {violating_data}',
                            'rule': rule['description'],
                            'response_status': resp.status,
                            'response_body': response_text[:500]
                        }
                        logging.error(f"Business logic vulnerability found: {vuln['type']}")
                        return vuln
                    else:
                        # Violation rejected - rule is enforced
                        logging.info(f"Rule enforced: {rule['rule_id']} (status: {resp.status})")
                        return None

            except Exception as e:
                logging.error(f"Error testing rule {rule['rule_id']}: {e}")
                return None

        except Exception as e:
            logging.error(f"Error in _test_single_rule: {e}")
            return None

    def _find_test_endpoint(self, field_name):
        """Find an endpoint that uses the given field."""
        for field, obs in self.field_observations.items():
            if field == field_name and obs['endpoints']:
                # Return the most recently observed endpoint
                return list(obs['endpoints'])[-1]
        return None

    async def _test_rate_limiting(self, endpoint):
        """Test rate limiting by sending rapid requests."""
        try:
            if not self.session_manager or not self.session_manager.async_session:
                return None

            # Send 20 rapid requests
            responses = []
            for i in range(20):
                async with self.session_manager.async_session.get(endpoint) as resp:
                    responses.append(resp.status)
                # Minimal delay between requests
                await asyncio.sleep(0.01)

            # Check if rate limiting kicked in (429 status)
            if 429 in responses:
                # Rate limiting is enforced - not a vulnerability
                logging.info(f"Rate limiting enforced on {endpoint}")
                return None
            else:
                # No rate limiting detected - potential vulnerability
                vuln = {
                    'type': 'Business Logic Violation: Missing Rate Limiting',
                    'severity': 'Medium',
                    'url': endpoint,
                    'evidence': f'Sent 20 rapid requests without rate limiting (responses: {set(responses)})',
                    'rule': 'Endpoint should enforce rate limiting'
                }
                logging.error(f"Rate limiting vulnerability found on {endpoint}")
                return vuln

        except Exception as e:
            logging.error(f"Error testing rate limiting: {e}")
            return None

    async def _test_idempotency(self, endpoint):
        """Test idempotency by sending duplicate requests."""
        try:
            if not self.session_manager or not self.session_manager.async_session:
                return None

            # Send same request 5 times
            responses = []
            request_data = {'test': 'data'}

            for i in range(5):
                async with self.session_manager.async_session.post(
                    endpoint,
                    json=request_data
                ) as resp:
                    response_text = await resp.text()
                    responses.append((resp.status, response_text))
                await asyncio.sleep(0.1)

            # Check if all responses are identical (idempotent)
            statuses = [r[0] for r in responses]
            bodies = [r[1] for r in responses]

            if len(set(statuses)) == 1 and len(set(bodies)) == 1:
                # Idempotent - not a vulnerability
                logging.info(f"Idempotency enforced on {endpoint}")
                return None
            else:
                # Not idempotent - potential vulnerability
                vuln = {
                    'type': 'Business Logic Violation: Lack of Idempotency',
                    'severity': 'Medium',
                    'url': endpoint,
                    'evidence': f'Duplicate requests produced different responses (statuses: {set(statuses)})',
                    'rule': 'State-changing operations should be idempotent'
                }
                logging.error(f"Idempotency vulnerability found on {endpoint}")
                return vuln

        except Exception as e:
            logging.error(f"Error testing idempotency: {e}")
            return None

    def learn_from_database(self, target_url):
        """
        Load previously learned rules from database for the given target.

        Args:
            target_url: Target URL to load rules for

        Returns:
            List of loaded business rules
        """
        import sqlite3

        if not self.enable_persistence:
            return []

        try:
            with sqlite3.connect(self.db_path, check_same_thread=False) as conn:
                cursor = conn.cursor()
                cursor.execute('''SELECT rule_id, rule_type, field_name, rule_constraint, conf
                        FROM business_rules WHERE target = ?''', (target_url,))
                rows = cursor.fetchall()

                loaded_rules = []
                for row in rows:
                    rule_id, rule_type, field_name, rule_constraint, conf = row
                    rule = {
                        'rule_id': rule_id,
                        'rule_type': rule_type,
                        'field_name': field_name,
                        'constraint': rule_constraint,
                        'confidence': conf,
                        'description': f"Loaded from database: {rule_type} on {field_name}"
                    }
                    loaded_rules.append(rule)
                    self.rule_confidence[rule_id] = conf

                self.business_rules = loaded_rules
                logging.info(f"Loaded {len(loaded_rules)} business rules from database for {target_url}")
                return loaded_rules

        except Exception as e:
            logging.error(f"Error loading rules from database: {e}")
            return []

    def get_statistics(self):
        """
        Get statistics about the inferencer's learning state.

        Returns:
            Dictionary with statistics
        """
        return {
            'observed_flows': len(self.observed_flows),
            'business_rules': len(self.business_rules),
            'field_observations': len(self.field_observations),
            'rule_confidence': self.rule_confidence,
            'learning_enabled': self.learning_enabled,
            'persistence_enabled': self.enable_persistence
        }

    def reset(self):
        """Reset the inferencer's learning state."""
        self.observed_flows = []
        self.business_rules = []
        self.field_observations = defaultdict(lambda: {
            'values': [],
            'patterns': set(),
            'occurrences': 0,
            'endpoints': set(),
            'min_value': None,
            'max_value': None,
            'data_type': None
        })
        self.rule_confidence = {}
        logging.info("BusinessLogicInferencer reset")

# ============================================================================
# BLIND gRPC SERVICE DISCOVERER - Issue U16 Fix
# ============================================================================

class BlindGRPCDiscoverer:
    """
    Blind gRPC service discoverer for reflection-disabled endpoints.

    This class addresses the limitation that gRPC reflection is often disabled
    in production. It uses a discovery strategy that probes common service names
    with actual gRPC calls to identify valid services on the target server.

    Architecture:
    - discover(): Probe common service names and return the first valid one found
    - Uses actual gRPC channel connections instead of hardcoded service lists
    """

    # Common gRPC service names that frequently appear in production
    COMMON_SERVICES = [
        'grpc.health.v1.Health',
        'grpc.reflection.v1.ServerReflection',
        'google.iam.v1.IAMPolicy',
        'google.cloud.audit.AuditService',
        'envoy.service.auth.v3.Authorization',
        'helloworld.Greeter',
    ]

    async def discover(self, host: str, port: int) -> Optional[str]:
        """
        Discover a valid gRPC service on the target host:port.

        Strategy:
        - Iterate through common service names
        - Attempt to create a gRPC channel and call each service
        - Return the first service that responds successfully

        Args:
            host: gRPC server host
            port: gRPC server port

        Returns:
            Service name if discovered, None otherwise
        """
        if not GRPC_AVAILABLE:
            logging.warning("gRPC libraries not available - blind discovery disabled")
            return None

        for service in self.COMMON_SERVICES:
            try:
                # Create channel for this attempt
                channel = grpc.insecure_channel(f'{host}:{port}')

                # Check channel connectivity
                try:
                    grpc.channel_ready_future(channel).result(timeout=2)
                except grpc.FutureTimeoutError:
                    channel.close()
                    continue

                # Try to create a stub for the service
                stub = channel.unary_unary(f'/{service}/GetInfo')

                # Try to call with empty message
                from google.protobuf.struct_pb2 import Struct
                struct_msg = Struct()
                struct_msg.update({"test": "probe"})

                try:
                    resp = stub(struct_msg, timeout=2)
                    # If we get here, the service exists and responded
                    channel.close()
                    logging.info(f"Discovered gRPC service: {service}")
                    return service
                except grpc.RpcError as e:
                    # Check if error indicates service exists but method doesn't
                    # This is still a successful discovery
                    if e.code() in [grpc.StatusCode.UNIMPLEMENTED, grpc.StatusCode.NOT_FOUND]:
                        channel.close()
                        logging.info(f"Discovered gRPC service (method not found): {service}")
                        return service
                    channel.close()
                    continue

            except Exception as e:
                logging.debug(f"Failed to probe service {service}: {e}")
                continue

        return None

# ============================================================================
# BLIND SCHEMA INFERENCE ENGINE - Issue T5 Fix
# ============================================================================

class BlindSchemaInferencer:
    """
    Blind Schema Inference Engine for discovering API schemas when introspection is disabled.

    This class addresses the limitation that GraphQL introspection, gRPC reflection, and REST
    OpenAPI/Swagger are often disabled in production. It uses multiple inference strategies
    to discover schema information without relying on standard introspection mechanisms.

    Architecture:
    - infer_graphql_schema(): Discover GraphQL schema via error message analysis, field guessing, and batching
    - infer_grpc_schema(): Discover gRPC schema via reflection fallback, common service names, and trial calls
    - discover_openapi(): Discover REST API schema via common OpenAPI/Swagger endpoint probing

    Supported Strategies:
    GraphQL:
    - Field suggestion (Clairvoyance-style): Parse error messages for "Did you mean X?" suggestions
    - Type suggestion: Attempt __type introspection, fall back to common field name dictionary
    - Batching enumeration: Send aliased queries to probe multiple field names at once

    gRPC:
    - Reflection (if enabled): Standard gRPC server reflection protocol
    - Common service names: Dictionary of popular gRPC service/method names from public repos
    - Trial calls: Attempt protobuf descriptor inference via method name probing

    REST:
    - OpenAPI/Swagger discovery: Probe standard endpoints like /openapi.json, /swagger.json, /api-docs
    - Framework-specific paths: Spring Boot, Express, Django, FastAPI, etc.
    """

    # Common GraphQL field names derived from public APIs and schemas
    COMMON_GRAPHQL_FIELDS = {
        # User-related fields
        'id', 'name', 'email', 'username', 'password', 'firstName', 'lastName', 'avatar',
        'profile', 'bio', 'location', 'website', 'createdAt', 'updatedAt', 'isActive',
        # Query/mutation names
        'users', 'user', 'posts', 'post', 'comments', 'comment', 'login', 'logout',
        'register', 'signup', 'signin', 'createUser', 'updateUser', 'deleteUser',
        # Product/commerce
        'products', 'product', 'orders', 'order', 'cart', 'items', 'item', 'price',
        'quantity', 'total', 'discount', 'coupon', 'checkout', 'payment',
        # Content
        'content', 'title', 'body', 'description', 'summary', 'tags', 'categories',
        'published', 'author', 'slug', 'status', 'type',
        # Pagination
        'page', 'limit', 'offset', 'cursor', 'hasNext', 'hasPrevious', 'totalCount',
        # Authentication
        'token', 'refreshToken', 'accessToken', 'expires', 'scopes', 'permissions',
        'roles', 'groups',
        # System
        'version', 'environment', 'timestamp', 'idempotencyKey', 'requestId',
    }

    # Common gRPC service names derived from public repositories
    COMMON_GRPC_SERVICES = {
        # Authentication
        'AuthService', 'UserService', 'AccountService', 'IdentityService',
        # E-commerce
        'ProductService', 'OrderService', 'CartService', 'PaymentService',
        'InventoryService', 'CatalogService',
        # Social
        'PostService', 'CommentService', 'FeedService', 'NotificationService',
        'FollowService', 'LikeService',
        # Data/Storage
        'StorageService', 'FileService', 'BlobService', 'DataService',
        # Communication
        'ChatService', 'MessageService', 'EmailService', 'SMSService',
        # Analytics
        'AnalyticsService', 'MetricsService', 'LoggingService', 'TrackingService',
        # Common method names
        'Get', 'Create', 'Update', 'Delete', 'List', 'Search', 'Find', 'Query',
        'Authenticate', 'Authorize', 'Validate', 'Process', 'Execute',
    }

    # Common OpenAPI/Swagger endpoint paths
    OPENAPI_ENDPOINTS = [
        '/openapi.json',
        '/swagger.json',
        '/api-docs',
        '/v3/api-docs',
        '/swagger/v1/swagger.json',
        '/swagger/v2/swagger.json',
        '/api/swagger.json',
        '/api/openapi.json',
        '/api-docs/swagger.json',
        '/api-docs/openapi.json',
        '/swagger-ui.json',
        '/docs/swagger.json',
        '/docs/openapi.json',
        # Framework-specific
        '/swagger.yaml',
        '/openapi.yaml',
        '/api/swagger.yaml',
        '/api/openapi.yaml',
    ]

    def __init__(self, session_manager):
        """
        Initialize the Blind Schema Inference Engine.

        Args:
            session_manager: SessionManager instance for making HTTP requests
        """
        self.session_manager = session_manager
        self.discovered_schemas = {}  # Cache of discovered schemas
        self.field_name_cache = set()  # Cache of discovered field names
        self.openapi_cache = {}  # Cache of discovered OpenAPI specs

        logging.info("BlindSchemaInferencer initialized")

    async def infer_graphql_schema(self, endpoint: str) -> Dict[str, Any]:
        """
        Infer GraphQL schema when introspection is disabled.

        Strategy 1: Field suggestion (Clairvoyance-style)
        - Send malformed queries and parse error messages for "Did you mean X?" suggestions
        - Extract suggested field names from error responses

        Strategy 2: Type suggestion
        - Attempt __type introspection query
        - If introspection is disabled, fall back to field-name guessing using common field dictionary

        Strategy 3: Batching to enumerate
        - Send multiple aliased queries in a single request to probe many field names at once
        - Use GraphQL aliasing to test multiple fields simultaneously

        Args:
            endpoint: GraphQL endpoint URL

        Returns:
            Dictionary containing inferred schema information:
            {
                'fields': List of discovered field names,
                'types': List of discovered type names,
                'mutations': List of discovered mutation names,
                'queries': List of discovered query names,
                'inference_method': Which strategy succeeded
            }
        """
        result = {
            'fields': [],
            'types': [],
            'mutations': [],
            'queries': [],
            'inference_method': None,
            'endpoint': endpoint
        }

        # Check cache first
        if endpoint in self.discovered_schemas:
            logging.info(f"Using cached GraphQL schema for {endpoint}")
            return self.discovered_schemas[endpoint]

        logging.info(f"Attempting blind GraphQL schema inference for {endpoint}")

        # Strategy 1: Field suggestion via error message analysis
        fields = await self._graphql_field_suggestion(endpoint)
        if fields:
            result['fields'] = fields
            result['inference_method'] = 'field_suggestion'
            self.discovered_schemas[endpoint] = result
            logging.info(f"GraphQL schema inferred via field suggestion: {len(fields)} fields")
            return result

        # Strategy 2: Type suggestion with introspection fallback
        schema = await self._graphql_type_suggestion(endpoint)
        if schema:
            result.update(schema)
            result['inference_method'] = 'type_suggestion'
            self.discovered_schemas[endpoint] = result
            logging.info(f"GraphQL schema inferred via type suggestion: {len(schema.get('fields', []))} fields")
            return result

        # Strategy 3: Batching enumeration
        fields = await self._graphql_batching_enumeration(endpoint)
        if fields:
            result['fields'] = fields
            result['inference_method'] = 'batching'
            self.discovered_schemas[endpoint] = result
            logging.info(f"GraphQL schema inferred via batching: {len(fields)} fields")
            return result

        # All strategies failed
        logging.warning(f"All GraphQL schema inference strategies failed for {endpoint}")
        return result

    async def _graphql_field_suggestion(self, endpoint: str) -> List[str]:
        """
        Strategy 1: Field suggestion via error message analysis.

        Send intentionally malformed queries and parse error messages for
        "Did you mean X?" suggestions that reveal valid field names.

        Args:
            endpoint: GraphQL endpoint URL

        Returns:
            List of discovered field names
        """
        discovered_fields = set()

        # Test prefixes to trigger field suggestions
        test_prefixes = ['use', 'nam', 'ema', 'pas', 'id', 'tit', 'con', 'cre', 'upd', 'del']

        try:
            if not self.session_manager or not self.session_manager.async_session:
                logging.warning("SessionManager not available for GraphQL field suggestion")
                return []

            for prefix in test_prefixes:
                # Send malformed query with incomplete field name
                query = f'{{{{ {prefix} }}}}'
                payload = json.dumps({'query': query})

                try:
                    resp = await self.session_manager.async_session.post(
                        endpoint,
                        data=payload,
                        headers={'Content-Type': 'application/json'}
                    )
                    response_text = await resp.text()
                    await resp.close()

                    # Parse error message for suggestions
                    # Common patterns: "Did you mean 'username'?", "Cannot query field 'nam' on type 'Query'"
                    suggestion_patterns = [
                        r'Did you mean [\'"](\w+)[\'"]?',
                        r'Cannot query field [\'"]\w+[\'"]? on type [\'"]\w+[\'"]?\. Did you mean [\'"](\w+)[\'"]?',
                        r'Field [\'"]\w+[\'"]? doesn\'t exist on type [\'"]\w+[\'"]?\. Did you mean [\'"](\w+)[\'"]?',
                    ]

                    for pattern in suggestion_patterns:
                        matches = re.findall(pattern, response_text, re.IGNORECASE)
                        for match in matches:
                            if isinstance(match, tuple):
                                match = match[0] if match else ''
                            if match and match not in discovered_fields:
                                discovered_fields.add(match)
                                logging.debug(f"Discovered GraphQL field via suggestion: {match}")

                except Exception as e:
                    logging.debug(f"Field suggestion request failed for prefix '{prefix}': {e}")
                    continue

        except Exception as e:
            logging.error(f"Error in GraphQL field suggestion: {e}")

        return list(discovered_fields)

    async def _graphql_type_suggestion(self, endpoint: str) -> Dict[str, Any]:
        """
        Strategy 2: Type suggestion with introspection fallback.

        First attempt standard __type introspection. If disabled, fall back
        to field-name guessing using a dictionary of common GraphQL field names.

        Args:
            endpoint: GraphQL endpoint URL

        Returns:
            Dictionary with discovered schema information
        """
        result = {'fields': [], 'types': [], 'mutations': [], 'queries': []}

        # Try introspection first
        introspection_query = '''
        {
            __schema {
                types {
                    name
                    fields {
                        name
                    }
                }
            }
        }
        '''

        try:
            if not self.session_manager or not self.session_manager.async_session:
                logging.warning("SessionManager not available for GraphQL type suggestion")
                return {}

            payload = json.dumps({'query': introspection_query})

            resp = await self.session_manager.async_session.post(
                endpoint,
                data=payload,
                headers={'Content-Type': 'application/json'}
            )
            response_text = await resp.text()
            await resp.close()

            # Check if introspection succeeded
            if resp.status == 200 and 'Cannot query field "__schema"' not in response_text:
                try:
                    data = json.loads(response_text)
                    if 'data' in data and '__schema' in data['data']:
                        # Introspection succeeded
                        types = data['data']['__schema'].get('types', [])
                        for type_obj in types:
                            type_name = type_obj.get('name')
                            if type_name and type_name not in ['Query', 'Mutation', 'Subscription', '__Schema', '__Type', '__Field', '__InputValue', '__EnumValue', '__Directive']:
                                result['types'].append(type_name)

                            fields = type_obj.get('fields', [])
                            for field in fields:
                                field_name = field.get('name')
                                if field_name and field_name not in result['fields']:
                                    result['fields'].append(field_name)

                        logging.info(f"GraphQL introspection succeeded: {len(result['fields'])} fields, {len(result['types'])} types")
                        return result
                except json.JSONDecodeError:
                    pass

        except Exception as e:
            logging.debug(f"GraphQL introspection failed: {e}")

        # Introspection disabled - fall back to field name guessing
        logging.info("GraphQL introspection disabled, using field name guessing")

        discovered_fields = set()

        # Try common field names via simple queries
        for field_name in self.COMMON_GRAPHQL_FIELDS:
            # Test if field exists on Query type
            query = f'{{{{ {field_name} }}}}'
            payload = json.dumps({'query': query})

            try:
                resp = await self.session_manager.async_session.post(
                    endpoint,
                    data=payload,
                    headers={'Content-Type': 'application/json'}
                )
                response_text = await resp.text()
                await resp.close()

                # If error doesn't say "Cannot query field", field might exist
                if resp.status == 200 or f'Cannot query field "{field_name}"' not in response_text:
                    discovered_fields.add(field_name)
                    logging.debug(f"Discovered GraphQL field via guessing: {field_name}")

            except Exception as e:
                logging.debug(f"Field guess failed for '{field_name}': {e}")
                continue

        result['fields'] = list(discovered_fields)
        return result

    async def _graphql_batching_enumeration(self, endpoint: str) -> List[str]:
        """
        Strategy 3: Batching enumeration using GraphQL aliases.

        Send multiple aliased queries in a single request to probe many
        field names at once. This is more efficient than individual requests.

        Args:
            endpoint: GraphQL endpoint URL

        Returns:
            List of discovered field names
        """
        discovered_fields = set()

        # Batch size (GraphQL has limits on query complexity)
        batch_size = 20

        # Convert field set to list for batching
        field_list = list(self.COMMON_GRAPHQL_FIELDS)

        for i in range(0, len(field_list), batch_size):
            batch = field_list[i:i + batch_size]

            # Create aliased query
            aliased_fields = []
            for idx, field in enumerate(batch):
                aliased_fields.append(f'f{idx}: {field}')

            query = '{ ' + ' '.join(aliased_fields) + ' }'
            payload = json.dumps({'query': query})

            try:
                if not self.session_manager or not self.session_manager.async_session:
                    break

                async with self.session_manager.async_session.post(
                    endpoint,
                    data=payload,
                    headers={'Content-Type': 'application/json'}
                ) as resp:
                    response_text = await resp.text()

                    # Parse response to see which fields succeeded
                    try:
                        data = json.loads(response_text)
                        if 'data' in data:
                            for idx, field in enumerate(batch):
                                alias = f'f{idx}'
                                if alias in data['data'] and data['data'][alias] is not None:
                                    discovered_fields.add(field)
                                    logging.debug(f"Discovered GraphQL field via batching: {field}")
                    except json.JSONDecodeError:
                        # Response might have errors - check error messages
                        # Fields not in error list might be valid
                        pass

            except Exception as e:
                logging.debug(f"Batching enumeration failed for batch {i//batch_size}: {e}")
                continue

        return list(discovered_fields)

    async def infer_grpc_schema(self, host: str, port: int) -> Dict[str, Any]:
        """
        Infer gRPC schema when reflection is disabled.

        Strategy 1: Reflection (if enabled)
        - Attempt standard gRPC server reflection protocol
        - List services and retrieve file descriptors

        Strategy 2: Common service names
        - Use dictionary of popular gRPC service/method names from public repos
        - Probe for common service names

        Strategy 3: Protobuf descriptor guessing
        - Attempt descriptor inference via trial method calls
        - Analyze response structure to infer message format

        Args:
            host: gRPC server host
            port: gRPC server port

        Returns:
            Dictionary containing inferred schema information:
            {
                'services': List of discovered service names,
                'methods': List of discovered method names,
                'inference_method': Which strategy succeeded
            }
        """
        result = {
            'services': [],
            'methods': [],
            'inference_method': None,
            'host': host,
            'port': port
        }

        # Check cache first
        cache_key = f"{host}:{port}"
        if cache_key in self.discovered_schemas:
            logging.info(f"Using cached gRPC schema for {cache_key}")
            return self.discovered_schemas[cache_key]

        logging.info(f"Attempting blind gRPC schema inference for {host}:{port}")

        # Strategy 1: Reflection (if enabled)
        if GRPC_AVAILABLE:
            schema = await grpc_reflection(host, port)
            if schema:
                result.update(schema)
                result['inference_method'] = 'reflection'
                self.discovered_schemas[cache_key] = result
                logging.info(f"gRPC schema inferred via reflection: {len(schema.get('services', []))} services")
                return result

        # Strategy 2: Common service names
        schema = await self._grpc_common_services(host, port)
        if schema:
            result.update(schema)
            result['inference_method'] = 'common_services'
            self.discovered_schemas[cache_key] = result
            logging.info(f"gRPC schema inferred via common services: {len(schema.get('services', []))} services")
            return result

        # Strategy 3: Trial calls for descriptor guessing
        schema = await self._grpc_trial_calls(host, port)
        if schema:
            result.update(schema)
            result['inference_method'] = 'trial_calls'
            self.discovered_schemas[cache_key] = result
            logging.info(f"gRPC schema inferred via trial calls: {len(schema.get('methods', []))} methods")
            return result

        # All strategies failed
        logging.warning(f"All gRPC schema inference strategies failed for {host}:{port}")
        return result

    async def _grpc_reflection(self, host: str, port: int) -> Dict[str, Any]:
        """
        Strategy 1: gRPC server reflection.

        Attempt to use the standard gRPC reflection protocol to discover
        available services and their descriptors.

        Args:
            host: gRPC server host
            port: gRPC server port

        Returns:
            Dictionary with discovered services and methods
        """
        result = {'services': [], 'methods': []}

        if not GRPC_AVAILABLE:
            return result

        try:
            import grpc
            from grpc_reflection.v1alpha import reflection_pb2_grpc, reflection_pb2

            # Create channel
            channel = grpc.insecure_channel(f"{host}:{port}")

            # Create reflection client
            reflection_client = reflection_pb2_grpc.ServerReflectionStub(channel)

            # List services
            request = reflection_pb2.ServerReflectionRequest(list_services="")
            responses = reflection_client.ServerReflectionInfo(iter([request]))

            services = set()
            for response in responses:
                if response.list_services_response:
                    for service in response.list_services_response.service:
                        service_name = service.name
                        if service_name and not service_name.startswith('grpc.reflection'):
                            services.add(service_name)
                            logging.debug(f"Discovered gRPC service via reflection: {service_name}")

            result['services'] = list(services)

            # For each service, get file descriptor to extract methods
            for service in services:
                try:
                    request = reflection_pb2.ServerReflectionRequest(
                        file_containing_symbol=service
                    )
                    responses = reflection_client.ServerReflectionInfo(iter([request]))

                    for response in responses:
                        if response.file_descriptor_response:
                            # Parse descriptor to extract method names
                            for fd in response.file_descriptor_response.file_descriptor_proto:
                                # This is a simplified extraction - full parsing would use protobuf
                                fd_str = fd.decode('utf-8', errors='ignore')
                                # Extract method names from descriptor
                                method_pattern = r'rpc\s+(\w+)\s*\('
                                methods = re.findall(method_pattern, fd_str)
                                for method in methods:
                                    if method not in result['methods']:
                                        result['methods'].append(method)
                                        logging.debug(f"Discovered gRPC method: {method}")

                except Exception as e:
                    logging.debug(f"Failed to get descriptor for service {service}: {e}")
                    continue

            channel.close()

        except Exception as e:
            logging.debug(f"gRPC reflection failed: {e}")

        return result

    async def _grpc_common_services(self, host: str, port: int) -> Dict[str, Any]:
        """
        Strategy 2: Common service names from public repositories.

        Probe for common gRPC service names that appear in popular
        open-source projects and public APIs.

        Args:
            host: gRPC server host
            port: gRPC server port

        Returns:
            Dictionary with discovered services
        """
        result = {'services': [], 'methods': []}

        if not GRPC_AVAILABLE:
            return result

        discovered_services = set()

        try:
            import grpc

            # Create channel
            channel = grpc.insecure_channel(f"{host}:{port}")

            # Try to connect to common service names
            for service_name in self.COMMON_GRPC_SERVICES:
                try:
                    # Attempt to create a stub for the service
                    # This will fail if the service doesn't exist, but the error
                    # message might reveal information
                    stub = channel.unary_unary(
                        f"/{service_name}/Get",
                        None,
                        None,
                        None
                    )
                    discovered_services.add(service_name)
                    logging.debug(f"Discovered gRPC service via common names: {service_name}")

                except Exception:
                    # Service doesn't exist - expected
                    continue

            channel.close()

        except Exception as e:
            logging.debug(f"gRPC common services probe failed: {e}")

        result['services'] = list(discovered_services)
        return result

    async def _grpc_trial_calls(self, host: str, port: int) -> Dict[str, Any]:
        """
        Strategy 3: Protobuf descriptor guessing via trial calls.

        Attempt to infer the schema by making trial calls to common
        method names and analyzing response structure.

        Args:
            host: gRPC server host
            port: gRPC server port

        Returns:
            Dictionary with discovered methods
        """
        result = {'methods': []}

        if not GRPC_AVAILABLE:
            return result

        discovered_methods = set()

        try:
            import grpc

            # Create channel
            channel = grpc.insecure_channel(f"{host}:{port}")

            # Try common method patterns
            common_methods = ['Get', 'Create', 'Update', 'Delete', 'List', 'Find']

            for method in common_methods:
                for service in self.COMMON_GRPC_SERVICES:
                    full_method = f"/{service}/{method}"

                    try:
                        # Attempt a unary call with empty message
                        stub = channel.unary_unary(full_method, None, None, None)
                        # Try to call - will fail but may reveal if method exists
                        discovered_methods.add(full_method)
                        logging.debug(f"Discovered gRPC method via trial: {full_method}")

                    except Exception:
                        continue

            channel.close()

        except Exception as e:
            logging.debug(f"gRPC trial calls failed: {e}")

        result['methods'] = list(discovered_methods)
        return result

    async def discover_openapi(self, base_url: str) -> Dict[str, Any]:
        """
        Discover REST API OpenAPI/Swagger schema.

        Probe common OpenAPI/Swagger endpoint paths to discover API documentation.
        This addresses the limitation that many REST APIs don't publish their schema.

        Args:
            base_url: Base URL of the REST API

        Returns:
            Dictionary containing discovered OpenAPI spec:
            {
                'spec': The OpenAPI/Swagger JSON spec,
                'endpoint': The URL where the spec was found,
                'endpoints_tested': List of endpoints that were probed
            }
        """
        result = {
            'spec': None,
            'endpoint': None,
            'endpoints_tested': []
        }

        # Check cache first
        if base_url in self.openapi_cache:
            logging.info(f"Using cached OpenAPI spec for {base_url}")
            return self.openapi_cache[base_url]

        logging.info(f"Attempting OpenAPI/Swagger discovery for {base_url}")

        # Parse base URL
        parsed = urlparse(base_url)
        base_path = parsed.path.rstrip('/')

        # Try each common endpoint
        for endpoint_path in self.OPENAPI_ENDPOINTS:
            full_url = f"{parsed.scheme}://{parsed.netloc}{base_path}{endpoint_path}"
            result['endpoints_tested'].append(full_url)

            try:
                if not self.session_manager or not self.session_manager.async_session:
                    continue

                async with self.session_manager.async_session.get(full_url) as resp:
                    if resp.status == 200:
                        content_type = resp.headers.get('Content-Type', '')

                        # Check if response is JSON
                        if 'application/json' in content_type:
                            response_text = await resp.text()

                            try:
                                spec = json.loads(response_text)

                                # Validate that it looks like an OpenAPI spec
                                if 'openapi' in spec or 'swagger' in spec or 'paths' in spec:
                                    result['spec'] = spec
                                    result['endpoint'] = full_url
                                    self.openapi_cache[base_url] = result
                                    logging.info(f"OpenAPI spec discovered at {full_url}")
                                    return result

                            except json.JSONDecodeError:
                                pass

            except Exception as e:
                logging.debug(f"OpenAPI endpoint probe failed for {full_url}: {e}")
                continue

        # No OpenAPI spec found
        logging.warning(f"No OpenAPI/Swagger spec found for {base_url} (tested {len(result['endpoints_tested'])} endpoints)")
        return result

    def get_statistics(self) -> Dict[str, Any]:
        """
        Get statistics about the inference engine's performance.

        Returns:
            Dictionary with statistics
        """
        return {
            'discovered_schemas_count': len(self.discovered_schemas),
            'openapi_cache_count': len(self.openapi_cache),
            'field_name_cache_count': len(self.field_name_cache),
            'common_graphql_fields_count': len(self.COMMON_GRAPHQL_FIELDS),
            'common_grpc_services_count': len(self.COMMON_GRPC_SERVICES),
            'openapi_endpoints_count': len(self.OPENAPI_ENDPOINTS)
        }

    def reset(self):
        """Reset the inference engine's cache."""
        self.discovered_schemas = {}
        self.field_name_cache = set()
        self.openapi_cache = {}
        logging.info("BlindSchemaInferencer reset")

class FP_Database:
    def __init__(self, db_path=None, config=None):
        self.config = config or {}
        # Use instance-specific database path to prevent conflicts with concurrent scans
        if db_path is None:
            import os
            instance_id = uuid.uuid4().hex[:8]
            db_path = f"fp_learn_{instance_id}.db"
        self.db_path = db_path
        
        # Initialize database using context manager
        with sqlite3.connect(db_path, check_same_thread=False) as conn:
            cursor = conn.cursor()
            cursor.execute('''CREATE TABLE IF NOT EXISTS false_positives
                    (id INTEGER PRIMARY KEY, type TEXT, url TEXT, parameter TEXT, payload TEXT, confidence REAL, feature_vector TEXT)''')
            # Updated table for parameter-specific false positives with scoping
            # Scoped by target (domain) + endpoint (path) + parameter + vulnerability type
            cursor.execute('''CREATE TABLE IF NOT EXISTS parameter_fp
                    (target TEXT, endpoint TEXT, parameter TEXT, vuln_type TEXT, marked_at TEXT, 
                    PRIMARY KEY (target, endpoint, parameter, vuln_type))''')
            conn.commit()
        
        # Keep connection open for long-lived operations
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.c = self.conn.cursor()
        
        self.lock = asyncio.Lock()
        self.pending_inserts = []
        self.batch_size = 100
        
        # Configuration for duplicate threshold
        fp_config = self.config.get('fp_handling', {})
        
        # Confidence decay on duplicates: Track vulnerability signatures with size limit
        self.vulnerability_signatures = {}  # signature -> count
        self.signature_lock = asyncio.Lock()
        self.max_signatures = fp_config.get('max_vulnerability_signatures', 10000) if config else 10000
        # Set reasonable default truncation to prevent memory issues with large responses
        self.signature_truncation_length = fp_config.get('signature_truncation_length', 500)  # Default 500 chars
        # Limit URLs stored per signature to prevent memory explosion
        self.max_urls_per_signature = fp_config.get('max_urls_per_signature', 100) if config else 100
        
        self.duplicate_threshold = fp_config.get('duplicate_threshold', 10)
        self.parameter_specific_suppression = fp_config.get('parameter_specific_suppression', True)
        self.context_specific_whitelist = fp_config.get('context_specific_whitelist', True)
        self.confidence_decay_on_duplicates = fp_config.get('confidence_decay_on_duplicates', True)
        self.smart_signature_eviction = fp_config.get('smart_signature_eviction', True)
        self.temporal_decay_factor = fp_config.get('temporal_decay_factor', 0.8)
        self.min_confidence_floor = fp_config.get('min_confidence_floor', 30)
        
        # Make temporal decay settings available for use in scanner classes
        # These are internal settings derived from config, so validation is not needed
        self.config['temporal_decay_factor'] = self.temporal_decay_factor
        self.config['min_confidence_floor'] = self.min_confidence_floor
    
    def _generate_feature_vector(self, vuln):
        """Generate a feature vector hash based on full URL, parameter name, and DOM context"""
        import hashlib
        from urllib.parse import urlparse
        
        # Extract full URL components (include domain to prevent cross-domain contamination)
        parsed_url = urlparse(vuln['url'])
        url_signature = f"{parsed_url.netloc}{parsed_url.path}"  # Include domain
        
        # Get parameter name
        parameter = vuln.get('parameter', '')
        
        # Get DOM context if available
        dom_context = vuln.get('dom_context', '')
        
        # Create a normalized string for hashing with domain
        normalized_string = f"{vuln['type']}|{url_signature}|{parameter}|{dom_context}".lower().strip()
        
        # Generate hash
        hash_obj = hashlib.sha256(normalized_string.encode())
        return hash_obj.hexdigest()
    
    def _generate_vulnerability_signature(self, vuln):
        """
        Generate a signature for duplicate detection based on (url, parameter, payload_family).

        This implements Issue B23: Group by (url, parameter, payload_family) to deduplicate
        XSS and SQLi findings that appear in multiple sinks on the same page.

        This implements Issue M4: Include sorted query parameter keys in signature to prevent
        collapsing distinct findings on different URLs with same path (e.g., /user?id=1 vs /user?id=2).

        Args:
            vuln: Vulnerability dictionary

        Returns:
            str: Hash signature for deduplication
        """
        import hashlib
        from urllib.parse import urlparse, parse_qs

        # Extract full URL components (include domain to prevent cross-domain false positives)
        parsed_url = urlparse(vuln['url'])
        url_signature = f"{parsed_url.netloc}{parsed_url.path}"

        # Include sorted query parameter keys in signature (Issue M4)
        # Values are dynamic, so we only include keys to distinguish different query structures
        if parsed_url.query:
            query_keys = sorted(parse_qs(parsed_url.query).keys())
            if query_keys:
                url_signature = f"{url_signature}?{','.join(query_keys)}"

        # Get vulnerability type
        vuln_type = vuln['type']

        # Get parameter name if available
        parameter = vuln.get('parameter', '')

        # Get payload for family classification
        payload = vuln.get('payload', '')

        # Get error string for SQLi error-based classification (Issue B23)
        error_string = None
        if 'sqli' in vuln_type.lower():
            # Extract error string from evidence or full_evidence for SQLi
            evidence = vuln.get('evidence', '')
            full_evidence = vuln.get('full_evidence', '')
            # Use the evidence that contains error information
            if 'error' in evidence.lower() or 'syntax' in evidence.lower():
                error_string = evidence
            elif full_evidence and ('error' in full_evidence.lower() or 'syntax' in full_evidence.lower()):
                error_string = full_evidence

        # Classify payload into family for deduplication
        # This groups similar payloads together (e.g., all script_tag XSS payloads)
        if hasattr(XSSContextClassifier, '_classify_payload_family'):
            payload_family = XSSContextClassifier._classify_payload_family(payload, vuln_type, error_string)
        else:
            # Fallback if classifier not available
            payload_family = 'generic'

        # Create a normalized signature string with (url, parameter, payload_family)
        # This deduplicates multiple sinks of the same vulnerability on the same page
        signature_string = f"{vuln_type}|{url_signature}|{parameter}|{payload_family}".lower().strip()

        # Generate hash
        hash_obj = hashlib.sha256(signature_string.encode())
        return hash_obj.hexdigest()

    async def check_duplicate_and_decay(self, vuln):
        """
        Check if this is a duplicate vulnerability and apply confidence decay with aggregation.
        
        If the exact same vulnerability (same signature) is found on multiple URLs
        with identical response patterns, aggregate them into a single finding with metadata
        about affected endpoints instead of reporting duplicates.
        
        Returns:
            tuple: (is_duplicate, adjusted_confidence, should_report, duplicate_info)
        """
        if not self.confidence_decay_on_duplicates:
            return False, vuln.get('confidence', 50), True, None
            
        async with self.signature_lock:
            signature = self._generate_vulnerability_signature(vuln)
            
            if signature not in self.vulnerability_signatures:
                # First occurrence - report normally
                self.vulnerability_signatures[signature] = {
                    'count': 1,
                    'first_url': vuln['url'],
                    'original_confidence': vuln.get('confidence', 50),
                    'affected_urls': [vuln['url']],
                    'last_access': time.time(),
                    'truncated_urls': 0,  # Track URLs that couldn't be stored due to memory limits
                    'logged_duplicate': False  # Track if we've already logged this as a duplicate
                }
                
                # Enforce size limit with smarter eviction if enabled
                if len(self.vulnerability_signatures) > self.max_signatures:
                    if self.smart_signature_eviction:
                        self._evict_least_recent_signatures()
                    else:
                        # Fallback to FIFO eviction
                        keys_to_remove = list(self.vulnerability_signatures.keys())[:len(self.vulnerability_signatures) - self.max_signatures]
                        for key in keys_to_remove:
                            del self.vulnerability_signatures[key]
                
                return False, vuln.get('confidence', 50), True, None
            else:
                # Duplicate detected - check threshold
                self.vulnerability_signatures[signature]['count'] += 1
                
                # Track multiple sinks for same URL (Issue B23)
                # If the same URL appears again in affected_urls, it indicates multiple sinks on the same page
                if vuln['url'] in self.vulnerability_signatures[signature]['affected_urls']:
                    # Same URL found again - this is a multiple sink on the same page
                    if 'multiple_sinks' not in self.vulnerability_signatures[signature]:
                        self.vulnerability_signatures[signature]['multiple_sinks'] = 0
                    self.vulnerability_signatures[signature]['multiple_sinks'] += 1
                    logging.info(f"Multiple sinks detected for signature {signature[:16]}... on URL {vuln['url']}: {self.vulnerability_signatures[signature]['multiple_sinks']} additional sinks")
                else:
                    # Different URL - add to affected URLs list
                    # Limit URLs stored per signature to prevent memory explosion
                    if len(self.vulnerability_signatures[signature]['affected_urls']) < self.max_urls_per_signature:
                        self.vulnerability_signatures[signature]['affected_urls'].append(vuln['url'])
                    else:
                        self.vulnerability_signatures[signature]['truncated_urls'] = self.vulnerability_signatures[signature].get('truncated_urls', 0) + 1
                
                self.vulnerability_signatures[signature]['last_access'] = time.time()
                count = self.vulnerability_signatures[signature]['count']
                
                # Only apply confidence decay if above threshold
                if count >= self.duplicate_threshold:
                    # Decay confidence for duplicates above threshold
                    decay_factor = max(0.1, 1.0 - ((count - self.duplicate_threshold) * 0.1))
                    adjusted_confidence = int(vuln.get('confidence', 50) * decay_factor)
                    should_report = adjusted_confidence >= 30  # Minimum threshold for reporting
                else:
                    # Below threshold - report normally
                    adjusted_confidence = vuln.get('confidence', 50)
                    should_report = True
                
                duplicate_info = {
                    'signature': signature,
                    'first_url': self.vulnerability_signatures[signature]['first_url'],
                    'total_count': count,
                    'affected_urls': self.vulnerability_signatures[signature]['affected_urls'].copy(),
                    'truncated_urls': self.vulnerability_signatures[signature].get('truncated_urls', 0),
                    'multiple_sinks': self.vulnerability_signatures[signature].get('multiple_sinks', 0)
                }
                
                # Only log duplicate detection once per signature to prevent excessive logging
                if not self.vulnerability_signatures[signature]['logged_duplicate']:
                    logging.debug(f"Duplicate vulnerability detected (count={count}, adjusted_confidence={adjusted_confidence}%, should_report={should_report}")
                    self.vulnerability_signatures[signature]['logged_duplicate'] = True
                
                return True, adjusted_confidence, should_report, duplicate_info
    
    def _evict_least_recent_signatures(self):
        """Evict least recently used signatures with adaptive memory-aware strategy"""
        # Sort by composite score: prioritize keeping high-count signatures
        # Score = last_access (recent) + count (frequency) - memory_cost
        def signature_score(item):
            sig_data = item[1]
            recency_score = sig_data['last_access']
            frequency_score = sig_data['count'] * 1000  # Weight frequency heavily
            memory_cost = len(sig_data.get('affected_urls', [])) * 10  # Penalize large URL lists
            # Also penalize signatures with many truncated URLs (memory pressure indicator)
            truncation_penalty = sig_data.get('truncated_urls', 0) * 50
            return recency_score + frequency_score - memory_cost - truncation_penalty
        
        sorted_signatures = sorted(
            self.vulnerability_signatures.items(),
            key=signature_score
        )
        
        # Remove lowest-scoring entries (least valuable)
        num_to_remove = len(self.vulnerability_signatures) - self.max_signatures
        evicted_count = 0
        for i in range(num_to_remove):
            key = sorted_signatures[i][0]
            sig_data = self.vulnerability_signatures[key]
            del self.vulnerability_signatures[key]
            evicted_count += 1
            logging.error(f"Evicted signature {key[:16]}... (count={sig_data['count']}, urls={len(sig_data.get('affected_urls', []))}, truncated={sig_data.get('truncated_urls', 0)} from duplicate tracking")
        
        logging.error(f"Evicted {evicted_count} signatures from duplicate tracking to maintain memory limits")
    
    async def get_duplicate_stats(self):
        """Get statistics about duplicate vulnerabilities"""
        async with self.signature_lock:
            total_signatures = len(self.vulnerability_signatures)
            duplicates = {sig: data for sig, data in self.vulnerability_signatures.items() if data['count'] > 1}
            duplicate_count = len(duplicates)
            total_duplicate_instances = sum(data['count'] for data in duplicates.values())
            
            return {
                'total_unique_signatures': total_signatures,
                'duplicate_signatures': duplicate_count,
                'total_duplicate_instances': total_duplicate_instances,
                'suppressed_instances': sum(max(0, data['count'] - 1) for data in duplicates.values()),
                'aggregated_findings': duplicate_count,
                'affected_urls_per_duplicate': {sig: len(data.get('affected_urls', [])) for sig, data in duplicates.items()},
                'above_threshold_instances': sum(1 for data in duplicates.values() if data['count'] >= self.duplicate_threshold),
                'truncated_urls_total': sum(data.get('truncated_urls', 0) for data in self.vulnerability_signatures.values()),
                'memory_efficiency': {
                    'max_signatures': self.max_signatures,
                    'max_urls_per_signature': self.max_urls_per_signature,
                    'signature_truncation_length': self.signature_truncation_length
                }
            }
    
    async def record_fp(self, vuln, mark_parameter=False):
        """Record a false positive vulnerability. If mark_parameter=True, also mark the parameter name as FP with scoping."""
        async with self.lock:
            feature_vector = self._generate_feature_vector(vuln)
            self.pending_inserts.append((vuln['type'], vuln['url'], vuln.get('parameter', ''), vuln.get('payload', ''), vuln.get('confidence', 0), feature_vector))
            if len(self.pending_inserts) >= self.batch_size:
                self._flush_batch()
        
        # Parameter-specific suppression: Mark parameter as FP with scoping if requested
        # This is done outside the lock to avoid deadlock
        if mark_parameter and vuln.get('parameter'):
            await self.mark_parameter_fp(vuln['parameter'], url=vuln.get('url'), vuln_type=vuln.get('type'))
    
    def _flush_batch(self):
        """Flush pending inserts to database. Caller must already hold self.lock."""
        if self.pending_inserts:
            self.c.executemany("INSERT OR REPLACE INTO false_positives (type, url, parameter, payload, confidence, feature_vector) VALUES (?,?,?,?,?,?)", self.pending_inserts)
            self.conn.commit()
            self.pending_inserts.clear()
    
    async def is_fp(self, vuln):
        async with self.lock:
            self._flush_batch()
            feature_vector = self._generate_feature_vector(vuln)
            # Check for matching feature vector (same endpoint/parameter combination)
            self.c.execute("SELECT 1 FROM false_positives WHERE feature_vector=?",
                            (feature_vector,))
            return self.c.fetchone() is not None

    def is_fp_sync(self, vuln):
        """
        Synchronous version of is_fp for use in GUI threads (e.g., ScanTab.add_finding).
        This is called from the main PyQt5 thread which is synchronous.
        """
        # Flush any pending inserts before checking
        if self.pending_inserts:
            self.c.executemany("INSERT OR REPLACE INTO false_positives (type, url, parameter, payload, confidence, feature_vector) VALUES (?,?,?,?,?,?)", self.pending_inserts)
            self.conn.commit()
            self.pending_inserts.clear()
        
        feature_vector = self._generate_feature_vector(vuln)
        # Check for matching feature vector (same endpoint/parameter combination)
        self.c.execute("SELECT 1 FROM false_positives WHERE feature_vector=?",
                        (feature_vector,))
        return self.c.fetchone() is not None
    
    async def is_parameter_fp(self, parameter_name, url=None, vuln_type=None):
        """
        Check if a parameter is marked as a false positive with scoping.
        
        Args:
            parameter_name: The parameter name to check
            url: The full URL to extract target and endpoint from
            vuln_type: The vulnerability type (e.g., 'xss', 'sqli', etc.)
        
        Returns:
            bool: True if parameter is marked as FP for this specific context
        """
        async with self.lock:
            self._flush_batch()
            
            # If URL or vuln_type not provided, fall back to legacy behavior (global by parameter name)
            if not url or not vuln_type:
                self.c.execute("SELECT 1 FROM parameter_fp WHERE parameter=?", (parameter_name,))
                return self.c.fetchone() is not None
            
            # Extract target (domain) and endpoint (path) from URL
            from urllib.parse import urlparse
            parsed_url = urlparse(url)
            target = parsed_url.netloc
            endpoint = parsed_url.path
            
            # Check for scoped false positive
            self.c.execute(
                "SELECT 1 FROM parameter_fp WHERE target=? AND endpoint=? AND parameter=? AND vuln_type=?",
                (target, endpoint, parameter_name, vuln_type)
            )
            return self.c.fetchone() is not None
    
    async def mark_parameter_fp(self, parameter_name, url=None, vuln_type=None):
        """
        Mark a parameter as a false positive with scoping.
        
        Args:
            parameter_name: The parameter name to mark as FP
            url: The full URL to extract target and endpoint from
            vuln_type: The vulnerability type (e.g., 'xss', 'sqli', etc.)
        """
        async with self.lock:
            from datetime import datetime
            marked_at = datetime.now().isoformat()
            
            # If URL or vuln_type not provided, fall back to legacy behavior (global by parameter name)
            if not url or not vuln_type:
                # Insert with empty target/endpoint/vuln_type for legacy entries
                self.c.execute(
                    "INSERT OR REPLACE INTO parameter_fp (parameter, marked_at, target, endpoint, vuln_type) VALUES (?, ?, '', '', '')",
                    (parameter_name, marked_at)
                )
            else:
                # Extract target (domain) and endpoint (path) from URL
                from urllib.parse import urlparse
                parsed_url = urlparse(url)
                target = parsed_url.netloc
                endpoint = parsed_url.path
                
                # Insert with full scoping
                self.c.execute(
                    "INSERT OR REPLACE INTO parameter_fp (target, endpoint, parameter, vuln_type, marked_at) VALUES (?, ?, ?, ?, ?)",
                    (target, endpoint, parameter_name, vuln_type, marked_at)
                )
            
            self.conn.commit()
    
    async def get_parameter_fp_list(self):
        """Get list of all parameters marked as false positives with their scoping information"""
        async with self.lock:
            self._flush_batch()
            self.c.execute("SELECT target, endpoint, parameter, vuln_type, marked_at FROM parameter_fp")
            rows = self.c.fetchall()
            return [
                {
                    'target': row[0],
                    'endpoint': row[1],
                    'parameter': row[2],
                    'vuln_type': row[3],
                    'marked_at': row[4]
                }
                for row in rows
            ]

    def get_learned_base_scores(self):
        """
        Calculate learned base scores from the FP database.

        This analyzes historical vulnerability data to learn appropriate base confidence scores
        for each evidence strength level (critical, high, medium, low) based on the actual
        confidence values of findings that were NOT marked as false positives.

        The learned scores reflect the actual signal strength observed in practice, rather
        than using fixed hardcoded values.

        Returns:
            dict: Base scores for each evidence strength level
                  {
                      'critical': float,
                      'high': float,
                      'medium': float,
                      'low': float
                  }
        """
        default_scores = {
            'critical': 95,
            'high': 85,
            'medium': 70,
            'low': 50
        }

        try:
            # Query false positives to understand which confidence levels are unreliable
            self.c.execute("SELECT confidence FROM false_positives WHERE confidence > 0")
            fp_confidences = [row[0] for row in self.c.fetchall()]

            if not fp_confidences:
                # No FP data yet, use defaults
                return default_scores

            # Calculate confidence score adjustments based on FP distribution
            # If a particular confidence range has many FPs, reduce base scores in that range
            fp_avg = sum(fp_confidences) / len(fp_confidences)

            # Calculate learned scores by adjusting defaults based on FP patterns
            # High FP rate at certain confidence levels indicates those levels are overconfident
            learned_scores = {}

            for strength, default in default_scores.items():
                # For each strength level, check if it aligns with FP-heavy confidence ranges
                # Adjust downward if this confidence range has many FPs
                if fp_avg > default - 10 and fp_avg < default + 10:
                    # This confidence range has FPs, reduce base score
                    learned_scores[strength] = max(30, default - 15)
                elif fp_avg > default:
                    # FPs are generally higher confidence, reduce more aggressively
                    learned_scores[strength] = max(30, default - 20)
                else:
                    # FPs are lower confidence, keep or slightly increase
                    learned_scores[strength] = min(95, default + 5)

            logging.info(f"Learned base scores from FP database: {learned_scores} (FP avg confidence: {fp_avg:.1f})")
            return learned_scores

        except Exception as e:
            logging.error(f"Error calculating learned base scores: {e}, using defaults")
            return default_scores

    async def close(self):
        async with self.lock:
            self._flush_batch()
            if self.conn:
                self.conn.close()
    
    def __enter__(self):
        """Context manager entry - return self for use with 'with' statement."""
        return self
    
    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit - ensure connection is closed even on exceptions."""
        try:
            if self.conn:
                self.conn.close()
        except Exception as e:
            logging.error(f"Error closing FP_Database in context manager: {e}")
        return False

class ProxyConfig:
    """Configuration for a single proxy with metadata"""
    def __init__(self, proxy_url, proxy_type="http", username=None, password=None, 
                    country=None, region=None, is_residential=False, health_check_url=None, target_url=None):
        self.proxy_url = proxy_url
        self.proxy_type = proxy_type.lower()  # http, https, socks5, socks4
        self.username = username
        self.password = password
        self.country = country  # ISO country code (e.g., 'US', 'GB', 'DE')
        self.region = region  # e.g., 'us-east', 'eu-west'
        self.is_residential = is_residential
        # Use target URL for health check if provided, otherwise fallback to external service
        if health_check_url:
            self.health_check_url = health_check_url
        elif target_url:
            self.health_check_url = target_url
        else:
            self.health_check_url = "https://api.ipify.org"
        
        # Performance metrics
        self.success_count = 0
        self.failure_count = 0
        self.avg_response_time = 0.0
        self.last_used = None
        self.last_health_check = None
        self.is_healthy = True
        
        # Rolling window for recent request tracking (last 20 requests)
        self.recent_requests = []  # List of booleans: True=success, False=failure
        self.recent_window_size = 20
        
    def get_success_rate(self):
        total = self.success_count + self.failure_count
        return self.success_count / total if total > 0 else 1.0
        
    def record_success(self, response_time):
        self.success_count += 1
        self.last_used = datetime.now()
        # Update rolling average response time
        if self.avg_response_time == 0:
            self.avg_response_time = response_time
        else:
            self.avg_response_time = (self.avg_response_time * 0.9) + (response_time * 0.1)
        # Update rolling window
        self.recent_requests.append(True)
        if len(self.recent_requests) > self.recent_window_size:
            self.recent_requests.pop(0)
            
    def record_failure(self):
        self.failure_count += 1
        self.last_used = datetime.now()
        # Update rolling window
        self.recent_requests.append(False)
        if len(self.recent_requests) > self.recent_window_size:
            self.recent_requests.pop(0)
    
    def get_recent_failure_rate(self):
        """Calculate failure rate in the recent window (last 20 requests)"""
        if not self.recent_requests:
            return 0.0
        failures = sum(1 for req in self.recent_requests if not req)
        return failures / len(self.recent_requests)
        
    def get_aiohttp_proxy(self):
        """Return proxy URL formatted for aiohttp"""
        if self.username and self.password:
            return f"{self.proxy_type}://{self.username}:{self.password}@{self.proxy_url}"
        return f"{self.proxy_type}://{self.proxy_url}"
    
    def get_selenium_proxy_dict(self):
        """
        Return proxy configuration dict for Selenium Proxy object.
        Handles both SOCKS and HTTP/HTTPS proxies with proper credential handling.
        Returns a dict for ALL proxy types for consistent handling.

        Note: HTTP/HTTPS proxy credentials must be embedded in the URL because
        Selenium Proxy API only provides separate auth fields for SOCKS proxies.
        Chrome will log these credentials. For production use, consider:
        - Using SOCKS5 proxies (credentials in separate fields, not logged)
        - IP whitelisting with the proxy provider (no credentials needed)
        - Using selenium-wire library to handle HTTP proxy authentication
        """
        from selenium.webdriver.common.proxy import ProxyType

        proxy_dict = {
            'proxyType': ProxyType.MANUAL
        }

        if self.proxy_type.startswith('socks'):
            # SOCKS proxies use separate credential fields (not logged by Chrome)
            socks_proxy_host = f"{self.proxy_type}://{self.proxy_url}"
            proxy_dict.update({
                'httpProxy': socks_proxy_host,
                'sslProxy': socks_proxy_host,
                'ftpProxy': socks_proxy_host,
                'socksProxy': socks_proxy_host,
                'socksVersion': 5 if self.proxy_type == 'socks5' else 4
            })

            # Add credentials if present (stored in separate fields, not in URL)
            if self.username and self.password:
                proxy_dict['socksUsername'] = self.username
                proxy_dict['socksPassword'] = self.password
        else:
            # HTTP/HTTPS proxies - credentials must be in URL (will be logged by Chrome)
            # Selenium Proxy API does not provide separate auth fields for HTTP/HTTPS
            if self.username and self.password:
                proxy_url = f"{self.proxy_type}://{self.username}:{self.password}@{self.proxy_url}"
            else:
                proxy_url = f"{self.proxy_type}://{self.proxy_url}"

            proxy_dict.update({
                'httpProxy': proxy_url,
                'sslProxy': proxy_url,
                'ftpProxy': proxy_url
            })

        return proxy_dict

class ProxyPool:
    """Advanced proxy pool with health checking, rotation, and geo-diverse selection"""
    def __init__(self, proxy_configs=None, enable_rotation=True, rotation_interval=100,
                    health_check_interval=300, prefer_geo_diverse=True, max_failure_rate=0.5, target_url=None, state_file=None, verify_ssl=True):
        self.proxy_configs: Dict[str, ProxyConfig] = {}
        self.enable_rotation = enable_rotation
        self.rotation_interval = rotation_interval  # requests per rotation
        self.rotation_counter = 0
        self.health_check_interval = health_check_interval  # seconds
        self.prefer_geo_diverse = prefer_geo_diverse
        self.max_failure_rate = max_failure_rate
        self.original_max_failure_rate = max_failure_rate  # Store original for auto-healing
        self.lock = threading.Lock()
        self.current_proxy_key = None
        self.last_rotation = datetime.now()
        self.target_url = target_url  # Store target URL for health checks
        self.state_file = state_file or "proxy_pool_state.json"  # State file for persistence
        self.verify_ssl = verify_ssl  # SSL verification for health checks
        
        # Auto-healing configuration
        self.auto_healing_enabled = True
        self.failure_tracking_window = 60  # seconds
        self.failure_threshold = 0.8  # 80% failure rate triggers auto-healing
        self.failure_history = []  # Track recent failures for auto-healing
        self.last_auto_heal_time = None
        self.auto_heal_cooldown = 300  # 5 minutes between auto-heals
        
        # Sticky session configuration
        self.sticky_session_enabled = False
        self.sticky_session_proxy_key = None
        self.sticky_session_start_time = None
        self.sticky_session_duration = 600  # 10 minutes default sticky session
        
        # Cookie storage per (session_id, proxy_key) for sticky sessions
        self.proxy_cookies: Dict[str, Dict[str, str]] = {}  # {session_id: {proxy_key: cookie_dict}}
        
        # Initialize with provided configs
        if proxy_configs:
            for config in proxy_configs:
                self.add_proxy(config)
                
        # Start health check background task
        self._health_check_running = False
        
        # Load persisted state
        self._load_state()
        
    def add_proxy(self, proxy_config: ProxyConfig):
        """Add a proxy configuration to the pool"""
        with self.lock:
            # If proxy config doesn't have a health_check_url set, use the pool's target_url
            if not proxy_config.health_check_url or proxy_config.health_check_url == "https://api.ipify.org":
                if self.target_url:
                    proxy_config.health_check_url = self.target_url
            key = self._make_proxy_key(proxy_config)
            self.proxy_configs[key] = proxy_config
            logging.info(f"Added proxy to pool: {mask_url(proxy_config.get_aiohttp_proxy())} ({proxy_config.proxy_type})")
    
    def set_target_url(self, target_url):
        """Set or update the target URL for health checks on all proxies"""
        with self.lock:
            self.target_url = target_url
            for config in self.proxy_configs.values():
                if not config.health_check_url or config.health_check_url == "https://api.ipify.org":
                    config.health_check_url = target_url
            logging.info(f"Updated target URL for proxy pool health checks: {target_url}")
            
    def add_proxy_url(self, proxy_url, proxy_type="http", username=None, password=None,
                        country=None, region=None, is_residential=False, target_url=None):
        """Convenience method to add a proxy by URL string"""
        # Use ProxyPool's target_url if no specific target_url provided for this proxy
        if target_url is None:
            target_url = self.target_url
        config = ProxyConfig(
            proxy_url=proxy_url,
            proxy_type=proxy_type,
            username=username,
            password=password,
            country=country,
            region=region,
            is_residential=is_residential,
            target_url=target_url
        )
        self.add_proxy(config)
        
    def add_proxy_list(self, proxy_list, proxy_type="http"):
        """Add multiple proxies from a list of URLs"""
        for proxy_url in proxy_list:
            self.add_proxy_url(proxy_url, proxy_type)
    
    def _load_state(self):
        """Load proxy pool state from disk for resume capability."""
        try:
            import os
            if os.path.exists(self.state_file):
                with open(self.state_file, 'r') as f:
                    import json
                    state = json.load(f)
                    self.rotation_counter = state.get('rotation_counter', 0)
                    last_rotation_str = state.get('last_rotation')
                    if last_rotation_str:
                        self.last_rotation = datetime.fromisoformat(last_rotation_str)
                    logging.info(f"Proxy pool state loaded: rotation_counter={self.rotation_counter}, last_rotation={self.last_rotation}")
        except Exception as e:
            logging.error(f"Failed to load proxy pool state: {e}")
    
    def _save_state(self):
        """Save proxy pool state to disk for resume capability."""
        try:
            import json
            state = {
                'rotation_counter': self.rotation_counter,
                'last_rotation': self.last_rotation.isoformat() if self.last_rotation else None
            }
            with open(self.state_file, 'w') as f:
                json.dump(state, f, indent=2)
        except Exception as e:
            logging.error(f"Failed to save proxy pool state: {e}")
            
    def _make_proxy_key(self, proxy_config: ProxyConfig) -> str:
        """Create a unique key for a proxy configuration"""
        return f"{proxy_config.proxy_type}://{proxy_config.proxy_url}"
        
    def get_next_proxy(self, preferred_country=None, preferred_type=None) -> Optional[ProxyConfig]:
        """Get the next proxy based on rotation strategy and preferences"""
        with self.lock:
            if not self.proxy_configs:
                return None
            
            # Check sticky session first
            if self.sticky_session_enabled and not self._check_sticky_session_expiry():
                if self.sticky_session_proxy_key and self.sticky_session_proxy_key in self.proxy_configs:
                    sticky_proxy = self.proxy_configs[self.sticky_session_proxy_key]
                    if sticky_proxy.is_healthy:
                        logging.error(f"Using sticky session proxy: {mask_url(sticky_proxy.get_aiohttp_proxy())}")
                        return sticky_proxy
            
            # Filter healthy proxies
            healthy_proxies = {
                k: v for k, v in self.proxy_configs.items() 
                if v.is_healthy and v.get_success_rate() >= self.max_failure_rate
            }
            
            # Exclude proxies with > 50% recent failures (rolling window)
            recent_failure_threshold = 0.5
            before_recent_filter = len(healthy_proxies)
            healthy_proxies = {
                k: v for k, v in healthy_proxies.items()
                if v.get_recent_failure_rate() <= recent_failure_threshold
            }
            after_recent_filter = len(healthy_proxies)
            if before_recent_filter > after_recent_filter:
                logging.error(f"Excluded {before_recent_filter - after_recent_filter} proxies with >50% recent failures")
            
            if not healthy_proxies:
                logging.error("No healthy proxies available, using all proxies")
                healthy_proxies = self.proxy_configs
                
            # Apply filters
            candidates = list(healthy_proxies.values())
            
            if preferred_country:
                country_candidates = [p for p in candidates if p.country == preferred_country]
                if country_candidates:
                    candidates = country_candidates
                    
            if preferred_type:
                type_candidates = [p for p in candidates if p.proxy_type == preferred_type.lower()]
                if type_candidates:
                    candidates = type_candidates
                    
            if not candidates:
                return None
                
            # Selection strategy
            if self.prefer_geo_diverse and len(candidates) > 1:
                # Prefer proxy from different country than last used
                if self.current_proxy_key and self.current_proxy_key in self.proxy_configs:
                    last_country = self.proxy_configs[self.current_proxy_key].country
                    diverse_candidates = [p for p in candidates if p.country != last_country]
                    if diverse_candidates:
                        candidates = diverse_candidates
                        
            # Select based on performance (lowest response time with good success rate)
            candidates.sort(key=lambda p: (p.avg_response_time if p.avg_response_time > 0 else float('inf'), -p.get_success_rate()))
            
            # Apply rotation - ensure thread-safe counter increment
            if self.enable_rotation:
                self.rotation_counter += 1
                if self.rotation_counter >= self.rotation_interval:
                    self.rotation_counter = 0
                    self.last_rotation = datetime.now()
                    # Rotate to next best candidate
                    if len(candidates) > 1:
                        candidates = candidates[1:] + [candidates[0]]
                # Save state after counter update
                self._save_state()
            
            selected = candidates[0]
            self.current_proxy_key = self._make_proxy_key(selected)
            
            # Set sticky session if enabled
            if self.sticky_session_enabled:
                self.sticky_session_proxy_key = self.current_proxy_key
                self.sticky_session_start_time = time.time()
                logging.info(f"Sticky session started with proxy: {mask_url(selected.get_aiohttp_proxy())}")
            
            return selected
            
    def mark_success(self, proxy_config: ProxyConfig, response_time: float):
        """Record a successful request through a proxy"""
        with self.lock:
            proxy_config.record_success(response_time)
            proxy_config.is_healthy = True
            
    def mark_failure(self, proxy_config: ProxyConfig):
        """Record a failed request through a proxy"""
        with self.lock:
            proxy_config.record_failure()
            # Mark as unhealthy if failure rate is too high
            if proxy_config.get_success_rate() < self.max_failure_rate:
                proxy_config.is_healthy = False
                logging.error(f"Proxy marked as unhealthy: {mask_url(proxy_config.get_aiohttp_proxy())} (success rate: {proxy_config.get_success_rate():.2%})")
            
            # Track failure for auto-healing
            self._track_failure()
            
            # Trigger auto-healing if needed
            if self.auto_healing_enabled:
                self._check_and_trigger_auto_heal()
                
    def reset_proxy_status(self, proxy_key=None):
        """Reset failure status for a proxy or all proxies"""
        with self.lock:
            if proxy_key:
                if proxy_key in self.proxy_configs:
                    self.proxy_configs[proxy_key].failure_count = 0
                    self.proxy_configs[proxy_key].is_healthy = True
                    self.proxy_configs[proxy_key].recent_requests = []
            else:
                for config in self.proxy_configs.values():
                    config.failure_count = 0
                    config.is_healthy = True
                    config.recent_requests = []
                    
    async def health_check(self, proxy_config: ProxyConfig, timeout=DEFAULT_REQUEST_TIMEOUT) -> bool:
        """Check if a proxy is working by making a test request"""
        try:
            import aiohttp
            proxy_url = proxy_config.get_aiohttp_proxy()
        except Exception as e:
            logging.error(f"Error: {e}")

            async with aiohttp.ClientSession() as session:
                start = time.time()
                ssl_context = create_ssl_context(verify=not DISABLE_SSL_VERIFICATION or not self.verify_ssl)
                async with session.get(
                    proxy_config.health_check_url,
                    proxy=proxy_url,
                    timeout=ClientTimeout(total=10, connect=5, sock_read=5),
                    ssl=ssl_context
                ) as response:
                    response_time = time.time() - start
                    if response.status == 200:
                        proxy_config.record_success(response_time)
                        proxy_config.last_health_check = datetime.now()
                        proxy_config.is_healthy = True
                        return True
                    else:
                        proxy_config.record_failure()
                        proxy_config.is_healthy = False
                        return False
        except Exception as e:
            proxy_config.record_failure()
            proxy_config.is_healthy = False
            logging.error(f"Health check failed for {mask_url(proxy_config.get_aiohttp_proxy())}: {e}")
            return False
            
    async def run_health_checks(self):
        """Run health checks on all proxies with concurrency limit"""
        import aiohttp
        semaphore = asyncio.Semaphore(20)  # Limit to 20 concurrent health checks
        
        async def health_check_with_semaphore(config):
            async with semaphore:
                return await self.health_check(config)
        
        tasks = []
        for config in self.proxy_configs.values():
            tasks.append(health_check_with_semaphore(config))
        
        if tasks:
            results = await asyncio.gather(*tasks, return_exceptions=True)
            healthy_count = sum(1 for r in results if r is True)
            logging.info(f"Health check complete: {healthy_count}/{len(results)} proxies healthy")
            
    def get_proxy_stats(self) -> Dict:
        """Get statistics about the proxy pool"""
        with self.lock:
            stats = {
                "total_proxies": len(self.proxy_configs),
                "healthy_proxies": sum(1 for p in self.proxy_configs.values() if p.is_healthy),
                "countries": {},
                "types": {},
                "residential_count": sum(1 for p in self.proxy_configs.values() if p.is_residential)
            }
            
            for config in self.proxy_configs.values():
                # Country stats
                if config.country:
                    stats["countries"][config.country] = stats["countries"].get(config.country, 0) + 1
                # Type stats
                stats["types"][config.proxy_type] = stats["types"].get(config.proxy_type, 0) + 1
                
            return stats
            
    def get_proxies_by_country(self, country: str) -> List[ProxyConfig]:
        """Get all proxies from a specific country"""
        with self.lock:
            return [p for p in self.proxy_configs.values() if p.country == country]
        
    def get_proxies_by_type(self, proxy_type: str) -> List[ProxyConfig]:
        """Get all proxies of a specific type"""
        with self.lock:
            return [p for p in self.proxy_configs.values() if p.proxy_type == proxy_type.lower()]
    
    def _track_failure(self):
        """Track failure for auto-healing logic"""
        current_time = time.time()
        self.failure_history.append(current_time)
        
        # Clean up old failures outside the tracking window
        self.failure_history = [
            t for t in self.failure_history 
            if current_time - t <= self.failure_tracking_window
        ]
    
    def _check_and_trigger_auto_heal(self):
        """Check if auto-healing should be triggered based on failure rate"""
        current_time = time.time()
        
        # Check cooldown
        if self.last_auto_heal_time and (current_time - self.last_auto_heal_time) < self.auto_heal_cooldown:
            return
        
        # Calculate failure rate in the tracking window
        if len(self.failure_history) < 10:  # Need minimum sample size
            return
        
        # Calculate approximate failure rate based on proxy health
        total_proxies = len(self.proxy_configs)
        if total_proxies == 0:
            return
        
        healthy_proxies = sum(1 for p in self.proxy_configs.values() if p.is_healthy)
        failure_rate = 1.0 - (healthy_proxies / total_proxies)
        
        # Trigger auto-healing if failure rate exceeds threshold
        if failure_rate >= self.failure_threshold:
            logging.error(f"Auto-healing triggered: {failure_rate:.1%} proxy failure rate detected")
            self._perform_auto_heal()
            self.last_auto_heal_time = current_time
    
    def _perform_auto_heal(self):
        """Perform auto-healing by dynamically adjusting max_failure_rate"""
        old_threshold = self.max_failure_rate
        # Increase threshold by 20% to allow more proxies to be considered healthy
        self.max_failure_rate = min(0.95, self.max_failure_rate + 0.2)
        
        # Reset all proxy health status
        for config in self.proxy_configs.values():
            config.is_healthy = True
            config.failure_count = 0
        
        logging.info(f"Auto-healing complete: max_failure_rate increased from {old_threshold:.2%} to {self.max_failure_rate:.2%}")
        logging.info(f"All proxy health status reset to allow recovery")
    
    def enable_sticky_session(self, duration_seconds=600):
        """Enable sticky session to maintain same proxy for multi-step operations"""
        with self.lock:
            self.sticky_session_enabled = True
            self.sticky_session_duration = duration_seconds
            logging.info(f"Sticky session enabled for {duration_seconds} seconds")
    
    def disable_sticky_session(self):
        """Disable sticky session and allow normal proxy rotation"""
        with self.lock:
            self.sticky_session_enabled = False
            self.sticky_session_proxy_key = None
            self.sticky_session_start_time = None
            # Clear all stored cookies when sticky session is disabled
            self.proxy_cookies.clear()
            logging.info("Sticky session disabled and cookies cleared")
    
    def _check_sticky_session_expiry(self):
        """Check if sticky session has expired"""
        if not self.sticky_session_enabled or not self.sticky_session_start_time:
            return True
        
        current_time = time.time()
        if current_time - self.sticky_session_start_time > self.sticky_session_duration:
            logging.info("Sticky session expired, allowing proxy rotation")
            # Clear cookies for the expired proxy across all sessions
            if self.sticky_session_proxy_key:
                self.clear_proxy_cookies(self.sticky_session_proxy_key)
            self.sticky_session_proxy_key = None
            self.sticky_session_start_time = None
            return True
        
        return False
    
    def store_cookies(self, session_id: str, proxy_key: str, cookies: Dict[str, str]):
        """Store cookies for a specific session and proxy combination"""
        with self.lock:
            if session_id not in self.proxy_cookies:
                self.proxy_cookies[session_id] = {}
            self.proxy_cookies[session_id][proxy_key] = cookies.copy()
            logging.debug(f"Stored cookies for session {session_id} and proxy {proxy_key}")
    
    def get_cookies(self, session_id: str, proxy_key: str) -> Optional[Dict[str, str]]:
        """Retrieve cookies for a specific session and proxy combination"""
        with self.lock:
            if session_id in self.proxy_cookies and proxy_key in self.proxy_cookies[session_id]:
                return self.proxy_cookies[session_id][proxy_key].copy()
            return None
    
    def clear_session_cookies(self, session_id: str):
        """Clear all cookies for a specific session"""
        with self.lock:
            if session_id in self.proxy_cookies:
                del self.proxy_cookies[session_id]
                logging.debug(f"Cleared cookies for session {session_id}")
    
    def clear_proxy_cookies(self, proxy_key: str):
        """Clear cookies for a specific proxy across all sessions"""
        with self.lock:
            for session_id in list(self.proxy_cookies.keys()):
                if proxy_key in self.proxy_cookies[session_id]:
                    del self.proxy_cookies[session_id][proxy_key]
                if not self.proxy_cookies[session_id]:
                    del self.proxy_cookies[session_id]
            logging.debug(f"Cleared cookies for proxy {proxy_key}")

# Legacy ProxyRotator for backward compatibility
class ProxyRotator:
    def __init__(self, proxy_list=None):
        self.proxy_pool = ProxyPool()
        if proxy_list:
            self.proxy_pool.add_proxy_list(proxy_list)
            
    def add_proxy(self, proxy_url):
        self.proxy_pool.add_proxy_url(proxy_url)
        
    def get_next_proxy(self):
        config = self.proxy_pool.get_next_proxy()
        return config.get_aiohttp_proxy() if config else None
        
    def mark_failed(self, proxy_url):
        # Find the config and mark as failed
        for key, config in self.proxy_pool.proxy_configs.items():
            if proxy_url in config.proxy_url or config.get_aiohttp_proxy() == proxy_url:
                self.proxy_pool.mark_failure(config)
                break
                
    def reset_failed(self):
        self.proxy_pool.reset_proxy_status()

class ScanStateManager:
    def __init__(self, db_path="scan_state.db", html_cache_dir="html_cache"):
        self.db_path = db_path
        self.html_cache_dir = html_cache_dir
        os.makedirs(self.html_cache_dir, exist_ok=True)

        # Initialize database using context manager
        with sqlite3.connect(db_path, check_same_thread=False) as conn:
            cursor = conn.cursor()
            self._init_tables_sync(cursor)
            conn.commit()

        # Keep connection open for long-lived operations
        # Wrap in try/finally to ensure connection is closed on error
        try:
            self.conn = sqlite3.connect(db_path, check_same_thread=False)
            self.c = self.conn.cursor()
        except Exception:
            # If connection creation or cursor setup fails, ensure cleanup
            if hasattr(self, 'conn') and self.conn:
                self.conn.close()
            raise

        self.lock = threading.Lock()
        self.pending_page_inserts = []
        self.batch_size = 100
    
    def _init_tables_sync(self, cursor):
        """Synchronous table initialization for use with context manager"""
        cursor.execute('''CREATE TABLE IF NOT EXISTS scan_state
                (id INTEGER PRIMARY KEY, target TEXT, timestamp TEXT, 
                visited_urls TEXT, parameters TEXT, vulnerabilities TEXT,
                crawled_pages TEXT, config TEXT, fsm_state TEXT)''')
        cursor.execute('''CREATE TABLE IF NOT EXISTS page_hashes
                (url TEXT PRIMARY KEY, content_hash TEXT, metadata TEXT, html_path TEXT, timestamp TEXT)''')
        # Migration: add html_path column if it doesn't exist
        try:
            cursor.execute("SELECT html_path FROM page_hashes LIMIT 1")
        except sqlite3.OperationalError:
            # Column doesn't exist, add it
            cursor.execute("ALTER TABLE page_hashes ADD COLUMN html_path TEXT")
        # Migration: add fsm_state column if it doesn't exist
        try:
            cursor.execute("SELECT fsm_state FROM scan_state LIMIT 1")
        except sqlite3.OperationalError:
            # Column doesn't exist, add it (if table exists)
            try:
                cursor.execute("ALTER TABLE scan_state ADD COLUMN fsm_state TEXT")
            except sqlite3.OperationalError:
                # Table might not exist yet, will be created with the column
                pass
        # Migration: if old html_content column exists, migrate to html_path
        try:
            cursor.execute("SELECT html_content FROM page_hashes LIMIT 1")
            # Column exists, migrate existing data
            cursor.execute("SELECT url, html_content FROM page_hashes WHERE html_content IS NOT NULL AND html_content != ''")
            rows = cursor.fetchall()
            for url, html_content in rows:
                if html_content:
                    html_path = self._save_html_to_disk(url, html_content)
                    cursor.execute("UPDATE page_hashes SET html_path = ?, html_content = NULL WHERE url = ?", (html_path, url))
            # Remove old column
            cursor.execute("ALTER TABLE page_hashes DROP COLUMN html_content")
        except sqlite3.OperationalError:
            # Column doesn't exist, already migrated
            pass
    def _init_tables(self):
        """Initialize tables using the instance connection (called during migration only)"""
        self._init_tables_sync(self.c)
        self.conn.commit()
    
    def _save_html_to_disk(self, url, html_content):
        """Save HTML content to disk and return the file path (synchronous, should be called from executor)"""
        html_filename = hashlib.md5(url.encode()).hexdigest() + ".html"
        html_path = os.path.join(self.html_cache_dir, html_filename)
        with open(html_path, 'w', encoding='utf-8') as f:
            f.write(html_content)
        return html_path
    
    def _load_html_from_disk(self, html_path):
        """Load HTML content from disk"""
        try:
            with open(html_path, 'r', encoding='utf-8') as f:
                return f.read()
        except (FileNotFoundError, IOError):
            return None
    def save_state(self, target, visited_urls, parameters, vulnerabilities, crawled_pages, config, fsm_state=None):
        with self.lock:
            timestamp = datetime.now().isoformat()
            # Store only metadata (URL and hash) instead of full HTML
            crawled_pages_metadata = []
            for p in crawled_pages:
                page_meta = {'url': p['url']}
                if 'hash' in p:
                    page_meta['hash'] = p['hash']
                elif 'html_path' in p:
                    # Generate hash from file path if needed
                    page_meta['hash'] = hashlib.md5(p['html_path'].encode()).hexdigest()
                crawled_pages_metadata.append(page_meta)
            
            fsm_state_json = json.dumps(fsm_state) if fsm_state else None
            self.c.execute("INSERT OR REPLACE INTO scan_state (id, target, timestamp, visited_urls, parameters, vulnerabilities, crawled_pages, config, fsm_state) VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?)",
                            (target, json.dumps(list(visited_urls)), json.dumps(parameters), json.dumps(vulnerabilities), json.dumps(crawled_pages_metadata), json.dumps(config), fsm_state_json))
            self.conn.commit()
    def load_state(self):
        with self.lock:
            # Try to load with fsm_state column first
            try:
                self.c.execute("SELECT target, visited_urls, parameters, vulnerabilities, crawled_pages, config, fsm_state FROM scan_state WHERE id=1")
                row = self.c.fetchone()
            except sqlite3.OperationalError:
                # Fallback for older databases without fsm_state column
                self.c.execute("SELECT target, visited_urls, parameters, vulnerabilities, crawled_pages, config FROM scan_state WHERE id=1")
                row = self.c.fetchone()
                if row:
                    row = list(row) + [None]  # Add None for fsm_state
            
            if row:
                try:
                    parameters = safe_json_loads(row[2], max_depth=100) if row[2] else []
                except json.JSONDecodeError:
                    parameters = []
                try:
                    vulnerabilities = safe_json_loads(row[3], max_depth=100) if row[3] else []
                except json.JSONDecodeError:
                    vulnerabilities = []
                try:
                    visited_urls = set(safe_json_loads(row[1], max_depth=100)) if row[1] else set()
                except json.JSONDecodeError:
                    visited_urls = set()
                try:
                    crawled_pages = safe_json_loads(row[4], max_depth=100) if row[4] else []
                except json.JSONDecodeError:
                    crawled_pages = []
                try:
                    config = safe_json_loads(row[5], max_depth=100) if row[5] else {}
                except json.JSONDecodeError:
                    config = {}
                try:
                    fsm_state = safe_json_loads(row[6], max_depth=100) if row[6] else None
                except (json.JSONDecodeError, IndexError):
                    fsm_state = None
                return {
                    'target': row[0],
                    'visited_urls': visited_urls,
                    'parameters': parameters if isinstance(parameters, list) else [],
                    'vulnerabilities': vulnerabilities if isinstance(vulnerabilities, list) else [],
                    'crawled_pages': crawled_pages,
                    'config': config,
                    'fsm_state': fsm_state
                }
            return None
    def store_page_hash(self, url, content, metadata):
        with self.lock:
            content_hash = hashlib.sha256(content.encode()).hexdigest()
            html_path = self._save_html_to_disk(url, content)
            self.pending_page_inserts.append((url, content_hash, json.dumps(metadata), html_path, datetime.now().isoformat()))
            if len(self.pending_page_inserts) >= self.batch_size:
                self._flush_page_batch()
    def _flush_page_batch(self):
        if self.pending_page_inserts:
            self.c.executemany("INSERT OR REPLACE INTO page_hashes (url, content_hash, metadata, html_path, timestamp) VALUES (?, ?, ?, ?, ?)", self.pending_page_inserts)
            self.conn.commit()
            self.pending_page_inserts.clear()
    def get_page_hash(self, url):
        with self.lock:
            self._flush_page_batch()
            self.c.execute("SELECT content_hash, metadata, html_path FROM page_hashes WHERE url=?", (url,))
            row = self.c.fetchone()
            if row:
                try:
                    metadata = safe_json_loads(row[1], max_depth=100)
                except json.JSONDecodeError:
                    metadata = {}
                html_content = self._load_html_from_disk(row[2]) if row[2] else None
                return {'hash': row[0], 'metadata': metadata, 'html_content': html_content, 'html_path': row[2]}
            return None
    
    def get_html_content(self, url):
        """Get HTML content for a specific URL, loading from disk if needed"""
        with self.lock:
            self._flush_page_batch()
            self.c.execute("SELECT html_path FROM page_hashes WHERE url=?", (url,))
            row = self.c.fetchone()
            if row and row[0]:
                return self._load_html_from_disk(row[0])
            return None
    def clear_state(self):
        with self.lock:
            self.c.execute("DELETE FROM scan_state")
            self.c.execute("DELETE FROM page_hashes")
            self.conn.commit()
            # Clean up HTML cache directory
            try:
                import shutil
                if os.path.exists(self.html_cache_dir):
                    shutil.rmtree(self.html_cache_dir)
                    os.makedirs(self.html_cache_dir, exist_ok=True)
            except Exception as e:
                logging.error(f"Error clearing HTML cache directory: {e}")
    
    def find_most_recent_checkpoint(self):
        """Find the most recent checkpoint file in the current directory"""
        import glob
        checkpoint_files = glob.glob("checkpoint_*.json")
        if not checkpoint_files:
            return None
        
        # Filter and validate checkpoint files
        valid_files = []
        for filename in checkpoint_files:
            if self._validate_checkpoint_filename(filename):
                valid_files.append(filename)
            else:
                logging.error(f"Skipping invalid checkpoint file: {filename}")
        
        if not valid_files:
            return None
        
        # Sort by timestamp (extracted from filename)
        valid_files.sort(key=lambda x: int(x.split('_')[1].split('.')[0]), reverse=True)
        return valid_files[0] if valid_files else None
    
    def _validate_checkpoint_filename(self, filename):
        """Validate checkpoint filename to prevent path traversal attacks"""
        return validate_checkpoint_filename(filename)
    
    def load_checkpoint_file(self, checkpoint_file):
        """Load checkpoint from a specific file with filename validation"""
        # Validate filename before opening
        if not self._validate_checkpoint_filename(checkpoint_file):
            logging.error(f"Security: Rejecting unsafe checkpoint filename: {checkpoint_file}")
            return None
        
        try:
            with open(checkpoint_file, 'r') as f:
                checkpoint = json.load(f)
            return checkpoint
        except Exception as e:
            logging.error(f"Failed to load checkpoint from {checkpoint_file}: {e}")
            return None
    
    def close(self):
        """Close the database connection to prevent resource leaks."""
        try:
            if self.c:
                try:
                    self.c.close()
                except Exception as cursor_error:
                    logging.error(f"Error closing cursor: {cursor_error}")
                self.c = None
            if self.conn:
                try:
                    self.conn.close()
                except Exception as conn_error:
                    logging.error(f"Error closing connection: {conn_error}")
                self.conn = None
        except Exception as e:
            logging.error(f"Error closing ScanStateManager: {e}")
    
    def __enter__(self):
        """Context manager entry - return self for use with 'with' statement."""
        return self
    
    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit - ensure connection is closed even on exceptions."""
        self.close()
        return False

class MITMProxyHandler:
    def __init__(self, port=8080, callback=None):
        self.port = port
        self.callback = callback
        self.server = None
        self.thread = None
        self.captured_requests = []
        self.lock = threading.Lock()
    def start(self):
        try:
            # Use ThreadingHTTPServer for concurrent request handling
            self.server = ThreadingHTTPServer(('0.0.0.0', self.port), self._create_handler())
            self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
            self.thread.start()
            return True
        except Exception as e:
            logging.error(f"MITM proxy start error: {e}")
            return False
    def _create_handler(self):
        class ProxyHandler(BaseHTTPRequestHandler):
            def __init__(self, *args, **kwargs):
                self.parent = self
                BaseHTTPRequestHandler.__init__(self, *args, **kwargs)
            def do_GET(self):
                self._handle_request('GET')
            def do_POST(self):
                self._handle_request('POST')
            def do_PUT(self):
                self._handle_request('PUT')
            def do_DELETE(self):
                self._handle_request('DELETE')
            def _handle_request(self, method):
                try:
                    content_length = int(self.headers.get('Content-Length', 0))
                    body = self.rfile.read(content_length) if content_length > 0 else None
                    captured = {
                        'method': method,
                        'url': self.path,
                        'headers': dict(self.headers),
                        'body': body.decode('utf-8', errors='ignore') if body else None
                    }
                    # Store only metadata to prevent memory leaks
                    captured_body_snippet = captured['body'][:500] if captured['body'] else ''
                    captured['body_snippet'] = captured_body_snippet
                    del captured['body']  # Remove full body
                    with self.parent.lock:
                        self.parent.captured_requests.append(captured)
                    if self.path.startswith('http://') or self.path.startswith('https://'):
                        target_url = self.path
                    else:
                        target_url = f"http://{self.headers.get('Host', '')}{self.path}"
                    import asyncio
                    import aiohttp
                    async def forward_request():
                        async with aiohttp.ClientSession() as session:
                            async with session.request(method, target_url, headers=dict(self.headers), data=body, timeout=ClientTimeout(total=10)) as resp:
                                content = await resp.read()
                                text = await resp.text()
                                return response_status(resp), response_headers(resp), content, text
                    loop = get_loop()
                    try:
                        status_code, resp_headers, content, text = loop.run_until_complete(forward_request())
                   
                    finally:
                        loop.close()
                    self.send_response(status_code)
                    for header, value in resp_headers.items():
                        if header.lower() not in ('content-encoding', 'transfer-encoding'):
                            self.send_header(header, value)
                    self.end_headers()
                    self.wfile.write(content)
                    if self.parent.callback:
                        self.parent.callback(captured, status_code, text)
                except Exception as e:
                    logging.error(f"MITM proxy request error: {e}")
                    self.send_error(500, str(e))
            def log_message(self, format, *args):
                """Suppress default HTTP server logging to reduce noise during scanning."""
                # Intentionally empty to reduce log noise - HTTP server logging is handled elsewhere
        handler_class = ProxyHandler
        handler_class.parent = self
        return handler_class
    def stop(self):
        if self.server:
            try:
                self.server.shutdown()
                logging.info("MITM proxy server stopped")
            except Exception as e:
                logging.error(f"Error stopping MITM proxy server: {e}")
        if self.thread:
            try:
                self.thread.join(timeout=2)
            except Exception as e:
                logging.error(f"Error joining MITM proxy thread: {e}")
    def get_captured_requests(self):
        with self.lock:
            return list(self.captured_requests)
    def clear_captured(self):
        with self.lock:
            self.captured_requests.clear()

