# PLAYWRIGHT JS RENDER DRIVER - Advanced JavaScript Instrumentation
# ---------------------------------------------------------------------
class PlaywrightJSRenderDriver:
    """
    Playwright-based browser driver implementing BrowserInterface protocol.
    Provides advanced JavaScript runtime instrumentation, user interaction recording,
    and deep vulnerability detection including Prototype Pollution and CSTI.
    
    Features:
    - Deep JavaScript runtime instrumentation via page.addInitScript
    - User interaction recording and replay (30-second sessions)
    - Advanced Prototype Pollution detection with property access tracking
    - Client-Side Template Injection (CSTI) detection with template monitoring
    - Headless browser context management
    - Built-in network interception and monitoring
    - Shadow DOM piercing and SPA route discovery
    - Secret scanning integration
    
    State Management:
    - The browser context is created once in create() and reused across navigations
    - Call fresh_context() between test phases to prevent state leakage (cookies, localStorage, history)
    - Page reuse is maintained within a single test, but not across tests after fresh_context()
    """
    
    def __init__(self, proxy=None, proxy_pool=None, human_like_behavior=True, config=None, signals=None):
        self.playwright = None
        self.browser = None
        self.context = None
        self.page = None
        self.config = config or {}
        self.signals = signals  # Store signals for GUI communication

        # Proxy configuration
        self.proxy = proxy
        self.proxy_pool = proxy_pool
        self.proxy_config = None

        # Human-like behavior
        self.human_like_behavior = human_like_behavior

        # Data collection (required by BrowserInterface)
        self.captured_requests = deque(maxlen=1000)
        self.captured_responses = deque(maxlen=1000)
        self.lock = threading.Lock()
        self.spa_routes_clicked = set()
        self.discovered_routes = set()
        self.route_transitions = []
        
        # Dynamic URL discovery with sources
        self.discovered_urls = deque(maxlen=500)
        
        # Secret scanning
        self.secret_scanner = SecretScanner(self.config)
        self.discovered_secrets = []
        
        # User interaction recording
        self.recording_enabled = False
        self.recorded_actions = []
        self.recording_start_time = None
        self.max_recording_duration = 30  # 30 seconds max recording
        
        # JavaScript runtime instrumentation
        self.js_instrumentation_enabled = False
        self.prototype_pollution_detected = []
        self.csti_detected = []
        self.runtime_hooks = {}
        
        # Runtime taint tracking
        self.runtime_taint_tracker = None
        self.runtime_taint_enabled = False
        self.runtime_taint_flows = []
        
        # Shadow DOM and SPA features
        self.shadow_dom_enabled = True
        self.websocket_messages = deque(maxlen=500)
        self.websocket_monitoring_enabled = False
        
        # Route Discovery Engine (Issue T4 Fix)
        self.route_discovery_engine = RouteDiscoveryEngine(self.config)
        self.route_discovery_enabled = self.config.get('route_discovery_enabled', True)
        
        # Playwright-specific settings
        self.headless = True
        self.browser_type = 'chromium'  # chromium, firefox, webkit
        
    async def __aenter__(self):
        await self.create()
        return self
    
    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.quit()
        return False
    
    async def fresh_context(self):
        """
        Create a fresh browser context to prevent state leakage between tests.
        Closes the existing context and creates a new one with the same settings.
        This prevents cookies, localStorage, and history from persisting across tests.
        
        The page is reused within a test but not across tests after calling this method.
        """
        if not self.browser:
            logging.error("Cannot create fresh context: browser not initialized")
            return False
        
        try:
            # Close existing context and page
            if self.page:
                await self.page.close()
                self.page = None
            
            if self.context:
                await self.context.close()
                self.context = None
            
            # Create new browser context with the same settings
            context_options = {
                'viewport': {'width': 1920, 'height': 1080},
                'user_agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'locale': 'en-US',
                'timezone_id': 'America/New_York',
                'java_script_enabled': True,
                'ignore_https_errors': True,
            }
            
            self.context = await self.browser.new_context(**context_options)
            
            # Create new page
            self.page = await self.context.new_page()
            
            # Re-setup network monitoring and instrumentation
            await self._setup_network_monitoring()
            await self._enable_js_runtime_instrumentation()
            
            if self.runtime_taint_enabled:
                await self._enable_runtime_taint_tracking()
            
            if self.websocket_monitoring_enabled:
                await self._enable_websocket_monitoring()
            
            logging.info("Fresh browser context created successfully")
            return True
            
        except Exception as e:
            logging.error(f"Failed to create fresh context: {e}")
            return False
    
    def fresh_context_sync(self):
        """
        Synchronous wrapper for fresh_context method.
        This allows sync callers to create a fresh browser context.
        """
        try:
            loop = get_loop()
            result = loop.run_until_complete(self.fresh_context())
            return result
        except Exception as e:
            logging.error(f"Sync fresh_context wrapper error: {e}")
            return False
    
    async def create(self):
        """Initialize Playwright browser, context, and page"""
        if not PLAYWRIGHT_AVAILABLE:
            logging.error("Playwright not available - cannot create PlaywrightJSRenderDriver")
            return None
        
        try:
            # Start Playwright (no longer accepts loop parameter in newer versions)
            playwright_instance = async_playwright()
            self.playwright = await playwright_instance.start()
            
            # Configure proxy settings
            proxy_config = None
            proxy_key = None
            if self.proxy_pool:
                self.proxy_config = self.proxy_pool.get_next_proxy()
                if self.proxy_config:
                    proxy_key = self.proxy_pool._make_proxy_key(self.proxy_config)
                    proxy_config = {
                        'server': self.proxy_config.proxy_url,
                        'username': self.proxy_config.username,
                        'password': self.proxy_config.password
                    }
                    logging.info(f"Using proxy for Playwright: {mask_url(self.proxy_config.get_aiohttp_proxy())}")
                    
                    # Restore cookies for this (session_id, proxy_key) combination if sticky session is enabled
                    if self.proxy_pool.sticky_session_enabled and self.session_id:
                        stored_cookies = self.proxy_pool.get_cookies(self.session_id, proxy_key)
                        if stored_cookies:
                            # Store cookies to be set after context is created
                            self._pending_cookies = stored_cookies
                            logging.debug(f"Will restore {len(stored_cookies)} cookies for session {self.session_id} and proxy {proxy_key}")
            elif self.proxy:
                proxy_config = {'server': self.proxy}
            
            # Launch browser with proxy if configured
            launch_options = {
                'headless': self.headless,
                'proxy': proxy_config
            }
            
            # Remove None values from launch options
            launch_options = {k: v for k, v in launch_options.items() if v is not None}
            
            self.browser = await getattr(self.playwright, self.browser_type).launch(**launch_options)
            
            # Create browser context with advanced settings
            context_options = {
                'viewport': {'width': 1920, 'height': 1080},
                'user_agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                'locale': 'en-US',
                'timezone_id': 'America/New_York',
                'java_script_enabled': True,
                'ignore_https_errors': True,  # For testing purposes
            }
            
            self.context = await self.browser.new_context(**context_options)
            
            # Restore cookies from sticky session if available
            if hasattr(self, '_pending_cookies') and self._pending_cookies:
                try:
                    await self.context.add_cookies([{'name': name, 'value': value, 'domain': '', 'path': '/'} for name, value in self._pending_cookies.items()])
                    logging.debug(f"Restored {len(self._pending_cookies)} cookies for Playwright session")
                    delattr(self, '_pending_cookies')
                except Exception as cookie_error:
                    logging.debug(f"Failed to restore cookies for Playwright: {cookie_error}")
            
            # Store proxy_key for later cookie storage
            if proxy_key:
                self._proxy_key = proxy_key
            
            # Create page
            self.page = await self.context.new_page()
            
            # Set up network interception
            await self._setup_network_monitoring()
            
            # Enable advanced JavaScript runtime instrumentation
            await self._enable_js_runtime_instrumentation()
            
            # Enable runtime taint tracking if configured
            await self._enable_runtime_taint_tracking()
            
            # Enable WebSocket monitoring
            await self._enable_websocket_monitoring()
            
            logging.info("PlaywrightJSRenderDriver initialized successfully")
            return self
            
        except Exception as e:
            logging.error(f"Playwright driver creation error: {e}")
            if self.proxy_config and self.proxy_pool:
                self.proxy_pool.mark_failure(self.proxy_config)
            
            # Clean up any resources that were successfully created
            try:
                if self.page:
                    await self.page.close()
                    self.page = None
            except Exception as e:
                logging.debug(f"Error: {e}")
            
            try:
                if self.context:
                    await self.context.close()
                    self.context = None
            except Exception as e:
                logging.debug(f"Error: {e}")
            
            try:
                if self.browser:
                    await self.browser.close()
                    self.browser = None
            except Exception as e:
                logging.debug(f"Error: {e}")
            
            try:
                if self.playwright:
                    await self.playwright.stop()
                    self.playwright = None
            except Exception as e:
                logging.debug(f"Error: {e}")
            
            return None
    
    async def _setup_network_monitoring(self):
        """Set up network request/response monitoring"""
        if not self.page:
            return
        
        try:
            # Request monitoring
            async def handle_request(request):
                with self.lock:
                    # Store only metadata to prevent memory leaks
                    self.captured_requests.append({
                        'type': 'request',
                        'url': request.url,
                        'method': request.method,
                        'headers': dict(request.headers) if request.headers else {},
                        'post_data': request.post_data[:500] if request.post_data else None  # Limit size
                    })
                    
                    # Also add to discovered URLs with source tracking
                    if request.url and request.url.startswith(('http://', 'https://')):
                        self.discovered_urls.append({
                            'url': request.url,
                            'discovery_source': 'playwright_network_request'
                        })
                    else:
                        pass
            # Response monitoring
            async def handle_response(response):
                try:
                    body = await response.body()
                    body_str = body.decode('utf-8', errors='ignore') if body else ''
                    
                    # Scan response body for secrets
                    secrets_found = []
                    if body_str:
                        content_type = response.headers.get('content-type', '')
                        url = response.url
                        
                        if 'html' in content_type.lower():
                            secrets_found = self.secret_scanner.scan_html(body_str, url)
                        elif 'json' in content_type.lower():
                            secrets_found = self.secret_scanner.scan_json(body_str, url)
                        elif 'javascript' in content_type.lower() or 'js' in content_type.lower():
                            secrets_found = self.secret_scanner.scan_javascript(body_str, url)
                        else:
                            secrets_found = self.secret_scanner.scan_content(body_str, url)
                        
                        if secrets_found:
                            with self.lock:
                                self.discovered_secrets.extend(secrets_found)

                            # Emit secret signals to GUI for real-time display
                            if hasattr(self, 'signals') and hasattr(self.signals, 'secret'):
                                for secret in secrets_found:
                                    try:
                                        self.signals.secret.emit(secret)
                                    except Exception as e:
                                        logging.error(f"Failed to emit secret signal to GUI: {e}")

                    with self.lock:
                        parsed_params = self._extract_json_parameters(body_str) if body_str else []
                        self.captured_responses.append({
                            'type': 'response',
                            'url': response.url,
                            'status': response.status,
                            'headers': response.headers,
                            'body': body_str,
                            'parameters': parsed_params,
                            'secrets': secrets_found
                        })
                except Exception as e:
                    if isinstance(e, asyncio.CancelledError):
                        raise
                    logging.error(f"Response handling error: {e}")
            
            self.page.on('request', handle_request)
            self.page.on('response', handle_response)
            
            # Navigation event monitoring for URL discovery
            async def handle_navigation(navigation):
                with self.lock:
                    if navigation.url and navigation.url.startswith(('http://', 'https://')):
                        self.discovered_urls.append({
                            'url': navigation.url,
                            'discovery_source': 'playwright_navigation'
                        })
                        logging.debug(f"Captured navigation URL: {navigation.url}")
            
            self.page.on('framenavigated', handle_navigation)
            
            logging.info("Network monitoring enabled")
            
        except Exception as e:
            logging.error(f"Network monitoring setup error: {e}")
    
