    def get_cookies(self) -> Dict[str, str]:
        """
        Get all cookies from the browser.
        
        Returns:
            Dictionary of cookie name-value pairs
        """
        # Sync wrapper for async compatibility
        return self.get_cookies_sync()
    
    def get_cookies_sync(self) -> Dict[str, str]:
        """Synchronous wrapper for get_cookies method"""
        try:
            return run_async_safely(self._get_cookies_async())
        except Exception as e:
            logging.error(f"Sync get_cookies wrapper error: {e}")
            return {}
    
    async def _get_cookies_async(self) -> Dict[str, str]:
        """Internal async implementation of get_cookies method"""
        if not self.context:
            return {}
        
        try:
            cookies = await self.context.cookies()
            return {cookie['name']: cookie['value'] for cookie in cookies}
        except Exception as e:
            logging.error(f"Playwright get_cookies error: {e}")
            return {}
    
    def set_cookies(self, cookies: Dict[str, str]) -> None:
        """
        Set cookies in the browser.
        
        Args:
            cookies: Dictionary of cookie name-value pairs to set
        """
