    def _extract_json_parameters(self, body, prefix=''):
        """Extract parameters from JSON body"""
        params = []
        try:
            data = safe_json_loads(body, max_depth=100)
            
            # Iterative stack-based traversal to avoid recursion
            stack = [(data, prefix, 0)]  # (object, current_prefix, depth)
            max_depth = 50  # Prevent infinite loops
            
            while stack:
                obj, current_prefix, depth = stack.pop()
                
                if depth > max_depth:
                    continue
                    
                if isinstance(obj, dict):
                    for key, value in obj.items():
                        new_prefix = f"{current_prefix}.{key}" if current_prefix else key
                        if isinstance(value, (dict, list)):
                            stack.append((value, new_prefix, depth + 1))
                        else:
                            params.append(new_prefix)
                elif isinstance(obj, list):
                    for i, item in enumerate(obj):
                        new_prefix = f"{current_prefix}[{i}]"
                        if isinstance(item, (dict, list)):
                            stack.append((item, new_prefix, depth + 1))
                        else:
                            params.append(new_prefix)
        except (json.JSONDecodeError, ValueError):
            pass
        return params
    
    # Backward compatibility methods for Selenium-like interface
    @property
    def driver(self):
        """
        Compatibility property for Selenium-like driver access.
        
        Returns a wrapper object that provides synchronous access to the Playwright driver.
        This allows sync code paths like driver.driver.get(url) to work correctly.
        """
        class SyncDriverWrapper:
            def __init__(self, playwright_driver):
                self._playwright_driver = playwright_driver
            
            def get(self, url, **kwargs):
                """Synchronous get method that calls the underlying sync wrapper"""
                return self._playwright_driver.get_sync(url, **kwargs)
            
            def __getattr__(self, name):
                """Delegate other attributes to the underlying driver"""
                return getattr(self._playwright_driver, name)
        
        return SyncDriverWrapper(self)
    
    async def get_async(self, url):
        """Async version of get method for compatibility"""
        return await self._get_async(url)
    
