    def quit(self) -> None:
        """
        Clean up and close the browser driver.
        Sync wrapper for async compatibility with BrowserInterface protocol.
        """
        self.quit_sync()
    
    # Async implementation (called by sync wrapper)
    async def _quit_async(self) -> None:
        """Internal async implementation of quit method"""
        try:
            # Store cookies for sticky session if enabled
            if self.proxy_pool and self.proxy_pool.sticky_session_enabled and self.session_id and hasattr(self, '_proxy_key') and self.context:
                try:
                    cookies = await self.context.cookies()
                    cookies_to_store = {cookie['name']: cookie['value'] for cookie in cookies}
                    if cookies_to_store:
                        self.proxy_pool.store_cookies(self.session_id, self._proxy_key, cookies_to_store)
                        logging.debug(f"Stored {len(cookies_to_store)} cookies from Playwright for session {self.session_id} and proxy {self._proxy_key}")
                except Exception as cookie_error:
                    logging.debug(f"Failed to store cookies from Playwright: {cookie_error}")
            
            # Clean up runtime taint tracking
            if self.runtime_taint_tracker:
                self.runtime_taint_tracker.clear_runtime_data()
                self.runtime_taint_tracker = None
                self.runtime_taint_enabled = False
                self.runtime_taint_flows = []
            
            if self.page:
                await self.page.close()
                self.page = None
            
            if self.context:
                await self.context.close()
                self.context = None
            
            if self.browser:
                await self.browser.close()
                self.browser = None
            
            if self.playwright:
                await self.playwright.stop()
                self.playwright = None
            
            logging.info("PlaywrightJSRenderDriver cleaned up successfully")
            
        except Exception as e:
            logging.error(f"Playwright quit error: {e}")
    
