class ScannerContext:
    """
    Narrow interface for scanner-related dependencies needed by InjectionEngine.
    This avoids tight coupling to the full scanner instance.
    """
    def __init__(self, business_logic_fsm=None, fsm_aware_testing_enabled=True,
                 spa_route_discovery_enabled=True, browser_auth_helper=None):
        self.business_logic_fsm = business_logic_fsm
        self.fsm_aware_testing_enabled = fsm_aware_testing_enabled
        self.spa_route_discovery_enabled = spa_route_discovery_enabled
        self.browser_auth_helper = browser_auth_helper
        self.waf_type = 'generic'  # Issue U8: Store detected WAF type for per-WAF evasion

    def set_waf_type(self, waf_type):
        """
        Update the detected WAF type based on response analysis.

        Args:
            waf_type: Detected WAF type (generic, cloudflare, aws-waf, sucuri)
        """
        self.waf_type = waf_type
        logging.info(f"[WAF] Updated ScannerContext WAF type to: {waf_type}")

