    def _validate_signal_configuration(self):
        """Validate that the signals object has the required attributes for GUI communication."""
        required_signals = ['log', 'finding', 'progress']
        missing_signals = []
        
        for signal_name in required_signals:
            if not hasattr(self.signals, signal_name):
                missing_signals.append(signal_name)
        
        if missing_signals:
            # Only log at debug level - missing signals is acceptable in headless mode
            logging.debug(f"Signals object missing optional signals: {', '.join(missing_signals)}. Running in headless mode.")
            # Don't print warnings - this is expected when running without GUI
        else:
            logging.debug("Signal configuration validated successfully")
        self.confirmed_injection_channels = []
        
        # New feature configurations
