        # Note: DynamicPayloadGenerator and semantic_mutator are already initialized earlier in __init__
        if self.semantic_mutator is not None and self.dynamic_payload_generator is not None:
            self.log("Advanced obfuscation components already initialized")
        else:
            logging.warning("Advanced obfuscation components not available - may affect certain scan features")
        
        # GraphQL advanced features (initialized during GraphQL testing)
