    async def _fuzz_websocket_ping_pong_flood(self, websocket, ws_url):
        """Test Ping/Pong flood for DoS vulnerability"""
        try:
            # Send rapid ping frames to test for DoS
            max_pings = 100  # Limit to avoid actual DoS
            
            start_time = time.time()
            
            # FIX: Fire all pings concurrently without awaiting each one to create true flood effect
            # Collect ping tasks to fire them all at once
            ping_tasks = []
            for i in range(max_pings):
                # Use larger ping data periodically to test fragmentation handling
                if i % 20 == 0:
                    # Large ping data (> 500 bytes) to test fragmentation
                    ping_data = f"ping_{i}" + "A" * 600
                    ping_data = ping_data.encode()
                else:
                    # Normal ping data
                    ping_data = f"ping_{i}".encode()
                
                # Fire ping without awaiting - this creates the flood effect
                ping_tasks.append(websocket.ping(ping_data))
            
            # Wait for all pings to be sent (not necessarily to receive pongs)
            await asyncio.gather(*ping_tasks, return_exceptions=True)
            
            ping_count = max_pings
            
            # Now await the pong queue to handle responses
            # This tests if the server can handle the flood of pings
            try:
                # Try to collect pongs with a timeout
                pong_timeout = 5  # 5 seconds to collect all pongs
                deadline = time.time() + pong_timeout
                pongs_received = 0
                
                while time.time() < deadline and pongs_received < max_pings:
                    try:
                        pong_wait = await asyncio.wait_for(websocket.pong(), timeout=0.5)
                        if pong_wait:
                            pongs_received += 1
                    except asyncio.TimeoutError:
                        # No pong received in this iteration, continue
                        break
                
                # Check if server failed to respond to significant portion of pings
                if pongs_received < max_pings * 0.8:  # If less than 80% pongs received
                    await self._add_vulnerability({
                        "type": "WebSocket Ping/Pong DoS",
                        "url": ws_url,
                        "parameter": "ping_pong",
                        "evidence": f"Server failed to respond to ping flood: {pongs_received}/{max_pings} pongs received",
                        "severity": "Medium",
                        "confidence": 75
                    })
                    
            except Exception as e:
                logging.error(f"Pong collection error: {e}")
            elapsed = time.time() - start_time
            # Dual-condition detection: Measure baseline and compare
            # For WebSocket tests, use a simple baseline approach since we don't have per-endpoint baselines
            # Calculate expected time for normal ping/pong (should be fast)
            expected_time_per_ping = 0.01  # 10ms per ping is reasonable baseline
            expected_total = max_pings * expected_time_per_ping
            # Only flag if significantly slower than expected (3x threshold)
            if elapsed > expected_total * 3:
                await self._add_vulnerability({
                    "type": "WebSocket Ping/Pong Slowdown",
                    "url": ws_url,
                    "parameter": "ping_pong",
                    "evidence": f"Ping/Pong degraded: {ping_count} pings in {elapsed:.2f}s (expected: {expected_total:.2f}s)",
                    "severity": "Low",
                    "confidence": 65
                })
                    
        except Exception as e:
            logging.error(f"WebSocket ping/pong flood error: {e}")
    
