    async def _send_fragmented_websocket_message(self, websocket, fragments, ws_url):
        """Send a fragmented WebSocket message with proper frame structure"""
        try:
            # Access the underlying transport to send raw frames
            # websockets library abstracts frame building, so we need manual approach
            import struct
            
            # Build WebSocket frames manually
            # Frame format: FIN(1) + RSV1(1) + RSV2(1) + RSV3(1) + OPCODE(4) + MASK(1) + PAYLOAD_LEN(7) + MASKING_KEY(32) + PAYLOAD
            
            for i, fragment in enumerate(fragments):
                # Encode fragment as UTF-8
                payload = fragment.encode('utf-8')
                payload_len = len(payload)
                
                # Determine opcode: TEXT for first frame, CONTINUATION for others
                if i == 0:
                    opcode = 0x1  # TEXT frame
                else:
                    opcode = 0x0  # CONTINUATION frame
                
                # Determine FIN bit: 0 for all but last, 1 for last
                fin = 0x80 if i == len(fragments) - 1 else 0x00
                
                # Build frame header
                first_byte = fin | opcode
                
                # Build payload length
                if payload_len < 126:
                    header = struct.pack('!BB', first_byte, 0x80 | payload_len)  # MASK=1
                elif payload_len < 65536:
                    header = struct.pack('!BBH', first_byte, 0x80 | 126, payload_len)  # MASK=1, 16-bit length
                else:
                    header = struct.pack('!BBQ', first_byte, 0x80 | 127, payload_len)  # MASK=1, 64-bit length
                
                # Generate masking key
                masking_key = b'\x00\x00\x00\x00'  # Use zero mask for simplicity
                
                # Mask the payload
                masked_payload = bytes([payload[j] ^ masking_key[j % 4] for j in range(len(payload))])
                
                # Combine header, masking key, and masked payload
                frame = header + masking_key + masked_payload
                
                # Send the frame via the underlying socket
                try:
                    # Access the underlying writer
                    writer = websocket.writer
                    writer.write(frame)
                    await writer.drain()
                except AttributeError:
                    # Fallback: if writer not accessible, use normal send
                    # This won't test fragmentation properly but won't crash
                    await websocket.send(fragment)
                
                # Small delay between fragments
                await asyncio.sleep(0.001)
                
        except Exception as e:
            logging.error(f"Error sending fragmented message: {e}")
            # Fallback to normal send if manual framing fails
            for fragment in fragments:
                await websocket.send(fragment)
    
