    async def _test_graphql_field_suggestion(self, endpoint):
        simple_query = "{ __typename }"
        try:
            resp = await self.injection_engine._async_fetch(endpoint, method='POST', json_data={'query': simple_query});
            status = response_status(resp)
            if resp and status == 200:
                try:
                    data = await self._parse_response_json_async(resp)
                    if 'data' in data and '__typename' in data['data']:
                        typename = data['data']['__typename']
                        if typename in ['Query', 'Mutation', 'Subscription']:
                            vuln = {
                                "type":"GraphQL Field Suggestion - Active Endpoint","url":endpoint,
                                "evidence":f"GraphQL endpoint confirmed with __typename: {typename}",
                                "severity":"Low","confidence":95,"cwe":CWE_MAP["GraphQL"]
                            }
                except (json.JSONDecodeError, KeyError, Exception) as e:
                    logging.exception(f"GraphQL __typename parsing error: {e}")
        except Exception as e:
            logging.error(f"GraphQL field suggestion test error: {e}")
        common_fields = ['users', 'posts', 'products', 'accounts', 'customers', 'orders', 'items', 'admin', 'user', 'post', 'product']
        sensitive_fields = ['email', 'password', 'creditCard', 'ssn', 'apiKey', 'token', 'secret']
        for field in common_fields:
            query = f"{{ {field} {{ id }} }}"
            try:
                resp = await self.injection_engine._async_fetch(endpoint, method='POST', json_data={'query': query});
                status = response_status(resp)
                if resp and status == 200:
                    try:
                        data = await self._parse_response_json_async(resp)
                        if 'data' in data and field in data['data']:
                            for sensitive in sensitive_fields:
                                sensitive_query = f"{{ {field} {{ {sensitive} }} }}"
                                resp_sensitive = await self.injection_engine._async_fetch(endpoint, method='POST', json_data={'query': sensitive_query});
                                status_sensitive = resp_sensitive.get('status') if isinstance(resp_sensitive, dict) else resp_sensitive.status if resp_sensitive else None
                                if resp_sensitive and status_sensitive == 200:
                                    try:
                                        sensitive_data = await self._parse_response_json_async(resp_sensitive)
                                        if 'data' in sensitive_data and field in sensitive_data['data']:
                                            field_data = sensitive_data['data'][field]
                                            if field_data and len(str(field_data)) > 0:
                                                await self._add_vulnerability({
                                                    "type":"GraphQL Field Suggestion - Sensitive Data Leak","url":endpoint,
                                                    "evidence":f"Sensitive field '{sensitive}' accessible in '{field}'",
                                                    "severity":"Critical","confidence":90,"cwe":CWE_MAP["GraphQL"]
                                                })
                                                break
                                    except (json.JSONDecodeError, KeyError, Exception) as e:
                                        logging.exception(f"GraphQL sensitive field parsing error: {e}")
                    except (json.JSONDecodeError, KeyError, Exception) as e:
                        logging.exception(f"GraphQL field response parsing error: {e}")
            except Exception as e:
                logging.error(f"GraphQL field brute-force error for {field}: {e}")
    async def _test_graphql_batching_auth_bypass(self, endpoint):
        auth_token = None
        if hasattr(self, 'session') and self.session:
            if 'Authorization' in self.session.headers:
                auth_header = self.session.headers['Authorization']
                if auth_header.startswith('Bearer '):
                    auth_token = auth_header[7:]
        batch_formats = [
            [
                {"query": "users { id }", "variables": {"id": 1}},
                {"query": "users { id }", "variables": {"id": 2}}
            ],
            {"batch": [
                {"query": "users { id }", "variables": {"id": 1}},
                {"query": "users { id }", "variables": {"id": 2}}
            ]},
            {"query": "users { id }", "variables": {"id": 1}}
        ]
        try:
            for batch_queries in batch_formats:
                headers_no_auth = {}
                resp_no_auth = await self.injection_engine._async_fetch(endpoint, method='POST', json_data=batch_queries, headers=headers_no_auth)
                if auth_token:
                    headers_with_auth = {"Authorization": f"Bearer {auth_token}"}
                    resp_with_auth = await self.injection_engine._async_fetch(endpoint, method='POST', json_data=batch_queries, headers=headers_with_auth)
                    if resp_no_auth and resp_with_auth:
                        no_auth_data = (await resp_no_auth.json()) if resp_no_auth.get('status') == 200 and hasattr(resp_no_auth, 'json') else resp_no_auth.get('_body', '{}') if isinstance(resp_no_auth, dict) else {}
                        with_auth_data = (await resp_with_auth.json()) if resp_with_auth.get('status') == 200 and hasattr(resp_with_auth, 'json') else resp_with_auth.get('_body', '{}') if isinstance(resp_with_auth, dict) else {}
                        if no_auth_data == with_auth_data and len(str(no_auth_data)) > 50:
                            vuln = {
                                "type":"GraphQL Batching Auth Bypass","url":endpoint,
                                "evidence":"Unauthenticated batch query returned same data as authenticated request",
                                "severity":"Critical","confidence":85,"cwe":CWE_MAP["GraphQL"]
                            }
                            break
                if auth_token and isinstance(batch_queries, list):
                    mixed_batch = [
                        {"query": "users { id email }", "variables": {"id": 1}},
                        {"query": "users { id password }", "variables": {"id": 2}}
                    ]
                    resp_mixed = await self.injection_engine._async_fetch(endpoint, method='POST', json_data=mixed_batch, headers=headers_with_auth)
                    if resp_mixed and resp_mixed.get('status') == 200:
                        try:
                            mixed_data = await resp_mixed.json() if hasattr(resp_mixed, 'json') else resp_mixed.get('_body', '{}')
                            mixed_str = str(mixed_data).lower()
                            if 'password' in mixed_str or len(mixed_str) > 100:
                                vuln = {
                                    "type":"GraphQL Batching Mixed Auth Context","url":endpoint,
                                    "evidence":"Batch query may leak sensitive data across auth contexts",
                                    "severity":"High","confidence":75,"cwe":CWE_MAP["GraphQL"]
                                }
                        except (json.JSONDecodeError, KeyError, Exception) as e:
                            logging.exception(f"GraphQL batching mixed auth parsing error: {e}")
        except Exception as e:
            logging.error(f"GraphQL batching auth bypass test error: {e}")
    
