if _is_main_process:
    class JsonSyntaxHighlighter(QSyntaxHighlighter):
        def __init__(self, document):
            QSyntaxHighlighter.__init__(self, document)
            self.highlighting_rules = []
            key_format = QTextCharFormat()
            key_format.setForeground(QBrush(QColor("#569CD6")))
            key_format.setFontWeight(QFont.Bold)
            self.highlighting_rules.append((r'"[^"]*"(?=:)', key_format))
            string_format = QTextCharFormat()
            string_format.setForeground(QBrush(QColor("#CE9178")))
            self.highlighting_rules.append((r':\s*"[^"]*"', string_format))
            number_format = QTextCharFormat()
            number_format.setForeground(QBrush(QColor("#B5CEA8")))
            self.highlighting_rules.append((r':\s*\d+\.?\d*', number_format))
            bool_format = QTextCharFormat()
            bool_format.setForeground(QBrush(QColor("#569CD6")))
            self.highlighting_rules.append((r':\s*(true|false|null)', bool_format))
        def highlightBlock(self, text):
            for pattern, format in self.highlighting_rules:
                import re
                for match in re.finditer(pattern, text):
                    self.setFormat(match.start(), match.end() - match.start(), format)

