        # Check if gray zone tab already exists
        for i in range(self.tabs.count()):
            if isinstance(self.tabs.widget(i), GrayZoneTab):
                gray_zone_tab = self.tabs.widget(i)
                # Update existing tab with current validation engine and reporting engine
                gray_zone_tab.set_validation_engine(getattr(self, 'validation_engine', None))
                gray_zone_tab.reporting_engine = getattr(self, 'reporting_engine', None)
                self.tabs.setCurrentIndex(i)
                return
        
        # Get validation engine and reporting engine if available
        validation_engine = getattr(self, 'validation_engine', None)
