if _is_main_process:
    class ScannerSignals(QObject):
        """Proper PyQt5 signals for thread-safe GUI updates"""
        log_signal = pyqtSignal(str)
        finding_signal = pyqtSignal(dict)
        secret_signal = pyqtSignal(dict)
        progress_signal = pyqtSignal(int, int)

        # Add aliases for backward compatibility with existing code
        @property
        def log(self):
            return self.log_signal

        @property
        def finding(self):
            return self.finding_signal

        @property
        def secret(self):
            return self.secret_signal

if _is_main_process:
    class OmegaDASTGUI(QMainWindow):
        """
        Main GUI window for ULTRA-DAST scanner.
        Provides a user-friendly interface for configuring and running scans.
        """

        def __init__(self):
            super().__init__()
            self.scanner = None
            self.scan_running = False
            self.findings = []
            self.scanner_config = {}
            # Create proper PyQt5 signals object
            self.signals = ScannerSignals()
            # Connect signals to GUI update methods
            self.signals.log_signal.connect(self.log)
            self.signals.finding_signal.connect(self.add_finding)
            self.signals.secret_signal.connect(self.add_secret)
            self.signals.progress_signal.connect(self.update_progress)
            # Setup UI first to create all widgets
            self.setup_ui()
            # Load config from config.json on startup after UI is ready
            self.load_config_from_file()

